    @staticmethod
    def _templateSupportArchRows(targetFdi: str) -> tuple[list[str], list[str]]:
        quadrant = targetFdi[:1]
        if quadrant in {"1", "2"}:
            return (
                [f"1{number}" for number in range(8, 0, -1)],
                [f"2{number}" for number in range(8, 0, -1)],
            )
        if quadrant in {"3", "4"}:
            return (
                [f"4{number}" for number in range(8, 0, -1)],
                [f"3{number}" for number in range(8, 0, -1)],
            )
        return ([], [])

    @staticmethod
    def _templateSupportToothIcon(color: qt.QColor) -> qt.QIcon:
        pixmap = qt.QPixmap(26, 30)
        pixmap.fill(qt.Qt.transparent)
        painter = qt.QPainter(pixmap)
        painter.setRenderHint(qt.QPainter.Antialiasing, True)
        pen = qt.QPen(color)
        pen.setWidth(2)
        painter.setPen(pen)
        painter.setBrush(qt.QBrush(color.lighter(165)))
        painter.drawRoundedRect(qt.QRectF(4.0, 2.0, 18.0, 16.0), 5.0, 5.0)
        painter.drawLine(9, 17, 8, 28)
        painter.drawLine(17, 17, 18, 28)
        painter.end()
        return qt.QIcon(pixmap)

    def _clearTemplateSupportArchButtons(self) -> None:
        layout = self._templateSupportArchGridLayout
        if not layout:
            return
        while self._qtLayoutCount(layout):
            item = layout.takeAt(0)
            widget = item.widget() if item and hasattr(item, "widget") else None
            if widget:
                widget.deleteLater()
        self._templateSupportButtonsBySegmentId.clear()

    def _rebuildTemplateSupportArchSelector(
        self,
        targetRecord: dict | None,
        availableRecords: list[dict],
        selectedSupportIds: list[str],
    ) -> None:
        self._clearTemplateSupportArchButtons()
        if not targetRecord:
            self._templateSupportArchStatusLabel.text = _(
                "Select a Step 4A target tooth to show its jaw."
            )
            self._templateSupportArchStatusLabel.styleSheet = "color: #b36b00;"
            return
        targetFdi = str(targetRecord.get("fdiNumber") or "")
        rows = self._templateSupportArchRows(targetFdi)
        recordsByFdi = {
            str(record.get("fdiNumber") or ""): record
            for record in availableRecords
            if record.get("fdiNumber")
        }
        recordsByFdi[targetFdi] = targetRecord
        selectedIds = set(selectedSupportIds)
        targetColor = qt.QColor("#F0A020")
        supportColor = qt.QColor("#258B8B")
        availableColor = qt.QColor("#6D7882")
        missingColor = qt.QColor("#B8BEC4")
        for rowIndex, fdiRow in enumerate(rows):
            for columnIndex, fdiNumber in enumerate(fdiRow):
                record = recordsByFdi.get(fdiNumber)
                isTarget = fdiNumber == targetFdi
                isAvailable = bool(record)
                segmentId = record["segmentId"] if record else ""
                selected = bool(segmentId and segmentId in selectedIds)
                button = qt.QToolButton(self._templateSupportArchWidget)
                button.objectName = f"templateSupportToothFdi{fdiNumber}Button"
                button.text = fdiNumber
                button.toolButtonStyle = qt.Qt.ToolButtonTextUnderIcon
                button.iconSize = qt.QSize(24, 28)
                button.setMinimumSize(38, 52)
                button.checkable = bool(isAvailable)
                button.checked = bool(selected or isTarget)
                button.enabled = bool(isAvailable and not isTarget)
                iconColor = (
                    targetColor
                    if isTarget
                    else supportColor
                    if selected
                    else availableColor
                    if isAvailable
                    else missingColor
                )
                button.icon = self._templateSupportToothIcon(iconColor)
                if isTarget:
                    button.toolTip = _(
                        "FDI %1 — TARGET TOOTH. Always included and locked."
                    ).replace("%1", fdiNumber)
                    button.styleSheet = (
                        "QToolButton { background: #FFE6B5; border: 2px solid "
                        "#F0A020; border-radius: 6px; font-weight: 700; }"
                    )
                elif isAvailable:
                    button.toolTip = _(
                        "FDI %1 — click to toggle this same-jaw support tooth."
                    ).replace("%1", fdiNumber)
                    button.styleSheet = (
                        "QToolButton { border: 1px solid #8A949C; border-radius: 6px; } "
                        "QToolButton:checked { background: #CDEFEF; border: 2px solid "
                        "#258B8B; font-weight: 700; }"
                    )
                    button.connect(
                        "toggled(bool)",
                        lambda checked, supportId=segmentId: (
                            self.onTemplateSupportArchButtonToggled(
                                supportId,
                                checked,
                            )
                        ),
                    )
                    self._templateSupportButtonsBySegmentId[segmentId] = button
                else:
                    button.toolTip = _(
                        "FDI %1 is not present as a whole-tooth segment."
                    ).replace("%1", fdiNumber)
                    button.styleSheet = (
                        "QToolButton { color: #999999; border: 1px dashed #BBBBBB; "
                        "border-radius: 6px; }"
                    )
                self._templateSupportArchGridLayout.addWidget(
                    button,
                    rowIndex,
                    columnIndex,
                )
        jawName = _("upper") if targetFdi[:1] in {"1", "2"} else _("lower")
        self._templateSupportArchStatusLabel.text = _(
            "%1 jaw only • target FDI %2 is fixed • %3 support tooth/teeth selected."
        ).replace("%1", jawName.capitalize()).replace(
            "%2", targetFdi
        ).replace("%3", str(len(selectedIds)))
        self._templateSupportArchStatusLabel.styleSheet = "color: #207227;"

    def onTemplateSupportArchButtonToggled(
        self,
        segmentId: str,
        checked: bool,
    ) -> None:
        if self._updatingTemplateUI:
            return
        listWidget = self.ui.templateSupportTeethListWidget
        for itemIndex in range(listWidget.count):
            item = listWidget.item(itemIndex)
            if str(item.data(qt.Qt.UserRole) or "") == str(segmentId):
                item.setCheckState(qt.Qt.Checked if checked else qt.Qt.Unchecked)
                return

    def _robotJointPositionsSi(self) -> dict[str, float]:
        if not self._parameterNode:
            return joint_positions_si_from_display(0, 0, 0, 0, 0, 0)
        return joint_positions_si_from_display(
            self._parameterNode.robotJoint1Deg,
            self._parameterNode.robotJoint2Mm,
            self._parameterNode.robotJoint3Deg,
            self._parameterNode.robotJoint4Mm,
            self._parameterNode.robotJoint5Deg,
            self._parameterNode.robotJoint6Deg,
        )

    def _setupRobotKeyboardShortcuts(self) -> None:
        """Create disabled shortcuts; Step 6 and the explicit toggle gate them."""

        if self._robotKeyboardShortcuts:
            return
        bindings = (
            ("Left", 0, None, -1.0),
            ("Right", 0, None, 1.0),
            ("Down", 1, None, -1.0),
            ("Up", 1, None, 1.0),
            ("PgDown", 2, None, -1.0),
            ("PgUp", 2, None, 1.0),
            ("Shift+Down", None, 0, -1.0),
            ("Shift+Up", None, 0, 1.0),
            ("Shift+Left", None, 2, -1.0),
            ("Shift+Right", None, 2, 1.0),
        )
        parent = slicer.util.mainWindow() or self.parent
        for keySequence, translationAxis, rotationAxis, direction in bindings:
            shortcut = qt.QShortcut(qt.QKeySequence(keySequence), parent)
            shortcut.objectName = f"robotNudgeShortcut{keySequence.replace('+', '')}"
            shortcut.context = qt.Qt.ApplicationShortcut
            shortcut.enabled = False
            shortcut.connect(
                "activated()",
                lambda ta=translationAxis, ra=rotationAxis, d=direction:
                    self._onRobotKeyboardNudge(ta, ra, d),
            )
            self._robotKeyboardShortcuts.append(shortcut)

    def _disableRobotKeyboardShortcuts(self) -> None:
        for shortcut in self._robotKeyboardShortcuts:
            shortcut.enabled = False

    def _updateRobotKeyboardShortcutState(self) -> None:
        if not hasattr(self, "ui"):
            return
        stageEntries = self._workflowStageEntries()
        robotStageActive = bool(
            stageEntries
            and int(self.ui.workflowStageComboBox.currentIndex)
            == len(stageEntries) - 1
        )
        enabled = bool(
            robotStageActive
            and self._parameterNode
            and not self._parameterNode.robotBaseMountLocked
            and self._parameterNode.robotKeyboardNudgeEnabled
            and self.logic
            and self.logic.isRobotBaseTransformNode(
                self._parameterNode.robotBaseTransform
            )
        )
        for shortcut in self._robotKeyboardShortcuts:
            shortcut.enabled = enabled
        self._setRobotTransformInteractionVisible(robotStageActive)

    def _onRobotKeyboardNudge(
        self,
        translationAxis: int | None,
        rotationAxis: int | None,
        direction: float,
    ) -> None:
        focusWidget = qt.QApplication.focusWidget()
        if focusWidget and (
            focusWidget.inherits("QAbstractSpinBox")
            or focusWidget.inherits("QLineEdit")
            or focusWidget.inherits("QTextEdit")
        ):
            return
        self._nudgeRobotBase(translationAxis, rotationAxis, direction)

    def _setRobotTransformInteractionVisible(self, visible: bool) -> None:
        if not self.logic:
            return
        baseTransform = (
            self._parameterNode.robotBaseTransform if self._parameterNode else None
        )
        planeNode = self._parameterNode.robotMountPlane if self._parameterNode else None
        if self.logic.isRobotBaseTransformNode(baseTransform):
            baseTransform.CreateDefaultDisplayNodes()
            displayNode = baseTransform.GetDisplayNode()
            if displayNode:
                for methodName, value in (
                    ("SetEditorVisibility", bool(visible)),
                    ("SetHandlesInteractive", bool(visible)),
                    ("SetTranslationHandleVisibility", bool(visible)),
                    ("SetRotationHandleVisibility", bool(visible)),
                    ("SetScaleHandleVisibility", False),
                ):
                    method = getattr(displayNode, methodName, None)
                    if method:
                        method(value)
        if self.logic.isRobotMountPlaneNode(planeNode):
            planeNode.CreateDefaultDisplayNodes()
            displayNode = planeNode.GetDisplayNode()
            if displayNode:
                displayNode.SetHandlesInteractive(bool(visible))
                displayNode.SetTranslationHandleVisibility(bool(visible))
                displayNode.SetRotationHandleVisibility(bool(visible))
                displayNode.SetScaleHandleVisibility(False)

    def _bindRobotPlacementNodes(self, baseTransform, planeNode) -> None:
        if self._robotBaseTransformNode is not baseTransform:
            if self._robotBaseTransformNode:
                self.removeObserver(
                    self._robotBaseTransformNode,
                    vtk.vtkCommand.ModifiedEvent,
                    self._onRobotPlacementNodeModified,
                )
            self._robotBaseTransformNode = baseTransform
            if baseTransform:
                self.addObserver(
                    baseTransform,
                    vtk.vtkCommand.ModifiedEvent,
                    self._onRobotPlacementNodeModified,
                )
        if self._robotMountPlaneNode is not planeNode:
            if self._robotMountPlaneNode:
                self.removeObserver(
                    self._robotMountPlaneNode,
                    vtk.vtkCommand.ModifiedEvent,
                    self._onRobotPlacementNodeModified,
                )
            self._robotMountPlaneNode = planeNode
            if planeNode:
                self.addObserver(
                    planeNode,
                    vtk.vtkCommand.ModifiedEvent,
                    self._onRobotPlacementNodeModified,
                )

    def _onRobotPlacementNodeModified(self, caller=None, event=None) -> None:
        del event
        if self._updatingRobotPlacementUI:
            return
        if (
            self.logic
            and self._parameterNode
            and caller is self._parameterNode.robotBaseTransform
        ):
            workspace = self.logic.robotWorkspaceModelNode()
            if workspace:
                workspace.SetAttribute("DENTOBOT.WorkspaceState", "Stale")
                self.ui.robotWorkspaceStatusLabel.text = _(
                    "Base placement changed. Regenerate before interpreting the "
                    "collision-filtered workspace."
                )
                self.ui.robotWorkspaceStatusLabel.styleSheet = "color: #b36b00;"
        self._updateRobotPlacementStatus()

    def _updateRobotPlacementStatus(self, message: str = "") -> None:
        if not self._parameterNode or not self.logic:
            return
        baseTransform = self._parameterNode.robotBaseTransform
        modelCount = len(self.logic.robotModelNodes())
        if message:
            status = message
            style = "color: #207227;"
        elif self.logic.isRos2MotionControlActive(baseTransform):
            status = _("ROS robot is in the viewport. Place the mount, then lock.")
            style = "color: #207227;"
        elif not self.logic.isRobotBaseTransformNode(baseTransform) or modelCount != 7:
            status = _("Choose a scene in 6.0, then load the ROS robot in 6.1.")
            style = "color: #b36b00;"
        else:
            matrix = vtk.vtkMatrix4x4()
            baseTransform.GetMatrixTransformToWorld(matrix)
            origin = tuple(matrix.GetElement(axis, 3) for axis in range(3))
            status = _(
                "Robot loaded (%1/7 links). Base RAS: X %2, Y %3, Z %4 mm."
            ).replace("%1", str(modelCount)).replace(
                "%2", f"{origin[0]:.2f}"
            ).replace("%3", f"{origin[1]:.2f}").replace(
                "%4", f"{origin[2]:.2f}"
            )
            style = "color: #207227;"
        self.ui.robotPlacementStatusLabel.text = status
        self.ui.robotPlacementStatusLabel.styleSheet = style

    def _updateRobotPlacement(self) -> None:
        if not self._parameterNode or not self.logic or not hasattr(self, "ui"):
            return
        baseTransform = self._parameterNode.robotBaseTransform
        planeNode = self._parameterNode.robotMountPlane
        self._bindRobotPlacementNodes(baseTransform, planeNode)
        baseValid = self.logic.isRobotBaseTransformNode(baseTransform)
        planeValid = self.logic.isRobotMountPlaneNode(planeNode)
        modelCount = len(self.logic.robotModelNodes())
        stageEntries = self._workflowStageEntries()
        robotStageActive = bool(
            stageEntries
            and int(self.ui.workflowStageComboBox.currentIndex)
            == len(stageEntries) - 1
        )
        if baseValid and modelCount:
            self.logic.updateRobotJointPoses(self._robotJointPositionsSi())
        self._updatingRobotPlacementUI = True
        try:
            for button in (
                self.ui.snapRobotBaseToPlaneButton,
                self.ui.frameRobotButton,
                self.ui.resetRobotJointsButton,
                self.ui.resetRobotBaseButton,
                self.ui.deleteRobotSetupButton,
                self.ui.robotXMinusButton,
                self.ui.robotXPlusButton,
                self.ui.robotYMinusButton,
                self.ui.robotYPlusButton,
                self.ui.robotZMinusButton,
                self.ui.robotZPlusButton,
                self.ui.robotRxMinusButton,
                self.ui.robotRxPlusButton,
                self.ui.robotRyMinusButton,
                self.ui.robotRyPlusButton,
                self.ui.robotRzMinusButton,
                self.ui.robotRzPlusButton,
            ):
                button.enabled = baseValid
            self.ui.snapRobotBaseToPlaneButton.enabled = baseValid and planeValid
            self.ui.flipRobotMountPlaneButton.enabled = planeValid
            self.ui.robotKeyboardNudgeCheckBox.enabled = baseValid
            phantomLoaded = bool(
                self._parameterNode.draftPhantomSkullModel
                and self._parameterNode.draftPhantomMandibleModel
            )
            self.ui.frameRobotButton.enabled = bool(
                modelCount or self.logic.draftPhantomModelNodes()
            )
            self.ui.deleteDraftPhantomButton.enabled = bool(
                self.logic.draftPhantomModelNodes()
            )
            self._updateDraftJawLandmarkControls(phantomLoaded=phantomLoaded)
            self.ui.resetDraftJawButton.enabled = self.logic.isDraftJawTransformNode(
                self._parameterNode.draftJawTransform
            )
        finally:
            self._updatingRobotPlacementUI = False
        self._updateRobotPlacementStatus()
        self._updateDraftPhantomStatus()
        self._updateRos2MotionControlStatus()
        self._updateRobotKeyboardShortcutState()
        if self._parameterNode and self.logic:
            if self._parameterNode.robotBaseMountLocked:
                self.logic.setRobotBaseMountLocked(self._parameterNode, True)
            try:
                self._applyTaskJointLimitsToJointSpinboxes()
            except ValueError:
                pass
        self._updateStep6PlanningUi()
        if robotStageActive:
            self._updateWorkflowViewControls()

    def _updateRos2MotionControlStatus(self, message: str = "") -> None:
        if not hasattr(self, "ui"):
            return
        base_transform = (
            self._parameterNode.robotBaseTransform if self._parameterNode else None
        )
        ros2_active = (
            self.logic.isRos2MotionControlActive(base_transform)
            if self.logic and base_transform
            else False
        )
        stage_entries = self._workflowStageEntries()
        step6_stage_active = bool(
            stage_entries
            and int(self.ui.workflowStageComboBox.currentIndex)
            == len(stage_entries) - 1
        )
        if message:
            status = message
            style = "color: #c62828;" if "failed" in message.lower() else "color: #207227;"
        elif not ros2_active and not step6_stage_active:
            status = _(
                "ROS 2 / MoveIt is inactive for this workflow stage. It is "
                "created in the MRML scene only when Step 6 is opened or Connect is used."
            )
            style = "color: #666666;"
        elif ros2_active:
            guard_status = joint_command_status()
            if guard_status is not None and not guard_status.accepted:
                pair = ""
                if guard_status.first_body or guard_status.second_body:
                    pair = " (%s ↔ %s)" % (
                        guard_status.first_body or "?",
                        guard_status.second_body or "?",
                    )
                self.ui.ros2MotionControlStatusLabel.text = _(
                    "Collision guard rejected the last manual move: %1%2"
                ).replace("%1", guard_status.reason).replace("%2", pair)
                self.ui.ros2MotionControlStatusLabel.styleSheet = "color: #c62828;"
                self._updateStep6PlanningUi()
                return
            ok, nodes, _cli = ros2_node_list()
            slicer_present = ok and ROS2_DEFAULT_SLICER_NODE in {
                name.lstrip("/") for name in nodes
            }
            if slicer_present:
                status = _(
                    "ROS 2 motion control is active. /slicer is present. "
                    "MRML link meshes are hidden while the SlicerROS2 robot "
                    "follows /joint_states."
                )
            else:
                status = _(
                    "ROS 2 motion control is marked active but /slicer was not "
                    "found. Reload DENTO Workflow."
                )
            style = "color: #207227;" if slicer_present else "color: #c62828;"
        else:
            stack_running, stack_hint = description_stack_running()
            if stack_running:
                status = _(
                    "The external DENTOBOT description + MoveIt stack is ready. "
                    "Connect to load the robot in SlicerROS2 Motion Control."
                )
            else:
                status = _(
                    "The external ROS 2 + MoveIt simulation stack is not ready. "
                    "Restart Slicer with Workspace/scripts/launch-dentoworkflow.bash."
                )
                if stack_hint:
                    status = f"{status} ({stack_hint})"
            style = "color: #b36b00;"
        self.ui.ros2MotionControlStatusLabel.text = status
        self.ui.ros2MotionControlStatusLabel.styleSheet = style
        self._updateStep6PlanningUi()

    def onConnectRos2MotionControl(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        if self._step6SceneKind() not in {"case", "phantom"}:
            slicer.util.errorDisplay(
                _("Choose a Step 6 scene before connecting the ROS robot."),
            )
            return
        try:
            base_transform = self.logic.ensureRobotBaseTransform(
                self._parameterNode.robotBaseTransform,
            )
            self._parameterNode.robotBaseTransform = base_transform
            phantom_models = self.logic.draftPhantomModelNodes()
            if phantom_models:
                self.logic.positionRobotBaseNearResearchPhantom(
                    base_transform,
                    phantom_models,
                )
            mrml_models = self.logic.robotModelNodes()
            robot_node, error = connect_dentobot_motion_control(
                base_transform,
                hide_mrml_robot=bool(mrml_models),
                mrml_robot_models=mrml_models,
                open_motion_module=True,
                start_stack_if_needed=False,
            )
            if error or robot_node is None:
                if is_ros2_runtime_unavailable_message(error or ""):
                    if slicer.util.confirmYesNoDisplay(
                        (error or "")
                        + "\n\n"
                        + _(
                            "Load the local URDF robot in MRML instead so you "
                            "can place and lock it?"
                        )
                    ):
                        self.onLoadRobotModel()
                        self._updateRos2MotionControlStatus(
                            _(
                                "ROS2 module missing; loaded the MRML robot "
                                "fallback."
                            )
                        )
                        return
                raise RuntimeError(error or _("ROS 2 robot node was not created."))
            self._updateRobotPlacement()
            self._applyStep6RecommendedView()
            self._updateRos2MotionControlStatus(
                _(
                    "Connected SlicerROS2 robot with plan-only MoveIt Motion "
                    "Control. The self-collision guard is active; lock the "
                    "placed base to sync head/case collision surfaces."
                )
            )
        except (RuntimeError, ValueError, OSError) as exc:
            self._updateRos2MotionControlStatus(
                _("ROS 2 connect failed: %1").replace("%1", str(exc))
            )
            slicer.util.errorDisplay(str(exc))

    def onDisconnectRos2MotionControl(self, checked: bool = False) -> None:
        del checked
        if not self.logic:
            return
        try:
            ok, message = disconnect_dentobot_motion_control(
                self.logic.robotModelNodes(),
            )
            if not ok:
                raise RuntimeError(message)
            self._updateRobotPlacement()
            self._updateRos2MotionControlStatus(
                _("Disconnected ROS 2 robot; MRML link meshes restored.")
            )
        except (RuntimeError, ValueError, OSError) as exc:
            self._updateRos2MotionControlStatus(
                _("ROS 2 disconnect failed: %1").replace("%1", str(exc))
            )
            slicer.util.errorDisplay(str(exc))

    def _clearRobotPlacement(self) -> None:
        if not hasattr(self, "ui"):
            return
        self._bindRobotPlacementNodes(None, None)
        self._disableRobotKeyboardShortcuts()
        self._updatingRobotPlacementUI = True
        try:
            self.ui.robotBaseTransformSelector.setCurrentNode(None)
            self.ui.robotMountPlaneSelector.setCurrentNode(None)
            self.ui.robotPlacementStatusLabel.text = _(
                "Load the seven articulated robot meshes to begin placement."
            )
            self.ui.robotPlacementStatusLabel.styleSheet = "color: #b36b00;"
        finally:
            self._updatingRobotPlacementUI = False

    def _updateDraftPhantomStatus(self, message: str = "", error: bool = False) -> None:
        if not hasattr(self, "ui") or not self._parameterNode or not self.logic:
            return
        if message:
            self.ui.draftOpenMouthStatusLabel.text = message
            self.ui.draftOpenMouthStatusLabel.styleSheet = (
                "color: #b00020;" if error else "color: #207227;"
            )
            return
        transform = self._parameterNode.draftJawTransform
        if self.logic.isDraftJawTransformNode(transform):
            angle = transform.GetAttribute("DENTOBOT.HingeAngleDeg") or "--"
            gap = transform.GetAttribute("DENTOBOT.AchievedIncisorGapMm") or "--"
            self.ui.draftOpenMouthStatusLabel.text = _(
                "Draft mouth open: pure TMJ hinge rotation %1°, measured incisor gap %2 mm."
            ).replace("%1", angle).replace("%2", gap)
            self.ui.draftOpenMouthStatusLabel.styleSheet = "color: #207227;"
        elif self.logic.draftPhantomModelNodes():
            pointCount = (
                self._parameterNode.draftJawLandmarks.GetNumberOfDefinedControlPoints()
                if self.logic.isDraftJawLandmarksNode(
                    self._parameterNode.draftJawLandmarks
                )
                else 0
            )
            self.ui.draftOpenMouthStatusLabel.text = _(
                "Draft phantom loaded. Jaw landmarks placed: %1/4."
            ).replace("%1", str(pointCount))
            self.ui.draftOpenMouthStatusLabel.styleSheet = "color: #b36b00;"
        else:
            self.ui.draftOpenMouthStatusLabel.text = _(
                "Load the local generic phantom to begin."
            )
            self.ui.draftOpenMouthStatusLabel.styleSheet = "color: #b36b00;"

    def onLoadRobotModel(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        if self._step6SceneKind() not in {"case", "phantom"}:
            slicer.util.errorDisplay(
                _("Choose a Step 6 scene before loading the MRML robot fallback."),
            )
            return
        try:
            baseTransform, models = self.logic.createOrUpdateRobotPlacement(
                self._parameterNode.robotBaseTransform,
                self._robotJointPositionsSi(),
            )
            self._parameterNode.robotBaseTransform = baseTransform
            self._updateRobotPlacement()
            if self.logic.draftPhantomModelNodes():
                self.logic.positionRobotBaseNearResearchPhantom(
                    baseTransform,
                    self.logic.draftPhantomModelNodes(),
                )
            self.onFrameStep6ResearchWorkspace()
            self._applyStep6RecommendedView()
            self._updateRobotPlacementStatus(
                _("Loaded/reused %1 robot links. Drag the base handles or mount plane.")
                .replace("%1", str(len(models)))
            )
        except (RuntimeError, ValueError, OSError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onLoadDraftPhantom(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        if not self._confirmStep6SceneSwitch("phantom"):
            return
        if self._parameterNode.step6PlanningContextImported:
            self._parameterNode.step6PlanningContextImported = False
        try:
            skull, mandible, models = self.logic.createOrUpdateDraftPhantom()
            self._parameterNode.draftPhantomSkullModel = skull
            self._parameterNode.draftPhantomMandibleModel = mandible
            self.onFrameStep6ResearchWorkspace()
            if self.logic.isRobotBaseTransformNode(
                self._parameterNode.robotBaseTransform
            ):
                self.logic.positionRobotBaseNearResearchPhantom(
                    self._parameterNode.robotBaseTransform,
                    models,
                )
            self._updateRobotPlacement()
            self._applyStep6RecommendedView()
            self._updateDraftPhantomStatus(
                _(
                    "Loaded generic BodyParts3D neurocranium, maxilla, and mandible. "
                    "Place the first jaw landmark next."
                )
            )
        except (RuntimeError, ValueError, OSError) as exc:
            self._updateDraftPhantomStatus(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onCreateDraftJawLandmarks(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            node = self.logic.ensureDraftJawLandmarksNode(
                self._parameterNode.draftJawLandmarks
            )
            self._parameterNode.draftJawLandmarks = node
            self._bindDraftJawLandmarksNode(node)
            summary = self.logic.getDraftJawLandmarkSummary(node)
            if summary["isComplete"]:
                return
            self.logic.startDraftJawLandmarkPlacement(node)
            self._updateRobotPlacement()
            landmarkIndex = summary["definedPointCount"]
            placementHints = self.logic.draftJawLandmarkPlacementHints()
            self._updateDraftPhantomStatus(
                _(
                    "Click one point in a 3D view for %1, then pan to the next "
                    "landmark and press the button again."
                ).replace("%1", placementHints[landmarkIndex])
            )
        except (RuntimeError, ValueError) as exc:
            self._updateDraftPhantomStatus(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onClearDraftJawLandmarks(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        node = self._parameterNode.draftJawLandmarks
        if not self.logic.isDraftJawLandmarksNode(node):
            return
        if node.GetNumberOfDefinedControlPoints() == 0:
            return
        try:
            self.logic.stopTrajectoryPlacement()
            self.logic.resetDraftJawOpening(
                self._parameterNode.draftPhantomMandibleModel,
                self._parameterNode.draftJawTransform,
                self._parameterNode.draftJawGapLine,
            )
            self._parameterNode.draftJawGapLine = None
            self.logic.clearDraftJawLandmarks(node)
            self._updateRobotPlacement()
            self._updateDraftPhantomStatus(
                _("Draft jaw landmarks cleared. Place the first landmark next.")
            )
        except (RuntimeError, ValueError) as exc:
            self._updateDraftPhantomStatus(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def _bindDraftJawLandmarksNode(
        self,
        landmarksNode: vtkMRMLMarkupsFiducialNode | None,
    ) -> None:
        if landmarksNode is self._draftJawLandmarksNode:
            return
        if self._draftJawLandmarksNode:
            for landmarkEvent in (
                vtk.vtkCommand.ModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointPositionDefinedEvent,
                slicer.vtkMRMLMarkupsNode.PointModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointRemovedEvent,
            ):
                self.removeObserver(
                    self._draftJawLandmarksNode,
                    landmarkEvent,
                    self._onDraftJawLandmarksModified,
                )
        self._draftJawLandmarksNode = landmarksNode
        if landmarksNode:
            for landmarkEvent in (
                vtk.vtkCommand.ModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointPositionDefinedEvent,
                slicer.vtkMRMLMarkupsNode.PointModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointRemovedEvent,
            ):
                self.addObserver(
                    landmarksNode,
                    landmarkEvent,
                    self._onDraftJawLandmarksModified,
                )

    def _onDraftJawLandmarksModified(self, caller=None, event=None) -> None:
        del caller, event
        if not self._parameterNode or not self.logic:
            return
        node = self._draftJawLandmarksNode
        if not node or not self.logic.isDraftJawLandmarksNode(node):
            return
        try:
            summary = self.logic.getDraftJawLandmarkSummary(node)
        except ValueError:
            return
        pointCount = summary["definedPointCount"]
        if pointCount >= 4:
            self.logic.stopTrajectoryPlacement()
            if not self.logic.isDraftJawTransformNode(
                self._parameterNode.draftJawTransform
            ):
                try:
                    self.onApplyDraftJawOpening()
                except (RuntimeError, ValueError) as exc:
                    self._updateDraftPhantomStatus(str(exc), error=True)
                    slicer.util.errorDisplay(str(exc))
        self._updateDraftJawLandmarkControls()
        if pointCount < 4:
            self._updateDraftPhantomStatus()

    def _updateDraftJawLandmarkControls(self, phantomLoaded: bool | None = None) -> None:
        if not hasattr(self, "ui") or not self._parameterNode or not self.logic:
            return
        if phantomLoaded is None:
            phantomLoaded = bool(
                self._parameterNode.draftPhantomSkullModel
                and self._parameterNode.draftPhantomMandibleModel
            )
        node = self._parameterNode.draftJawLandmarks
        summary = None
        if node and self.logic.isDraftJawLandmarksNode(node):
            try:
                summary = self.logic.getDraftJawLandmarkSummary(node)
            except ValueError:
                summary = None
        pointCount = summary["definedPointCount"] if summary else 0
        isComplete = bool(summary and summary["isComplete"])
        buttonLabels = self.logic.draftJawLandmarkButtonLabels()
        self._updatingRobotPlacementUI = True
        try:
            self.ui.createDraftJawLandmarksButton.enabled = bool(
                phantomLoaded and not isComplete
            )
            self.ui.createDraftJawLandmarksButton.text = (
                buttonLabels[pointCount]
                if pointCount < len(buttonLabels)
                else _("All landmarks placed")
            )
            self.ui.clearDraftJawLandmarksButton.enabled = bool(
                phantomLoaded and pointCount > 0
            )
            self.ui.applyDraftJawOpeningButton.enabled = bool(
                phantomLoaded and isComplete
            )
        finally:
            self._updatingRobotPlacementUI = False

    def onApplyDraftJawOpening(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            transform, gapLine, summary = self.logic.createOrUpdateDraftJawOpening(
                self._parameterNode.draftPhantomMandibleModel,
                self._parameterNode.draftJawLandmarks,
                self._parameterNode.draftJawTransform,
                self._parameterNode.draftJawGapLine,
                self._parameterNode.draftJawTargetGapMm,
            )
            self._parameterNode.draftJawTransform = transform
            self._parameterNode.draftJawGapLine = gapLine
            self._updateRobotPlacement()
            self._updateDraftPhantomStatus(
                _(
                    "Draft mouth opened by pure TMJ hinge rotation %1°; measured "
                    "incisor gap %2 mm."
                )
                .replace("%1", f"{summary['angleDeg']:.2f}")
                .replace("%2", f"{summary['gapMm']:.2f}")
            )
        except (RuntimeError, ValueError) as exc:
            self._updateDraftPhantomStatus(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onResetDraftJaw(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        self.logic.resetDraftJawOpening(
            self._parameterNode.draftPhantomMandibleModel,
            self._parameterNode.draftJawTransform,
            self._parameterNode.draftJawGapLine,
        )
        self._parameterNode.draftJawGapLine = None
        self._updateRobotPlacement()
        self._updateDraftPhantomStatus(_("Draft mandible reset to the closed source pose."))

    def onDeleteDraftPhantom(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        removed = self.logic.deleteDraftPhantom(
            self._parameterNode.draftJawLandmarks,
            self._parameterNode.draftJawTransform,
            self._parameterNode.draftJawGapLine,
        )
        wasModifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.draftPhantomSkullModel = None
            self._parameterNode.draftPhantomMandibleModel = None
            self._parameterNode.draftJawLandmarks = None
            self._parameterNode.draftJawTransform = None
            self._parameterNode.draftJawGapLine = None
        finally:
            self._parameterNode.EndModify(wasModifying)
        self._bindDraftJawLandmarksNode(None)
        self._updateRobotPlacement()
        logging.info("Deleted %d disposable draft phantom nodes", len(removed))

    def onCreateRobotMountPlane(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            planeNode = self.logic.createOrResetRobotMountPlane(
                self._parameterNode.robotMountPlane,
                self._parameterNode.robotBaseTransform,
            )
            self._parameterNode.robotMountPlane = planeNode
            try:
                slicer.modules.markups.logic().SetActiveListID(planeNode)
            except Exception:
                logging.debug("Could not make the robot mount plane active.")
            self._updateRobotPlacement()
            self._updateRobotPlacementStatus(
                _("Mount plane ready. Drag its handles, then click Snap Base to Plane.")
            )
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onSnapRobotBaseToPlane(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            self.logic.snapRobotBaseToPlane(
                self._parameterNode.robotBaseTransform,
                self._parameterNode.robotMountPlane,
            )
            self._updateRobotPlacementStatus(
                _("Robot base snapped to the mount-plane origin and orientation.")
            )
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onFlipRobotMountPlane(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        planeNode = self._parameterNode.robotMountPlane
        if not self.logic.isRobotMountPlaneNode(planeNode):
            return
        normal = np.asarray(planeNode.GetNormalWorld(), dtype=float)
        planeNode.SetNormalWorld(tuple(float(value) for value in -normal))
        self._updateRobotPlacementStatus(_("Mount-plane normal flipped."))

    def _nudgeRobotBase(
        self,
        translationAxis: int | None,
        rotationAxis: int | None,
        direction: float,
    ) -> None:
        if not self._parameterNode or not self.logic:
            return
        if self._parameterNode.robotBaseMountLocked:
            return
        translation = [0.0, 0.0, 0.0]
        rotation = [0.0, 0.0, 0.0]
        if translationAxis is not None:
            translation[translationAxis] = (
                float(direction) * self._parameterNode.robotTranslationStepMm
            )
        if rotationAxis is not None:
            rotation[rotationAxis] = (
                float(direction) * self._parameterNode.robotRotationStepDeg
            )
        try:
            self.logic.nudgeRobotBase(
                self._parameterNode.robotBaseTransform,
                translationLocalMm=tuple(translation),
                rotationLocalDeg=tuple(rotation),
            )
            self._updateRobotPlacementStatus()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onRobotJointValueChanged(self, value: float) -> None:
        del value
        if self._updatingRobotPlacementUI or not self._parameterNode or not self.logic:
            return
        positions = self._robotJointPositionsSi()
        if self.logic.isRos2MotionControlActive(
            self._parameterNode.robotBaseTransform
        ):
            ok, message = apply_joint_positions_si_to_motion_control(positions)
            if not ok:
                accepted = last_accepted_joint_positions_si()
                if accepted:
                    self._updatingRobotPlacementUI = True
                    try:
                        self._setRobotJointsFromSi(
                            accepted,
                            publish_to_ros=False,
                        )
                    finally:
                        self._updatingRobotPlacementUI = False
                self._updateRos2MotionControlStatus(
                    _("ROS 2 joint update failed: %1").replace("%1", message)
                )
                return
        elif self.logic.robotLinkTransformNodes():
            self.logic.updateRobotJointPoses(positions)
        self._updateRobotPlacementStatus()

    def onRobotBaseTransformSelectionChanged(self, transformNode) -> None:
        if self._updatingRobotPlacementUI or not self._parameterNode:
            return
        self._parameterNode.robotBaseTransform = transformNode
        self._updateRobotPlacement()

    def onRobotMountPlaneSelectionChanged(self, planeNode) -> None:
        if self._updatingRobotPlacementUI or not self._parameterNode:
            return
        self._parameterNode.robotMountPlane = planeNode
        self._updateRobotPlacement()

    def onDraftPhantomSelectionChanged(self, node=None) -> None:
        del node
        if self._updatingRobotPlacementUI or not self._parameterNode:
            return
        self._parameterNode.draftPhantomSkullModel = (
            self.ui.draftPhantomSkullSelector.currentNode()
        )
        self._parameterNode.draftPhantomMandibleModel = (
            self.ui.draftPhantomMandibleSelector.currentNode()
        )
        self._updateRobotPlacement()

    def onDraftJawLandmarksSelectionChanged(self, node) -> None:
        if self._updatingRobotPlacementUI or not self._parameterNode:
            return
        self._parameterNode.draftJawLandmarks = node
        self._bindDraftJawLandmarksNode(node)
        self._updateRobotPlacement()

    def onRobotKeyboardNudgeToggled(self, checked: bool) -> None:
        if self._updatingRobotPlacementUI or not self._parameterNode:
            return
        self._parameterNode.robotKeyboardNudgeEnabled = bool(checked)
        self._updateRobotKeyboardShortcutState()

    def onResetRobotJoints(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode:
            return
        wasModifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.robotJoint1Deg = 0.0
            self._parameterNode.robotJoint2Mm = 0.0
            self._parameterNode.robotJoint3Deg = 0.0
            self._parameterNode.robotJoint4Mm = 0.0
            self._parameterNode.robotJoint5Deg = 0.0
            self._parameterNode.robotJoint6Deg = 0.0
        finally:
            self._parameterNode.EndModify(wasModifying)
        self._updateRobotPlacement()
        self._updateRobotPlacementStatus(_("All robot joints reset to selected zero."))

    def onResetRobotBase(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        baseTransform = self._parameterNode.robotBaseTransform
        if not self.logic.isRobotBaseTransformNode(baseTransform):
            return
        matrix = vtk.vtkMatrix4x4()
        matrix.Identity()
        baseTransform.SetAndObserveTransformNodeID(None)
        baseTransform.SetMatrixTransformToParent(matrix)
        self._updateRobotPlacementStatus(_("Robot base reset to Slicer world RAS."))

    def onFrameStep6CaseScene(self, checked: bool = False) -> None:
        """Show the imported case in slice and 3D views (not the phantom workspace)."""
        del checked
        if not self._parameterNode or not self.logic:
            return
        self._showStep6CaseVolumeInSliceViewers()
        bounds = self.logic.step6CaseViewRasBounds(self._parameterNode)
        if bounds is None:
            return
        self._frameRasBoundsInViews(bounds)

    def onFrameStep6ResearchWorkspace(self, checked: bool = False) -> None:
        del checked
        if not self.logic:
            return
        bounds = self.logic.step6ResearchWorkspaceRasBounds(
            self.logic.robotModelNodes(),
            self.logic.draftPhantomModelNodes(),
        )
        if bounds is None:
            return
        self._frameRasBoundsInViews(bounds)

    def onFrameRobot(self, checked: bool = False) -> None:
        del checked
        self.onFrameStep6ResearchWorkspace()

    def onDeleteRobotSetup(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        if not slicer.util.confirmYesNoDisplay(
            _(
                "Delete the simulation-only robot meshes, link transforms, base "
                "transform, and mount plane from this scene?"
            ),
            windowTitle=_("Delete Step 6 robot setup"),
        ):
            return
        if self.logic.isRos2MotionControlActive(
            self._parameterNode.robotBaseTransform
        ):
            disconnect_dentobot_motion_control(self.logic.robotModelNodes())
        removed = self.logic.deleteRobotPlacement(
            self._parameterNode.robotBaseTransform,
            self._parameterNode.robotMountPlane,
        )
        wasModifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.robotBaseTransform = None
            self._parameterNode.robotMountPlane = None
            self._parameterNode.robotKeyboardNudgeEnabled = False
        finally:
            self._parameterNode.EndModify(wasModifying)
        self._clearRobotPlacement()
        logging.info("Deleted %d Step 6 robot placement nodes", len(removed))

    def _step6SceneKind(self) -> str:
        if not self._parameterNode or not self.logic:
            return "none"
        imported = bool(self._parameterNode.step6PlanningContextImported)
        phantom = bool(self.logic.draftPhantomModelNodes())
        if imported and phantom:
            return "conflict"
        if imported:
            return "case"
        if phantom:
            return "phantom"
        return "none"

    def _step6RobotPresent(self) -> bool:
        if not self._parameterNode or not self.logic:
            return False
        base = self._parameterNode.robotBaseTransform
        if self.logic.isRos2MotionControlActive(base):
            return True
        return bool(self.logic.robotModelNodes())

    def _showStep6CaseVolumeInSliceViewers(self) -> None:
        if not self._parameterNode:
            return
        volume = self._parameterNode.inputVolume
        if volume is None:
            return
        try:
            slicer.util.setSliceViewerLayers(background=volume, fit=True)
        except Exception:
            logging.debug("Could not set slice viewers to the Step 6 case volume.")

    def _applyStep6RecommendedView(self) -> None:
        if not hasattr(self, "ui"):
            return
        stage_entries = self._workflowStageEntries()
        if (
            not stage_entries
            or int(self.ui.workflowStageComboBox.currentIndex)
            != len(stage_entries) - 1
        ):
            return
        if self._step6SceneKind() == "case":
            self._showStep6CaseVolumeInSliceViewers()
        self._applyWorkflowViewPreset("recommended", updateStatus=False)
        self._updateWorkflowViewControls()

    def _confirmStep6SceneSwitch(self, target: str) -> bool:
        kind = self._step6SceneKind()
        if kind in {"none", target}:
            return True
        if target == "case":
            return slicer.util.confirmYesNoDisplay(
                _(
                    "A draft phantom is already loaded. Switch to the case package "
                    "and delete the phantom from the scene?"
                )
            )
        return slicer.util.confirmYesNoDisplay(
            _(
                "A case package is already imported. Switch to the phantom test "
                "scene? Case nodes stay in the scene but the recommended view "
                "will hide them."
            )
        )

    def _updateStep6PlanningUi(self, message: str = "", error: bool = False) -> None:
        if not hasattr(self, "ui") or not self._parameterNode:
            return
        imported = bool(self._parameterNode.step6PlanningContextImported)
        locked = bool(self._parameterNode.robotBaseMountLocked)
        has_plan = self._step6MotionPlan is not None and self._step6MotionPlan.success
        scene_kind = self._step6SceneKind()
        scene_active = scene_kind in {"case", "phantom"}
        robot_present = self._step6RobotPresent()
        ros2_active = self.logic.isRos2MotionControlActive(
            self._parameterNode.robotBaseTransform
        ) if self.logic else False

        if message:
            context_status = message
        elif scene_kind == "case":
            context_status = _("Case planning package is the active Step 6 scene.")
        elif scene_kind == "phantom":
            context_status = _("Draft phantom is the active Step 6 scene.")
        elif scene_kind == "conflict":
            context_status = _(
                "Both a case package and a phantom are present. Choose one scene."
            )
        else:
            context_status = _("No Step 6 scene yet. Import a case or load the phantom.")

        if locked:
            mount_status = _("Base mount locked for motion planning.")
        elif not scene_active:
            mount_status = _("Choose a scene before loading the robot.")
        elif not robot_present:
            mount_status = _("Load the ROS robot (or MRML fallback) before placing.")
        else:
            mount_status = _("Base mount is unlocked.")

        if message and "motion plan" in message.lower():
            plan_status = message
        elif has_plan:
            plan_status = self._step6MotionPlan.message
        elif not imported:
            plan_status = _(
                "Trajectory planning needs the case package. Phantom mode is "
                "for placement testing only."
            )
        else:
            plan_status = _("No motion plan yet.")

        style_ok = "color: #207227;"
        style_warn = "color: #b36b00;"
        style_err = "color: #b00020;"
        style = style_err if error else (
            style_ok if scene_active or has_plan else style_warn
        )

        self.ui.step6PlanningContextStatusLabel.text = context_status
        self.ui.step6PlanningContextStatusLabel.styleSheet = (
            style_err if scene_kind == "conflict" else (
                style_ok if scene_active else style_warn
            )
        )
        self.ui.step6MountLockStatusLabel.text = mount_status
        self.ui.step6MountLockStatusLabel.styleSheet = (
            style_ok if locked else style_warn
        )
        self.ui.step6TrajectoryPlanningStatusLabel.text = plan_status
        self.ui.step6TrajectoryPlanningStatusLabel.styleSheet = (
            style_err if error else (style_ok if has_plan else style_warn)
        )

        self.ui.step6MountLockGroupBox.enabled = scene_active
        self.ui.step6TaskJointLimitsGroupBox.enabled = robot_present
        self.ui.step6WorkspaceGroupBox.enabled = robot_present
        self.ui.step6TrajectoryPlanningGroupBox.enabled = locked and imported

        place_enabled = scene_active and robot_present and not locked
        self.ui.lockRobotBaseMountButton.enabled = (
            scene_active and robot_present and not locked
        )
        self.ui.unlockRobotBaseMountButton.enabled = locked
        self.ui.planTrajectoryMotionButton.enabled = imported and locked
        self.ui.previewTrajectoryMotionButton.enabled = has_plan
        self.ui.stopTrajectoryMotionButton.enabled = (
            self._step6MotionPreviewTimer is not None
        )

        self.ui.connectRos2MotionButton.enabled = scene_active and not ros2_active
        self.ui.disconnectRos2MotionButton.enabled = ros2_active
        self.ui.loadRobotModelButton.enabled = scene_active
        self.ui.frameRobotButton.enabled = scene_active
        self.ui.importStep6PlanningContextButton.enabled = not locked
        self.ui.loadDraftPhantomButton.enabled = not locked

        for widget_name in (
            "createRobotMountPlaneButton",
            "flipRobotMountPlaneButton",
            "snapRobotBaseToPlaneButton",
            "resetRobotBaseButton",
        ):
            widget = getattr(self.ui, widget_name, None)
            if widget is not None:
                widget.setEnabled(place_enabled)
        self.ui.snapRobotBaseToPlaneButton.enabled = (
            place_enabled
            and self.logic.isRobotBaseTransformNode(
                self._parameterNode.robotBaseTransform
            )
            and self.logic.isRobotMountPlaneNode(self._parameterNode.robotMountPlane)
        )
        self.ui.flipRobotMountPlaneButton.enabled = (
            place_enabled
            and self.logic.isRobotMountPlaneNode(self._parameterNode.robotMountPlane)
        )
        for widget_name in (
            "robotXMinusButton",
            "robotXPlusButton",
            "robotYMinusButton",
            "robotYPlusButton",
            "robotZMinusButton",
            "robotZPlusButton",
            "robotRxMinusButton",
            "robotRxPlusButton",
            "robotRyMinusButton",
            "robotRyPlusButton",
            "robotRzMinusButton",
            "robotRzPlusButton",
        ):
            widget = getattr(self.ui, widget_name, None)
            if widget is not None:
                widget.setEnabled(place_enabled)
        self.ui.robotKeyboardNudgeCheckBox.enabled = place_enabled
        self.ui.resetRobotJointsButton.enabled = robot_present
        self.ui.deleteRobotSetupButton.enabled = robot_present and not locked
        self.ui.applyTaskJointLimitsButton.enabled = robot_present
        self.ui.resetTaskJointLimitsButton.enabled = robot_present
        self.ui.generateRobotWorkspaceButton.enabled = (
            robot_present
            and self.logic.isRobotBaseTransformNode(
                self._parameterNode.robotBaseTransform
            )
        )
        self.ui.clearRobotWorkspaceButton.enabled = bool(
            self.logic.robotWorkspaceModelNode()
        )

    def _applyTaskJointLimitsToJointSpinboxes(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        limits = self.logic.getTaskJointLimits(self._parameterNode)
        pairs = (
            (self.ui.robotJoint1SpinBox, limits.joint_1),
            (self.ui.robotJoint2SpinBox, limits.joint_2),
            (self.ui.robotJoint3SpinBox, limits.joint_3),
            (self.ui.robotJoint4SpinBox, limits.joint_4),
            (self.ui.robotJoint5SpinBox, limits.joint_5),
            (self.ui.robotJoint6SpinBox, limits.joint_6),
        )
        for spinbox, joint_limit in pairs:
            minimum, maximum, value = apply_task_limit_range_to_value(
                spinbox.value,
                joint_limit,
            )
            spinbox.setMinimum(minimum)
            spinbox.setMaximum(maximum)
            spinbox.setValue(value)

    def _onTaskJointLimitSpinBoxChanged(self, value: float = 0.0) -> None:
        del value
        if self._updatingFromParameterNode or self._updatingRobotPlacementUI:
            return
        try:
            self._applyTaskJointLimitsToJointSpinboxes()
            if self.logic.deleteRobotWorkspaceModel():
                self.ui.robotWorkspaceStatusLabel.text = _(
                    "Task limits changed. Generate a new workspace cloud."
                )
                self.ui.robotWorkspaceStatusLabel.styleSheet = "color: #b36b00;"
        except ValueError:
            pass

    def _setRobotJointsFromSi(
        self,
        joint_positions_si: dict[str, float],
        *,
        publish_to_ros: bool = True,
    ) -> tuple[bool, str]:
        if not self._parameterNode:
            return False, _("Step 6 parameter node is unavailable.")
        was_modifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.robotJoint1Deg = degrees(
                joint_positions_si["link-1_Revolute-1"],
            )
            self._parameterNode.robotJoint2Mm = (
                joint_positions_si["link-2_Slider-2"] * 1000.0
            )
            self._parameterNode.robotJoint3Deg = degrees(
                joint_positions_si["link-3_Revolute-3"],
            )
            self._parameterNode.robotJoint4Mm = (
                joint_positions_si["link-4_Slider-4"] * 1000.0
            )
            self._parameterNode.robotJoint5Deg = degrees(
                joint_positions_si["link-5_Revolute-5"],
            )
            self._parameterNode.robotJoint6Deg = degrees(
                joint_positions_si["pneumatic_spindle-Copy_Revolute-6"],
            )
        finally:
            self._parameterNode.EndModify(was_modifying)
        self._updateRobotPlacement()
        if (
            publish_to_ros
            and self.logic
            and self.logic.isRos2MotionControlActive(
                self._parameterNode.robotBaseTransform
            )
        ):
            ok, message = apply_joint_positions_si_to_motion_control(joint_positions_si)
            if not ok:
                return False, message
        return True, ""

    def onImportStep6PlanningContext(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            if self._caseBundleRobotProfileCompatible is False:
                raise ValueError(
                    _(
                        "The installed URDF/SRDF/mesh/MoveIt resources do not "
                        "match this case package. Reconcile the robot profile "
                        "before importing the case into Step 6."
                    )
                )
            if not self._confirmStep6SceneSwitch("case"):
                return
            if self.logic.draftPhantomModelNodes():
                self.logic.deleteDraftPhantom(
                    self._parameterNode.draftJawLandmarks,
                    self._parameterNode.draftJawTransform,
                    self._parameterNode.draftJawGapLine,
                )
                was_modifying = self._parameterNode.StartModify()
                try:
                    self._parameterNode.draftPhantomSkullModel = None
                    self._parameterNode.draftPhantomMandibleModel = None
                    self._parameterNode.draftJawLandmarks = None
                    self._parameterNode.draftJawTransform = None
                    self._parameterNode.draftJawGapLine = None
                finally:
                    self._parameterNode.EndModify(was_modifying)
            report = self.logic.importStep6PlanningContext(self._parameterNode)
            try:
                self._applyTaskJointLimitsToJointSpinboxes()
            except ValueError:
                pass
            self._applyStep6RecommendedView()
            self.onFrameStep6CaseScene()
            self._updateStep6PlanningUi(report.message)
        except (RuntimeError, ValueError) as exc:
            self._updateStep6PlanningUi(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onLockRobotBaseMount(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        if self._step6SceneKind() not in {"case", "phantom"}:
            slicer.util.errorDisplay(
                _("Import a case package or load the draft phantom before locking."),
            )
            return
        if not self._step6RobotPresent():
            slicer.util.errorDisplay(_("Load the ROS robot or MRML fallback before locking."))
            return
        try:
            self.logic.setRobotBaseMountLocked(self._parameterNode, True)
            message = _("Base mount locked.")
            if self.logic.isRos2MotionControlActive(
                self._parameterNode.robotBaseTransform
            ):
                obstacle_count = self.logic.syncStep6MoveItPlanningScene(
                    self._parameterNode
                )
                message = _(
                    "Base mount locked; refreshed %1 MoveIt collision surface(s)."
                ).replace("%1", str(obstacle_count))
            self._updateStep6PlanningUi(message)
        except (RuntimeError, ValueError) as exc:
            self.logic.setRobotBaseMountLocked(self._parameterNode, False)
            self._updateStep6PlanningUi(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onUnlockRobotBaseMount(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        self.logic.setRobotBaseMountLocked(self._parameterNode, False)
        self._updateStep6PlanningUi(_("Base mount unlocked."))

    def onApplyTaskJointLimits(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            self._applyTaskJointLimitsToJointSpinboxes()
            self._updateStep6PlanningUi(_("Task joint limits applied to Step 6 controls."))
        except ValueError as exc:
            self._updateStep6PlanningUi(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onResetTaskJointLimits(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        self.logic.resetTaskJointLimitsToUrdf(self._parameterNode)
        self._applyTaskJointLimitsToJointSpinboxes()
        self._updateStep6PlanningUi(_("Task joint limits reset to URDF mechanical bounds."))

    def onGenerateRobotWorkspace(self, checked: bool = False) -> None:
        """Build a deterministic, filtered provisional-TCP reach cloud."""
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            qt.QApplication.setOverrideCursor(qt.Qt.WaitCursor)
            model, report = self.logic.createOrUpdateRobotWorkspace(
                self._parameterNode
            )
            self.ui.robotWorkspaceStatusLabel.text = _(
                "%1/%2 TCP samples accepted; %3 rejected by 5 mm self-AABB "
                "clearance and %4 by provisional TCP/environment clearance. "
                "%5 persistent CAD-AABB false-positive pairs are excluded; "
                "MoveIt remains authoritative."
            ).replace("%1", str(report.accepted_count)).replace(
                "%2", str(report.requested_count)
            ).replace("%3", str(report.self_collision_rejections)).replace(
                "%4", str(report.environment_rejections)
            ).replace(
                "%5", str(report.excluded_aabb_pairs)
            )
            self.ui.robotWorkspaceStatusLabel.styleSheet = "color: #207227;"
            self.ui.clearRobotWorkspaceButton.enabled = model is not None
        except (RuntimeError, ValueError) as exc:
            self.ui.robotWorkspaceStatusLabel.text = str(exc)
            self.ui.robotWorkspaceStatusLabel.styleSheet = "color: #b00020;"
            slicer.util.errorDisplay(str(exc))
        finally:
            qt.QApplication.restoreOverrideCursor()

    def onClearRobotWorkspace(self, checked: bool = False) -> None:
        del checked
        if not self.logic:
            return
        self.logic.deleteRobotWorkspaceModel()
        self.ui.robotWorkspaceStatusLabel.text = _("No workspace cloud generated.")
        self.ui.robotWorkspaceStatusLabel.styleSheet = "color: #b36b00;"
        self.ui.clearRobotWorkspaceButton.enabled = False

    def onPlanTrajectoryMotion(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            if self.logic.isRos2MotionControlActive(
                self._parameterNode.robotBaseTransform
            ):
                ok, message = ensure_slicer_ros2_runtime(require_stack=True)
                if not ok:
                    raise RuntimeError(message)
            self.onStopTrajectoryMotion()
            result = self.logic.planStep6TrajectoryMotion(self._parameterNode)
            self._step6MotionPlan = result
            if not result.success:
                raise RuntimeError(result.message)
            self._updateStep6PlanningUi(result.message)
        except (RuntimeError, ValueError) as exc:
            self._step6MotionPlan = None
            self._updateStep6PlanningUi(str(exc), error=True)
            slicer.util.errorDisplay(str(exc))

    def onPreviewTrajectoryMotion(self, checked: bool = False) -> None:
        del checked
        if not self._step6MotionPlan or not self._step6MotionPlan.success:
            return
        import qt

        if self.logic and self._parameterNode and self.logic.isRos2MotionControlActive(
            self._parameterNode.robotBaseTransform
        ):
            ok, message = ensure_slicer_ros2_runtime(require_stack=True)
            if not ok:
                slicer.util.errorDisplay(message)
                return
        self.onStopTrajectoryMotion()
        self._step6MotionPreviewIndex = 0
        timer = qt.QTimer()
        timer.setInterval(250)
        timer.timeout.connect(self._advanceStep6MotionPreview)
        timer.start()
        self._step6MotionPreviewTimer = timer
        self._updateStep6PlanningUi(_("Previewing simulated motion plan."))

    def _advanceStep6MotionPreview(self) -> None:
        if not self._step6MotionPlan or not self._step6MotionPlan.waypoint_joint_vectors_si:
            self.onStopTrajectoryMotion()
            return
        waypoints = self._step6MotionPlan.waypoint_joint_vectors_si
        if self._step6MotionPreviewIndex >= len(waypoints):
            self.onStopTrajectoryMotion()
            self._updateStep6PlanningUi(_("Simulated motion preview complete."))
            return
        ok, message = self._setRobotJointsFromSi(
            waypoints[self._step6MotionPreviewIndex]
        )
        if not ok:
            self.onStopTrajectoryMotion()
            self._updateStep6PlanningUi(message, error=True)
            slicer.util.errorDisplay(message)
            return
        self._step6MotionPreviewIndex += 1
        slicer.app.processEvents()

    def onStopTrajectoryMotion(self, checked: bool = False) -> None:
        del checked
        if self._step6MotionPreviewTimer is not None:
            self._step6MotionPreviewTimer.stop()
            self._step6MotionPreviewTimer = None
        self._step6MotionPreviewIndex = 0
        self._updateStep6PlanningUi()

    def _workflowStageEntries(self) -> list[tuple[str, object]]:
        """Return the ordered clinical/research workflow sections.

        The section widgets remain the existing CTK collapsible buttons so the
        navigation layer does not duplicate controls or MRML state.
        """

        return [
            (_("Case"), self.ui.caseCollapsibleButton),
            (_("1 · CBCT Imaging"), self.ui.imagingCollapsibleButton),
            (_("2 · AI Segmentation"), self.ui.backendCollapsibleButton),
            (_("3 · Review and Correct"), self.ui.segmentationReviewCollapsibleButton),
            (_("4A · Trajectory Planning"), self.ui.planningCollapsibleButton),
            (_("4B · Support Teeth and Draft"), self.ui.templateModelingCollapsibleButton),
            (_("4C · Guide Rails and Docks"), self.ui.targetDockingCollapsibleButton),
            (_("5A · Visible Support Surface"), self.ui.templateModelingCollapsibleButton),
            (_("5B · Shell and Guide Fusion"), self.ui.templateGuideCollapsibleButton),
            (_("5C · Verify and Export"), self.ui.templateFinalizationCollapsibleButton),
            (_("6 · Robot Placement"), self.ui.robotPlacementCollapsibleButton),
        ]

    def _setupWorkflowNavigation(self) -> None:
        """Initialize the one-visible-stage wizard over the existing controls."""

        self._updatingWorkflowNavigationUI = True
        try:
            self.ui.workflowStageComboBox.clear()
            for stageLabel, _section in self._workflowStageEntries():
                self.ui.workflowStageComboBox.addItem(stageLabel)
            self.ui.workflowStageComboBox.currentIndex = 0
            entries = self._workflowStageEntries()
            for section in {entry[1] for entry in entries}:
                active = section is entries[0][1]
                section.visible = active
                section.collapsed = not active
            self.ui.assistedTrajectoryCollapsibleButton.collapsed = True
            self.ui.assistedTrajectoryCollapsibleButton.visible = False
        finally:
            self._updatingWorkflowNavigationUI = False

        self.ui.workflowStageComboBox.connect(
            "currentIndexChanged(int)",
            self.onWorkflowStageChanged,
        )
        self.ui.previousWorkflowStageButton.connect(
            "clicked(bool)",
            self.onPreviousWorkflowStage,
        )
        self.ui.nextWorkflowStageButton.connect(
            "clicked(bool)",
            self.onNextWorkflowStage,
        )
        self.ui.showGuidanceCheckBox.connect(
            "toggled(bool)",
            self.onShowGuidanceToggled,
        )
        self.ui.showBackendLogCheckBox.connect(
            "toggled(bool)",
            self.onShowBackendLogToggled,
        )
        self.ui.workflowViewPresetComboBox.connect(
            "currentIndexChanged(int)",
            self.onWorkflowViewPresetChanged,
        )
        self.ui.workflowViewElementsListWidget.connect(
            "itemChanged(QListWidgetItem*)",
            self.onWorkflowViewElementChanged,
        )
        self.ui.frameWorkflowViewButton.connect(
            "clicked(bool)",
            self.onFrameWorkflowView,
        )
        self.ui.restoreWorkflowViewButton.connect(
            "clicked(bool)",
            self.onRestoreWorkflowView,
        )
        connectedSections = set()
        for _index, (_stageLabel, section) in enumerate(self._workflowStageEntries()):
            if section in connectedSections:
                continue
            connectedSections.add(section)
            section.connect(
                "contentsCollapsed(bool)",
                lambda collapsed, activeSection=section: self._onWorkflowSectionCollapsed(
                    activeSection, collapsed
                ),
            )
        self._setGuidanceVisible(False)
        self._updateWorkflowNavigationButtons()
        self._setWorkflowViewAvailability(False)

    @staticmethod
    def _normalizedTrajectoryPlacementMode(mode: str) -> str:
        return "Assisted" if str(mode).strip() == "Assisted" else "Manual"

    def _trajectoryPlacementMode(self) -> str:
        if not self._parameterNode:
            return "Manual"
        return self._normalizedTrajectoryPlacementMode(
            self._parameterNode.trajectoryPlacementMode
        )

    def _updateTrajectoryPlacementModeControls(self) -> None:
        if not hasattr(self, "ui"):
            return
        mode = self._trajectoryPlacementMode()
        comboBox = self.ui.trajectoryPlacementModeComboBox
        self._updatingPlanningUI = True
        try:
            selectedIndex = comboBox.findData(mode)
            comboBox.currentIndex = max(int(selectedIndex), 0)
            manualVisible = mode == "Manual"
            for widget in (
                self.ui.createTrajectoryButton,
                self.ui.placeTrajectoryButton,
                self.ui.undoTrajectoryPointButton,
                self.ui.resetTrajectoryButton,
            ):
                widget.visible = manualVisible
            stageIndex = int(self.ui.workflowStageComboBox.currentIndex)
            assistedVisible = mode == "Assisted" and stageIndex == 4
            self.ui.assistedTrajectoryCollapsibleButton.visible = assistedVisible
            if assistedVisible:
                self.ui.assistedTrajectoryCollapsibleButton.collapsed = False
        finally:
            self._updatingPlanningUI = False

    def onTrajectoryPlacementModeChanged(self, index: int) -> None:
        if self._updatingPlanningUI or not self._parameterNode:
            return
        mode = self.ui.trajectoryPlacementModeComboBox.itemData(int(index))
        normalizedMode = self._normalizedTrajectoryPlacementMode(mode)
        if self._parameterNode.trajectoryPlacementMode != normalizedMode:
            self._parameterNode.trajectoryPlacementMode = normalizedMode
        self._updateTrajectoryPlacementModeControls()
        self._updatePlanning()

    def _guidanceWidgets(self) -> list[object]:
        widgetNames = (
            "introLabel",
            "dicomInstructionLabel",
            "backendDescriptionLabel",
            "runArtifactsExplanationLabel",
            "segmentationSafetyLabel",
            "segmentationReviewDescriptionLabel",
            "segmentationReviewSafetyLabel",
            "planningDescriptionLabel",
            "planningSafetyLabel",
            "assistedTrajectoryDescriptionLabel",
            "assistedTrajectorySafetyLabel",
            "targetDockingDescriptionLabel",
            "targetDockingSafetyLabel",
            "templateModelingDescriptionLabel",
            "templateModelingSafetyLabel",
            "templateGuideDescriptionLabel",
            "templateDockingFusionDescriptionLabel",
            "templateGuideSafetyLabel",
            "finalVerificationDescriptionLabel",
            "finalVerificationSafetyLabel",
        )
        return [
            getattr(self.ui, widgetName)
            for widgetName in widgetNames
            if hasattr(self.ui, widgetName)
        ]

    def _setGuidanceVisible(self, visible: bool) -> None:
        for widget in self._guidanceWidgets():
            widget.visible = bool(visible)

    def onShowGuidanceToggled(self, visible: bool) -> None:
        self._setGuidanceVisible(visible)

    def onShowBackendLogToggled(self, visible: bool) -> None:
        self.ui.backendLogTextEdit.visible = bool(visible)

    def _workflowViewSupportSegmentIds(self) -> list[str]:
        if not self._parameterNode or not self.logic:
            return []
        try:
            supportIds = self.logic.decodeTemplateSupportSegmentIds(
                self._parameterNode.templateSupportToothSegmentIdsJson
            )
        except ValueError:
            supportIds = []
        sourceModel = self._parameterNode.draftTemplateSupportModel
        if self.logic.isDraftTemplateSupportModelNode(sourceModel):
            try:
                supportIds = self.logic.getDraftTemplateSupportModelSummary(
                    sourceModel
                )["supportSegmentIds"]
            except (RuntimeError, ValueError, json.JSONDecodeError):
                pass
        targetId = self._parameterNode.targetToothSegmentId
        return [
            segmentId
            for segmentId in supportIds
            if segmentId and segmentId != targetId
        ]

    def _workflowManagedDisplayNodes(self) -> list:
        """Return every user-facing displayable so presets never leave stale objects."""

        nodesById = {}
        if self._parameterNode:
            for fieldName in (
                "targetToothBoundsRoi",
                "trajectoryLine",
                "assistedTrajectoryEntries",
                "targetDockingReferencePlane",
                "targetDockingAssemblyModel",
                "draftTemplateSupportModel",
                "templateSupportBoundaryCurve",
                "templateSupportBoundaryPlane",
                "visibleTemplateSupportModel",
                "templateInsertionDirection",
                "templateUndercutSurfaceModel",
                "templateUndercutBlockoutModel",
                "patientContactShellModel",
                "templateDockingAssemblyModel",
                "templateDockingClearanceModel",
                "templateDockingReinforcementModel",
                "templateDockingChannelsModel",
                "finalPrintableTemplateModel",
                "templateShellRoi",
                "researchTemplateShellModel",
                "researchTemplateSleeveModel",
                "templateTrimPlane",
                "templateTrimCurve",
                "finalizedTemplateShellModel",
                "robotBaseTransform",
                "robotMountPlane",
                "draftPhantomSkullModel",
                "draftPhantomMandibleModel",
                "draftJawLandmarks",
                "draftJawGapLine",
            ):
                node = getattr(self._parameterNode, fieldName, None)
                if node and node.GetID() and node.IsA("vtkMRMLDisplayableNode"):
                    nodesById[node.GetID()] = node
        ownershipAttributes = (
            "DENTOBOT.TrajectoryRole",
            "DENTOBOT.MarkupsRole",
            "DENTOBOT.ModelRole",
            "DENTOBOT.BoundsRole",
        )
        for node in slicer.util.getNodesByClass("vtkMRMLDisplayableNode"):
            if node.IsA("vtkMRMLSegmentationNode"):
                continue
            hideFromEditors = getattr(node, "GetHideFromEditors", None)
            if hideFromEditors and hideFromEditors():
                continue
            if not node.GetDisplayNode():
                try:
                    node.CreateDefaultDisplayNodes()
                except Exception:
                    continue
            if node.GetID() and node.GetDisplayNode():
                nodesById[node.GetID()] = node
            if any(node.GetAttribute(attribute) for attribute in ownershipAttributes):
                nodesById[node.GetID()] = node
        if self.logic:
            for node in (
                *self.logic.robotModelNodes(),
                *self.logic.draftPhantomModelNodes(),
            ):
                if node and node.GetID():
                    nodesById[node.GetID()] = node
        try:
            ros_robot = find_ros2_robot_by_name("dentobot")
        except Exception:
            ros_robot = None
        if ros_robot:
            for index in range(ros_robot.GetNumberOfNodeReferences("model")):
                model = ros_robot.GetNthNodeReference("model", index)
                if model and model.GetID() and model.IsA("vtkMRMLDisplayableNode"):
                    nodesById[model.GetID()] = model
        return list(nodesById.values())

    def _workflowCuratedViewEntries(self, stageIndex: int) -> list[dict]:
        if not self._parameterNode or not self.logic or stageIndex < 4:
            return []
        if stageIndex == 10:
            return self._step6WorkflowViewEntries()
        segmentationNode = self._parameterNode.teethSegmentation
        targetId = self._parameterNode.targetToothSegmentId
        supportIds = self._workflowViewSupportSegmentIds()
        entries = []

        def addSegments(key, label, segmentIds, category, stages) -> None:
            if stageIndex not in stages or not segmentationNode:
                return
            segmentation = segmentationNode.GetSegmentation()
            validIds = [
                segmentId
                for segmentId in segmentIds
                if segmentation.GetSegment(segmentId)
            ]
            if validIds:
                entries.append(
                    {
                        "key": key,
                        "label": label,
                        "kind": "segments",
                        "segmentIds": validIds,
                        "category": category,
                    }
                )

        def addNode(key, label, node, category, stages) -> None:
            if (
                stageIndex not in stages
                or not node
                or not node.GetID()
                or not node.GetDisplayNode()
            ):
                return
            entries.append(
                {
                    "key": key,
                    "label": label,
                    "kind": "node",
                    "node": node,
                    "category": category,
                }
            )

        allStageIndices = {4, 5, 6, 7, 8, 9}
        if segmentationNode and targetId:
            targetLabel = targetId
            targetRecord = self._targetToothRecordsById.get(targetId)
            if targetRecord:
                targetLabel = targetRecord["displayName"]
            addSegments(
                "segments:target",
                _("[Mask] Target tooth — %1").replace("%1", targetLabel),
                [targetId],
                "target_mask",
                allStageIndices,
            )
            targetFdi = (
                str(targetRecord.get("fdiNumber") or "")
                if targetRecord
                else ""
            )
            if targetFdi:
                try:
                    detailIds = [
                        record["segmentId"]
                        for record in self.logic.getSegmentationReviewRecords(
                            segmentationNode
                        )
                        if record.get("fdiNumber") == targetFdi
                        and record.get("category") == "Pulp and root canals"
                    ]
                except ValueError:
                    detailIds = []
                addSegments(
                    "segments:targetDetail",
                    _("[Mask] Target pulp / root canal (%1)").replace(
                        "%1", str(len(detailIds))
                    ),
                    detailIds,
                    "target_detail",
                    {4},
                )
        addSegments(
            "segments:support",
            _("[Masks] Selected support teeth (%1)").replace(
                "%1", str(len(supportIds))
            ),
            supportIds,
            "support_mask",
            {5, 6, 7, 8, 9},
        )
        if segmentationNode:
            allSegmentIds = vtk.vtkStringArray()
            segmentationNode.GetSegmentation().GetSegmentIDs(allSegmentIds)
            subjectIds = {targetId, *supportIds}
            otherIds = [
                allSegmentIds.GetValue(index)
                for index in range(allSegmentIds.GetNumberOfValues())
                if allSegmentIds.GetValue(index) not in subjectIds
            ]
            addSegments(
                "segments:other",
                _("[Masks] Other segmented anatomy (%1)").replace(
                    "%1", str(len(otherIds))
                ),
                otherIds,
                "other_mask",
                allStageIndices,
            )

        addNode(
            "node:targetBounds",
            _("[4A] Target bounds box"),
            self._parameterNode.targetToothBoundsRoi,
            "bounds",
            allStageIndices,
        )
        targetTrajectories = []
        if segmentationNode and targetId:
            targetTrajectories = self.logic.dentobotTrajectoriesForTarget(
                segmentationNode,
                targetId,
            )
        for trajectoryNode in targetTrajectories:
            selectedSuffix = (
                _(" — selected")
                if trajectoryNode is self._parameterNode.trajectoryLine
                else ""
            )
            addNode(
                f"trajectory:{trajectoryNode.GetID()}",
                _("[4A] %1%2")
                .replace("%1", trajectoryNode.GetName() or _("Trajectory"))
                .replace("%2", selectedSuffix),
                trajectoryNode,
                "trajectory",
                allStageIndices,
            )
        addNode(
            "node:assistedEntries",
            _("[4A] Assisted crown entry points"),
            self._parameterNode.assistedTrajectoryEntries,
            "assisted",
            {4},
        )
        addNode(
            "node:targetDockingPlane",
            _("[4C] Occlusal reference plane"),
            self._parameterNode.targetDockingReferencePlane,
            "target_docking",
            {6, 7, 8, 9},
        )
        addNode(
            "node:targetDockingAssembly",
            _("[4C] Guide rails / four docks"),
            self._parameterNode.targetDockingAssemblyModel,
            "target_docking",
            {6, 7, 8, 9},
        )
        dockingAssembly = self._parameterNode.targetDockingAssemblyModel
        if dockingAssembly:
            role = self.logic.TARGET_DOCKING_MEASUREMENT_REFERENCE_ROLE
            for index in range(dockingAssembly.GetNumberOfNodeReferences(role)):
                measurementNode = dockingAssembly.GetNthNodeReference(role, index)
                addNode(
                    f"targetDockingMeasurement:{measurementNode.GetID()}"
                    if measurementNode
                    else f"targetDockingMeasurement:{index}",
                    measurementNode.GetName()
                    if measurementNode
                    else _("[4B] Dock measurement"),
                    measurementNode,
                    "target_docking_measurement",
                    {6, 7, 8, 9},
                )
        addNode(
            "node:draftSupport",
            _("[4B] Complete support-tooth draft"),
            self._parameterNode.draftTemplateSupportModel,
            "draft_support",
            {5, 6, 7},
        )
        addNode(
            "node:supportBoundary",
            _("[5A] Support boundary"),
            self._parameterNode.templateSupportBoundaryCurve,
            "support_boundary",
            {7, 8},
        )
        addNode(
            "node:supportPlane",
            _("[5A] Automatic support plane"),
            self._parameterNode.templateSupportBoundaryPlane,
            "support_plane",
            {7},
        )
        addNode(
            "node:visibleSupport",
            _("[5A] Visible support preview"),
            self._parameterNode.visibleTemplateSupportModel,
            "visible_support",
            {7, 8, 9},
        )
        addNode(
            "node:insertionDirection",
            _("[5B] Insertion direction"),
            self._parameterNode.templateInsertionDirection,
            "insertion",
            {8},
        )
        addNode(
            "node:undercut",
            _("[5B] Undercut preview"),
            self._parameterNode.templateUndercutSurfaceModel,
            "undercut",
            {8},
        )
        addNode(
            "node:blockout",
            _("[5B] Directional blockout"),
            self._parameterNode.templateUndercutBlockoutModel,
            "blockout",
            {8},
        )
        addNode(
            "node:patientShell",
            _("[5B] Patient-contact shell"),
            self._parameterNode.patientContactShellModel,
            "patient_shell",
            {8, 9},
        )
        for keySuffix, label, node in (
            (
                "dockingFusion",
                _("[5B] Integrated docking assembly"),
                self._parameterNode.templateDockingAssemblyModel,
            ),
            (
                "dockingClearance",
                _("[5B] Docking clearance"),
                self._parameterNode.templateDockingClearanceModel,
            ),
            (
                "reinforcement",
                _("[5B] Shell reinforcement"),
                self._parameterNode.templateDockingReinforcementModel,
            ),
            (
                "channels",
                _("[5B] Drill / dock channels"),
                self._parameterNode.templateDockingChannelsModel,
            ),
        ):
            addNode(
                f"node:{keySuffix}",
                label,
                node,
                "final_aux",
                {8, 9},
            )
        addNode(
            "node:finalTemplate",
            _("[5C] Final printable template"),
            self._parameterNode.finalPrintableTemplateModel,
            "final",
            {8, 9},
        )
        return entries

    def _workflowViewEntries(self, stageIndex: int) -> list[dict]:
        """Return a complete, individually toggleable inventory for every stage.

        Curated workflow entries supply meaningful categories for presets.  The
        inventory then expands segmentation groups into one row per segment and
        appends every other user-facing displayable node in the MRML scene.
        """

        if not self._parameterNode or not self.logic:
            return []
        curated = self._workflowCuratedViewEntries(stageIndex)
        entries = []
        for entry in curated:
            if entry["kind"] == "segments":
                continue
            if entry["kind"] != "nodes":
                entries.append(entry)
                continue
            for nodeIndex, node in enumerate(entry["nodes"]):
                entries.append(
                    {
                        "key": f"{entry['key']}:{node.GetID()}",
                        "label": _("%1 — %2")
                        .replace("%1", entry["label"])
                        .replace("%2", node.GetName() or str(nodeIndex + 1)),
                        "kind": "node",
                        "node": node,
                        "category": entry["category"],
                    }
                )
        categoryBySegment = {}
        for entry in curated:
            if entry["kind"] != "segments":
                continue
            for segmentId in entry["segmentIds"]:
                categoryBySegment.setdefault(segmentId, entry["category"])

        for segmentationNode in slicer.util.getNodesByClass(
            "vtkMRMLSegmentationNode"
        ):
            segmentation = segmentationNode.GetSegmentation()
            if not segmentation:
                continue
            segmentIds = vtk.vtkStringArray()
            segmentation.GetSegmentIDs(segmentIds)
            for segmentIndex in range(segmentIds.GetNumberOfValues()):
                segmentId = segmentIds.GetValue(segmentIndex)
                segment = segmentation.GetSegment(segmentId)
                if not segment:
                    continue
                category = categoryBySegment.get(segmentId, "other_mask")
                if (
                    segmentationNode is self._parameterNode.teethSegmentation
                    and segmentId == self._parameterNode.targetToothSegmentId
                ):
                    key = "segments:target"
                    category = "target_mask"
                elif category == "target_detail":
                    key = (
                        "segments:targetDetail"
                        if not any(
                            item.get("key") == "segments:targetDetail"
                            for item in entries
                        )
                        else f"segment:{segmentationNode.GetID()}:{segmentId}"
                    )
                else:
                    key = f"segment:{segmentationNode.GetID()}:{segmentId}"
                entries.append(
                    {
                        "key": key,
                        "label": _("[Mask] %1 — %2")
                        .replace("%1", segment.GetName() or segmentId)
                        .replace("%2", segmentationNode.GetName() or _("Segmentation")),
                        "kind": "segments",
                        "segmentationNode": segmentationNode,
                        "segmentIds": [segmentId],
                        "category": category,
                    }
                )

        representedNodeIds = set()
        for entry in entries:
            if entry["kind"] == "node" and entry.get("node"):
                representedNodeIds.add(entry["node"].GetID())
            elif entry["kind"] == "nodes":
                representedNodeIds.update(
                    node.GetID() for node in entry["nodes"] if node and node.GetID()
                )
        for node in self._workflowManagedDisplayNodes():
            if node.GetID() in representedNodeIds:
                continue
            classLabel = node.GetClassName().replace("vtkMRML", "").replace("Node", "")
            entries.append(
                {
                    "key": f"scene:{node.GetID()}",
                    "label": _("[Scene/%1] %2")
                    .replace("%1", classLabel)
                    .replace("%2", node.GetName() or node.GetID()),
                    "kind": "node",
                    "node": node,
                    "category": (
                        "case_volume"
                        if node.IsA("vtkMRMLScalarVolumeNode")
                        else "scene_element"
                    ),
                }
            )
        volumeRenderingLogic = (
            slicer.modules.volumerendering.logic()
            if hasattr(slicer.modules, "volumerendering")
            else None
        )
        if volumeRenderingLogic:
            for volumeNode in slicer.util.getNodesByClass("vtkMRMLScalarVolumeNode"):
                try:
                    renderingDisplay = (
                        volumeRenderingLogic.GetFirstVolumeRenderingDisplayNode(
                            volumeNode
                        )
                    )
                    if not renderingDisplay:
                        renderingDisplay = (
                            volumeRenderingLogic.CreateDefaultVolumeRenderingNodes(
                                volumeNode
                            )
                        )
                except Exception:
                    renderingDisplay = None
                if renderingDisplay:
                    entries.append(
                        {
                            "key": f"volumeRendering:{volumeNode.GetID()}",
                            "label": _("[3D Volume] %1").replace(
                                "%1", volumeNode.GetName() or volumeNode.GetID()
                            ),
                            "kind": "volume_rendering",
                            "node": volumeNode,
                            "displayNode": renderingDisplay,
                            "category": "case_volume_3d",
                        }
                    )
        return entries

    def _step6WorkflowViewEntries(self) -> list[dict]:
        """Step 6 Elements list: case package, phantom, robot, mount — not the full 4A–5C dump."""
        entries: list[dict] = []
        parameterNode = self._parameterNode
        segmentationNode = parameterNode.teethSegmentation
        targetId = parameterNode.targetToothSegmentId

        def addSegments(key, label, segmentIds, category) -> None:
            if not segmentationNode:
                return
            segmentation = segmentationNode.GetSegmentation()
            validIds = [
                segmentId
                for segmentId in segmentIds
                if segmentation.GetSegment(segmentId)
            ]
            if validIds:
                entries.append(
                    {
                        "key": key,
                        "label": label,
                        "kind": "segments",
                        "segmentIds": validIds,
                        "category": category,
                    }
                )

        def addNode(key, label, node, category) -> None:
            if not node or not node.GetID():
                return
            if not node.GetDisplayNode():
                try:
                    node.CreateDefaultDisplayNodes()
                except Exception:
                    return
            if not node.GetDisplayNode():
                return
            entries.append(
                {
                    "key": key,
                    "label": label,
                    "kind": "node",
                    "node": node,
                    "category": category,
                }
            )

        def addNodes(key, label, nodes, category) -> None:
            valid = []
            for node in nodes:
                if not node or not node.GetID():
                    continue
                if not node.GetDisplayNode():
                    try:
                        node.CreateDefaultDisplayNodes()
                    except Exception:
                        continue
                if node.GetDisplayNode():
                    valid.append(node)
            if not valid:
                return
            entries.append(
                {
                    "key": key,
                    "label": label,
                    "kind": "nodes",
                    "nodes": valid,
                    "category": category,
                }
            )

        if segmentationNode and targetId:
            targetLabel = targetId
            targetRecord = self._targetToothRecordsById.get(targetId)
            if targetRecord:
                targetLabel = targetRecord["displayName"]
            addSegments(
                "segments:target",
                _("[Mask] Target tooth — %1").replace("%1", targetLabel),
                [targetId],
                "target_mask",
            )
        if parameterNode.trajectoryLine:
            addNode(
                "node:step6Trajectory",
                _("[4A] Selected trajectory"),
                parameterNode.trajectoryLine,
                "trajectory",
            )
        addNode(
            "node:step6Volume",
            _("[1] CBCT volume"),
            parameterNode.inputVolume,
            "case_volume",
        )
        addNode(
            "node:step6Bounds",
            _("[4A] Target tooth bounds"),
            parameterNode.targetToothBoundsRoi,
            "bounds",
        )
        addNode(
            "node:step6Docks",
            _("[4C] Guide rails / docks"),
            parameterNode.targetDockingAssemblyModel,
            "target_docking",
        )
        addNode(
            "node:step6Template",
            _("[5C] Final printable template"),
            parameterNode.finalPrintableTemplateModel,
            "final",
        )
        addNodes(
            "nodes:step6Phantom",
            _("[Step 6] Draft phantom"),
            self.logic.draftPhantomModelNodes(),
            "phantom",
        )
        addNode(
            "node:step6JawLandmarks",
            _("[Step 6] Jaw landmarks"),
            parameterNode.draftJawLandmarks,
            "phantom_landmarks",
        )
        addNode(
            "node:step6JawGap",
            _("[Step 6] Incisor gap line"),
            parameterNode.draftJawGapLine,
            "phantom_landmarks",
        )
        addNode(
            "node:step6Mount",
            _("[Step 6] Mount plane"),
            parameterNode.robotMountPlane,
            "robot_mount",
        )
        addNodes(
            "nodes:step6MrmlRobot",
            _("[Step 6] MRML robot links"),
            self.logic.robotModelNodes(),
            "robot_mrml",
        )
        try:
            ros_robot = find_ros2_robot_by_name("dentobot")
        except Exception:
            ros_robot = None
        if ros_robot is not None:
            ros_models = [
                ros_robot.GetNthNodeReference("model", index)
                for index in range(ros_robot.GetNumberOfNodeReferences("model"))
            ]
            addNodes(
                "nodes:step6RosRobot",
                _("[Step 6] ROS robot"),
                ros_models,
                "robot_ros",
            )
        return entries

    @staticmethod
    def _workflowViewPresetCategories(presetKey: str) -> set[str] | None:
        categories = {
            "target_only": {"target_mask"},
            "trajectory_only": {
                "target_mask",
                "target_detail",
                "trajectory",
            },
            "plan": {"target_mask", "bounds", "trajectory", "assisted"},
            "support_masks": {"target_mask", "support_mask"},
            "support_design": {
                "target_mask",
                "support_mask",
                "draft_support",
                "support_boundary",
                "support_plane",
                "visible_support",
            },
            "docks_only": {"target_docking", "target_docking_measurement"},
            "undercut_analysis": {
                "visible_support",
                "insertion",
                "undercut",
                "blockout",
            },
            "shell_only": {"patient_shell"},
            "shell_guides": {
                "patient_shell",
                "trajectory",
                "target_docking",
                "final_aux",
            },
            "final_only": {"final"},
            "robot_mount_only": {"robot_mrml", "robot_ros", "robot_mount"},
            "case_package": {
                "case_volume",
                "case_volume_3d",
                "target_mask",
                "bounds",
                "trajectory",
                "target_docking",
                "final",
            },
            "phantom_only": {"phantom", "phantom_landmarks"},
        }
        return categories.get(presetKey)

    def _workflowViewRecommendedCategories(self, stageIndex: int) -> set[str]:
        if stageIndex == 4:
            return {"target_mask", "bounds", "trajectory", "assisted"}
        if stageIndex == 5:
            return {"target_mask", "support_mask", "draft_support"}
        if stageIndex == 6:
            return {
                "target_mask",
                "support_mask",
                "draft_support",
                "trajectory",
                "target_docking",
                "target_docking_measurement",
            }
        if stageIndex == 7:
            categories = {
                "target_mask",
                "support_mask",
                "support_boundary",
                "support_plane",
                "visible_support",
            }
            if not self._parameterNode.visibleTemplateSupportModel:
                categories.add("draft_support")
            return categories
        if stageIndex == 8:
            if self._parameterNode.finalPrintableTemplateModel:
                return {"final"}
            return {"patient_shell", "trajectory", "target_docking"}
        if stageIndex == 9:
            return (
                {"final"}
                if self._parameterNode.finalPrintableTemplateModel
                else {"patient_shell", "target_docking"}
            )
        if stageIndex == 10:
            ros_active = self.logic.isRos2MotionControlActive(
                self._parameterNode.robotBaseTransform
            )
            robot_category = {"robot_ros"} if ros_active else {"robot_mrml"}
            kind = self._step6SceneKind()
            if kind == "phantom":
                categories = {"phantom", "robot_mount", *robot_category}
                landmarks = self._parameterNode.draftJawLandmarks
                if landmarks is None or landmarks.GetNumberOfDefinedControlPoints() < 4:
                    categories.add("phantom_landmarks")
                return categories
            return {
                "case_volume",
                "case_volume_3d",
                "target_mask",
                "bounds",
                "trajectory",
                "target_docking",
                "final",
                "robot_mount",
                *robot_category,
            }
        return set()

    def _workflowViewPresetDefinitions(
        self,
        stageIndex: int,
        entries: list[dict],
    ) -> list[tuple[str, str]]:
        categories = {entry["category"] for entry in entries}
        definitions = [
            ("scene", _("Current scene visibility (unchanged)")),
            ("recommended", _("Recommended for this step")),
            ("target_only", _("Target tooth mask only")),
        ]
        if stageIndex == 4 and "trajectory" in categories:
            definitions.append(
                ("trajectory_only", _("Selected trajectory context only"))
            )
        if categories & {"trajectory", "bounds", "assisted"}:
            definitions.append(("plan", _("Target + trajectory planning")))
        if "support_mask" in categories:
            definitions.append(("support_masks", _("Target + support masks only")))
        if categories & {
            "support_boundary",
            "support_plane",
            "visible_support",
        }:
            definitions.append(("support_design", _("Support-surface design")))
        if "target_docking" in categories:
            definitions.append(("docks_only", _("Guide rails / docks only")))
        if categories & {"undercut", "blockout", "insertion"}:
            definitions.append(("undercut_analysis", _("Undercut analysis only")))
        if "patient_shell" in categories:
            definitions.append(("shell_only", _("Patient-contact shell only")))
            definitions.append(("shell_guides", _("Shell + trajectories + guides")))
        if "final" in categories:
            definitions.append(("final_only", _("Final printable template only")))
        if stageIndex == 10:
            definitions.append(("robot_mount_only", _("Robot + mount only")))
            if categories & {"target_mask", "trajectory", "target_docking", "final"}:
                definitions.append(
                    ("case_package", _("Case planning package"))
                )
            if "phantom" in categories:
                definitions.append(("phantom_only", _("Phantom only")))
        definitions.extend(
            (
                ("all", _("All elements available in this step")),
                ("custom", _("Custom element selection")),
            )
        )
        return definitions

    def _workflowViewKeysForPreset(
        self,
        presetKey: str,
        entries: list[dict],
        stageIndex: int,
    ) -> set[str]:
        if presetKey == "all":
            return {entry["key"] for entry in entries}
        if presetKey == "recommended" and stageIndex < 4:
            return {
                entry["key"]
                for entry in entries
                if self._workflowViewEntryCheckState(entry) != qt.Qt.Unchecked
            }
        if presetKey == "recommended":
            categories = self._workflowViewRecommendedCategories(stageIndex)
        else:
            categories = self._workflowViewPresetCategories(presetKey) or set()
        visibleKeys = {
            entry["key"]
            for entry in entries
            if entry["category"] in categories
        }
        if (
            self._parameterNode
            and not self._parameterNode.targetDockingMeasurementsVisible
        ):
            visibleKeys = {
                entry["key"]
                for entry in entries
                if entry["key"] in visibleKeys
                and entry["category"] != "target_docking_measurement"
            }
        if presetKey == "trajectory_only":
            selectedTrajectory = (
                self._parameterNode.trajectoryLine
                if self._parameterNode
                else None
            )
            visibleKeys = {
                entry["key"]
                for entry in entries
                if entry["key"] in visibleKeys
                and (
                    entry["category"] != "trajectory"
                    or entry.get("node") is selectedTrajectory
                )
            }
        if (
            presetKey == "recommended"
            and stageIndex == 4
            and not self._parameterNode.assistedTrajectoryEntries
        ):
            selectedTrajectory = (
                self._parameterNode.trajectoryLine
                if self._parameterNode
                else None
            )
            visibleKeys = {
                entry["key"]
                for entry in entries
                if entry["key"] in visibleKeys
                and (
                    entry["category"] != "trajectory"
                    or entry.get("node") is selectedTrajectory
                )
            }
        return visibleKeys

    def _workflowViewEntryCheckState(self, entry: dict) -> int:
        if entry["kind"] == "volume_rendering":
            return (
                qt.Qt.Checked
                if entry["displayNode"].GetVisibility()
                else qt.Qt.Unchecked
            )
        if entry["kind"] == "node":
            displayNode = entry["node"].GetDisplayNode()
            return (
                qt.Qt.Checked
                if displayNode and displayNode.GetVisibility()
                else qt.Qt.Unchecked
            )
        if entry["kind"] == "nodes":
            states = []
            for node in entry["nodes"]:
                displayNode = node.GetDisplayNode() if node else None
                states.append(bool(displayNode and displayNode.GetVisibility()))
            if states and all(states):
                return qt.Qt.Checked
            if any(states):
                return qt.Qt.PartiallyChecked
            return qt.Qt.Unchecked
        segmentationNode = entry.get("segmentationNode") or self._parameterNode.teethSegmentation
        displayNode = segmentationNode.GetDisplayNode() if segmentationNode else None
        if not displayNode or not displayNode.GetVisibility():
            return qt.Qt.Unchecked
        states = [
            bool(displayNode.GetSegmentVisibility(segmentId))
            for segmentId in entry["segmentIds"]
        ]
        if states and all(states):
            return qt.Qt.Checked
        if any(states):
            return qt.Qt.PartiallyChecked
        return qt.Qt.Unchecked

    def _updateWorkflowViewControls(self) -> None:
        if not hasattr(self, "ui"):
            return
        stageIndex = int(self.ui.workflowStageComboBox.currentIndex)
        active = bool(self._parameterNode and self.logic)
        self.ui.workflowViewGroupBox.visible = False
        self._setWorkflowViewAvailability(active)
        if not active:
            self._workflowViewEntriesByKey = {}
            self._updatingWorkflowViewUI = True
            try:
                self.ui.workflowViewPresetComboBox.clear()
                self.ui.workflowViewPresetComboBox.addItem(
                    _("View presets unavailable"),
                    "",
                )
                self.ui.workflowViewElementsListWidget.clear()
                self.ui.workflowViewStatusLabel.text = _(
                    "Element visibility controls need an active DENTOBOT case."
                )
                self.ui.workflowViewStatusLabel.styleSheet = "color: #6b6b6b;"
            finally:
                self._updatingWorkflowViewUI = False
            return
        entries = self._workflowViewEntries(stageIndex)
        self._workflowViewEntriesByKey = {
            entry["key"]: entry for entry in entries
        }
        self._updatingWorkflowViewUI = True
        try:
            comboBox = self.ui.workflowViewPresetComboBox
            definitions = self._workflowViewPresetDefinitions(stageIndex, entries)
            comboBox.clear()
            selectedIndex = 0
            for index, (key, label) in enumerate(definitions):
                comboBox.addItem(label, key)
                if key == self._workflowViewActivePresetKey:
                    selectedIndex = index
            comboBox.currentIndex = selectedIndex

            listWidget = self.ui.workflowViewElementsListWidget
            listWidget.clear()
            for entry in entries:
                item = qt.QListWidgetItem(entry["label"])
                item.setData(qt.Qt.UserRole, entry["key"])
                item.setFlags(item.flags() | qt.Qt.ItemIsUserCheckable)
                item.setCheckState(self._workflowViewEntryCheckState(entry))
                color = None
                if entry["kind"] == "node":
                    color = self.logic.lineageColorFromNode(entry["node"])
                elif entry["category"] in {"target_mask", "target_detail"}:
                    colorSource = self._parameterNode.trajectoryLine
                    color = self.logic.lineageColorFromNode(colorSource)
                if color:
                    item.setData(
                        qt.Qt.DecorationRole,
                        qt.QColor(
                            *(int(round(component * 255.0)) for component in color)
                        ),
                    )
                listWidget.addItem(item)
            self.ui.restoreWorkflowViewButton.enabled = bool(
                self._workflowViewPriorState
            )
            self.ui.frameWorkflowViewButton.enabled = bool(entries)
        finally:
            self._updatingWorkflowViewUI = False

    def _setWorkflowViewAvailability(self, active: bool) -> None:
        """Keep both display tabs available throughout the workflow."""

        active = bool(active)
        self.ui.workflowViewPresetComboBox.enabled = active
        self.ui.frameWorkflowViewButton.enabled = (
            active and bool(self._workflowViewEntriesByKey)
        )
        self.ui.restoreWorkflowViewButton.enabled = (
            active and bool(self._workflowViewPriorState)
        )
        if self._viewControlsTabWidget:
            self._viewControlsTabWidget.setTabEnabled(
                self._viewControlsElementsTabIndex,
                active,
            )
            self._viewControlsTabWidget.setTabEnabled(
                self._viewControlsDisplayTabIndex,
                True,
            )

    def _ensureWorkflowViewSnapshot(self) -> None:
        if self._workflowViewPriorState or not self.logic:
            return
        self._restoreAssistedTrajectoryFocus(updateUi=False)
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        self._workflowViewPriorState = self.logic.captureWorkflowDisplayState(
            self._parameterNode.teethSegmentation if self._parameterNode else None,
            self._workflowManagedDisplayNodes(),
        )
        segmentationStates = {}
        primary = self._parameterNode.teethSegmentation if self._parameterNode else None
        for segmentationNode in slicer.util.getNodesByClass("vtkMRMLSegmentationNode"):
            if segmentationNode is primary:
                continue
            segmentationStates[segmentationNode.GetID()] = (
                self.logic.captureWorkflowDisplayState(segmentationNode, [])
            )
        self._workflowViewPriorState["additionalSegmentations"] = segmentationStates
        self._workflowViewPriorState["volumeRendering"] = {
            entry["displayNode"].GetID(): bool(entry["displayNode"].GetVisibility())
            for entry in self._workflowViewEntriesByKey.values()
            if entry["kind"] == "volume_rendering"
            and entry["displayNode"].GetID()
        }

    def _extendWorkflowViewSnapshotForNewNodes(self, nodes: list) -> None:
        if not self._workflowViewPriorState or not self.logic:
            return
        captured = self.logic.captureWorkflowDisplayState(None, nodes)
        storedNodes = self._workflowViewPriorState.setdefault("nodes", {})
        for nodeId, state in captured.get("nodes", {}).items():
            storedNodes.setdefault(nodeId, state)

    def _applyWorkflowViewKeys(
        self,
        visibleKeys: set[str],
        *,
        activePresetKey: str,
        updateStatus: bool = True,
    ) -> None:
        if not self._parameterNode or not self.logic:
            return
        self._ensureWorkflowViewSnapshot()
        entries = list(self._workflowViewEntriesByKey.values())
        managedNodes = self._workflowManagedDisplayNodes()
        self._extendWorkflowViewSnapshotForNewNodes(managedNodes)
        visibleSegmentIds = {
            segmentId
            for entry in entries
            if entry["key"] in visibleKeys and entry["kind"] == "segments"
            and (
                entry.get("segmentationNode") is None
                or entry.get("segmentationNode") is self._parameterNode.teethSegmentation
            )
            for segmentId in entry["segmentIds"]
        }
        visibleNodeIds = set()
        for entry in entries:
            if entry["key"] not in visibleKeys:
                continue
            if entry["kind"] == "node":
                visibleNodeIds.add(entry["node"].GetID())
            elif entry["kind"] == "nodes":
                for node in entry["nodes"]:
                    if node and node.GetID():
                        visibleNodeIds.add(node.GetID())
            elif entry["kind"] == "volume_rendering":
                entry["displayNode"].SetVisibility(entry["key"] in visibleKeys)
        result = self.logic.applyWorkflowDisplaySelection(
            self._parameterNode.teethSegmentation,
            visibleSegmentIds,
            managedNodes,
            visibleNodeIds,
        )
        primarySegmentation = self._parameterNode.teethSegmentation
        segmentIdsByNode = {}
        for entry in entries:
            if entry["key"] not in visibleKeys or entry["kind"] != "segments":
                continue
            segmentationNode = entry.get("segmentationNode") or primarySegmentation
            if segmentationNode:
                segmentIdsByNode.setdefault(segmentationNode, set()).update(
                    entry["segmentIds"]
                )
        for segmentationNode in slicer.util.getNodesByClass("vtkMRMLSegmentationNode"):
            if segmentationNode is primarySegmentation:
                continue
            self.logic.applyWorkflowDisplaySelection(
                segmentationNode,
                segmentIdsByNode.get(segmentationNode, set()),
                [],
                set(),
            )
        self._workflowViewVisibleKeys = set(visibleKeys)
        self._workflowViewActivePresetKey = activePresetKey
        if activePresetKey == "trajectory_only":
            self._presentSelectedTrajectory(
                self._parameterNode.trajectoryLine,
                centerSlices=True,
            )
        self.ui.restorePlanningViewButton.enabled = bool(
            self._workflowViewPriorState
        )
        self._updateWorkflowViewControls()
        self._updateTemplateGuideVisibilityControls()
        if updateStatus:
            self.ui.workflowViewStatusLabel.text = _(
                "Display selection: %1 mask segment(s), %2 scene element(s), "
                "including any checked 3D volumes."
            ).replace(
                "%1", str(len(result["visibleSegmentIds"]))
            ).replace(
                "%2", str(len(visibleKeys) - len(result["visibleSegmentIds"]))
            )
            self.ui.workflowViewStatusLabel.styleSheet = "color: #207227;"

    def _applyWorkflowViewPreset(
        self,
        presetKey: str,
        *,
        updateStatus: bool = True,
    ) -> None:
        stageIndex = int(self.ui.workflowStageComboBox.currentIndex)
        entries = self._workflowViewEntries(stageIndex)
        self._workflowViewEntriesByKey = {
            entry["key"]: entry for entry in entries
        }
        visibleKeys = self._workflowViewKeysForPreset(
            presetKey,
            entries,
            stageIndex,
        )
        self._applyWorkflowViewKeys(
            visibleKeys,
            activePresetKey=presetKey,
            updateStatus=updateStatus,
        )

    def _activateWorkflowViewStage(
        self,
        stageIndex: int,
        *,
        stageChanged: bool,
    ) -> None:
        active = bool(self._parameterNode and self.logic)
        self._workflowViewStageIndex = stageIndex
        if stageIndex == 4:
            try:
                self._enableCrossViewNavigation()
            except RuntimeError as exc:
                self.ui.crossViewNavigationStatusLabel.text = str(exc)
                self.ui.crossViewNavigationStatusLabel.styleSheet = (
                    "color: #b00020;"
                )
        else:
            self._restoreCrossViewNavigation(updateUi=False)
        self._updateWorkflowViewControls()
        if stageChanged:
            if self.ui.autoWorkflowViewCheckBox.checked:
                self._applyWorkflowViewPreset("recommended")
            else:
                self._workflowViewActivePresetKey = "custom"
                self._workflowViewVisibleKeys = {
                    entry["key"]
                    for entry in self._workflowViewEntriesByKey.values()
                    if self._workflowViewEntryCheckState(entry)
                    != qt.Qt.Unchecked
                }
                self.ui.workflowViewStatusLabel.text = _(
                    "Current scene visibility is unchanged; choose a quick "
                    "view or toggle individual elements."
                )
                self.ui.workflowViewStatusLabel.styleSheet = "color: #1f5f99;"
                self._updateWorkflowViewControls()

    def _refreshWorkflowViewAfterStateChange(self) -> None:
        """Keep an active display preset authoritative as MRML inputs change."""

        stageIndex = int(self.ui.workflowStageComboBox.currentIndex)
        self._updateWorkflowViewControls()
        if not self._workflowViewPriorState:
            return
        if self._workflowViewActivePresetKey == "custom":
            availableKeys = set(self._workflowViewEntriesByKey)
            visibleKeys = self._workflowViewVisibleKeys & availableKeys
            self._applyWorkflowViewKeys(
                visibleKeys,
                activePresetKey="custom",
                updateStatus=False,
            )
        elif self._workflowViewActivePresetKey:
            self._applyWorkflowViewPreset(
                self._workflowViewActivePresetKey,
                updateStatus=False,
            )

    def onWorkflowViewPresetChanged(self, index: int) -> None:
        if self._updatingWorkflowViewUI or index < 0:
            return
        presetKey = str(self.ui.workflowViewPresetComboBox.itemData(index) or "")
        if not presetKey or presetKey in {"scene", "custom"}:
            return
        self._applyWorkflowViewPreset(presetKey)

    def onWorkflowViewElementChanged(self, item) -> None:
        if self._updatingWorkflowViewUI or not item or not self._parameterNode:
            return
        key = str(item.data(qt.Qt.UserRole) or "")
        entry = self._workflowViewEntriesByKey.get(key)
        if not entry:
            return
        self._ensureWorkflowViewSnapshot()
        visible = item.checkState() == qt.Qt.Checked
        if entry["kind"] == "node":
            displayNode = entry["node"].GetDisplayNode()
            if displayNode:
                displayNode.SetVisibility(visible)
        elif entry["kind"] == "nodes":
            for node in entry["nodes"]:
                displayNode = node.GetDisplayNode() if node else None
                if displayNode:
                    displayNode.SetVisibility(visible)
        elif entry["kind"] == "volume_rendering":
            entry["displayNode"].SetVisibility(visible)
        else:
            segmentationNode = entry.get("segmentationNode") or self._parameterNode.teethSegmentation
            displayNode = segmentationNode.GetDisplayNode() if segmentationNode else None
            if displayNode:
                wasModifying = displayNode.StartModify()
                try:
                    for segmentId in entry["segmentIds"]:
                        displayNode.SetSegmentVisibility(segmentId, visible)
                    segmentation = segmentationNode.GetSegmentation()
                    segmentIds = vtk.vtkStringArray()
                    segmentation.GetSegmentIDs(segmentIds)
                    hasVisibleSegment = any(
                        displayNode.GetSegmentVisibility(
                            segmentIds.GetValue(segmentIndex)
                        )
                        for segmentIndex in range(segmentIds.GetNumberOfValues())
                    )
                    displayNode.SetVisibility(hasVisibleSegment)
                    displayNode.SetVisibility2D(hasVisibleSegment)
                    displayNode.SetVisibility3D(hasVisibleSegment)
                finally:
                    displayNode.EndModify(wasModifying)
        if visible:
            self._workflowViewVisibleKeys.add(key)
        else:
            self._workflowViewVisibleKeys.discard(key)
        self._workflowViewActivePresetKey = "custom"
        self.ui.workflowViewStatusLabel.text = _(
            "Custom display selection; geometry and masks are unchanged."
        )
        self.ui.workflowViewStatusLabel.styleSheet = "color: #1f5f99;"
        self._updateWorkflowViewControls()
        self._updateTemplateGuideVisibilityControls()

    def _restoreWorkflowViewState(self, updateUi: bool = True) -> None:
        state = self._workflowViewPriorState
        self._workflowViewPriorState = None
        self._workflowViewActivePresetKey = ""
        self._workflowViewVisibleKeys.clear()
        if state and self.logic:
            for displayNodeId, visible in state.get("volumeRendering", {}).items():
                displayNode = slicer.mrmlScene.GetNodeByID(displayNodeId)
                if displayNode:
                    displayNode.SetVisibility(bool(visible))
            for segmentationState in state.get(
                "additionalSegmentations", {}
            ).values():
                self.logic.restoreWorkflowDisplayState(segmentationState)
            self.logic.restoreWorkflowDisplayState(state)
        if updateUi and hasattr(self, "ui"):
            self.ui.restorePlanningViewButton.enabled = False
            self.ui.workflowViewStatusLabel.text = _(
                "Previous segmentation and workflow-object display restored."
            )
            self.ui.workflowViewStatusLabel.styleSheet = "color: #207227;"
            self._updateWorkflowViewControls()
            self._updateTemplateGuideVisibilityControls()

    def onRestoreWorkflowView(self, checked: bool = False) -> None:
        del checked
        self._restoreWorkflowViewState(updateUi=True)

    def onFrameWorkflowView(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        boundsList = []
        for entry in self._workflowViewEntriesByKey.values():
            if self._workflowViewEntryCheckState(entry) == qt.Qt.Unchecked:
                continue
            if entry["kind"] == "node":
                bounds = [0.0] * 6
                entry["node"].GetRASBounds(bounds)
                boundsList.append(bounds)
            elif entry["kind"] == "nodes":
                for node in entry["nodes"]:
                    bounds = [0.0] * 6
                    node.GetRASBounds(bounds)
                    boundsList.append(bounds)
            elif entry["kind"] == "volume_rendering":
                bounds = [0.0] * 6
                entry["node"].GetRASBounds(bounds)
                boundsList.append(bounds)
            else:
                for segmentId in entry["segmentIds"]:
                    try:
                        boundsList.append(
                            self.logic.getSegmentationSegmentBoundsWorld(
                                entry.get("segmentationNode")
                                or self._parameterNode.teethSegmentation,
                                segmentId,
                            )
                        )
                    except ValueError:
                        continue
        finiteBounds = [
            tuple(float(value) for value in bounds)
            for bounds in boundsList
            if len(bounds) == 6
            and all(math.isfinite(float(value)) for value in bounds)
            and all(bounds[2 * axis + 1] > bounds[2 * axis] for axis in range(3))
        ]
        if not finiteBounds:
            self.ui.workflowViewStatusLabel.text = _(
                "No visible workflow geometry is available to frame."
            )
            self.ui.workflowViewStatusLabel.styleSheet = "color: #b36b00;"
            return
        combined = tuple(
            min(bounds[axis] for bounds in finiteBounds)
            if axis % 2 == 0
            else max(bounds[axis] for bounds in finiteBounds)
            for axis in range(6)
        )
        self._frameRasBoundsInViews(combined)
        self.ui.workflowViewStatusLabel.text = _(
            "Framed the currently visible workflow elements."
        )
        self.ui.workflowViewStatusLabel.styleSheet = "color: #207227;"

