    def onWorkflowStageChanged(self, index: int) -> None:
        if self._updatingWorkflowNavigationUI:
            return
        self._setWorkflowStage(index)

    def onPreviousWorkflowStage(self, checked: bool = False) -> None:
        del checked
        self._setWorkflowStage(self.ui.workflowStageComboBox.currentIndex - 1)

    def onNextWorkflowStage(self, checked: bool = False) -> None:
        del checked
        self._setWorkflowStage(self.ui.workflowStageComboBox.currentIndex + 1)

    def _setWorkflowStage(self, index: int, ensureVisible: bool = True) -> None:
        entries = self._workflowStageEntries()
        if not entries:
            return
        index = max(0, min(int(index), len(entries) - 1))
        previousIndex = int(self.ui.workflowStageComboBox.currentIndex)
        stageChanged = index != previousIndex
        self._updatingWorkflowNavigationUI = True
        try:
            self.ui.workflowStageComboBox.currentIndex = index
            activeSection = entries[index][1]
            for section in {entry[1] for entry in entries}:
                isActive = section is activeSection
                section.visible = isActive
                section.collapsed = not isActive
            self._configureTemplateModelingStage(index)
            self.ui.stepTitleLabel.text = entries[index][0].upper()
        finally:
            self._updatingWorkflowNavigationUI = False
        self._updateTrajectoryPlacementModeControls()
        self._updateWorkflowNavigationButtons()
        self._activateWorkflowViewStage(index, stageChanged=stageChanged)
        self._updateWorkflowNavigationRecommendation()
        self._updateRobotKeyboardShortcutState()
        if index == len(entries) - 1:
            # ROS status nodes are intentionally lazy: entering Step 6 is the
            # lifecycle boundary that may create them.
            self._updateRos2MotionControlStatus()
        if ensureVisible:
            qt.QTimer.singleShot(
                0,
                lambda section=entries[index][1]: self._ensureWorkflowSectionVisible(
                    section
                ),
            )

    def _onWorkflowSectionCollapsed(self, section, collapsed: bool) -> None:
        if self._updatingWorkflowNavigationUI:
            return
        currentIndex = int(self.ui.workflowStageComboBox.currentIndex)
        if self._workflowStageEntries()[currentIndex][1] is not section or not collapsed:
            return
        # A wizard stage is not a free accordion. Keep the one active section
        # open so the task area can never become an empty stack of headers.
        self._updatingWorkflowNavigationUI = True
        try:
            section.collapsed = False
        finally:
            self._updatingWorkflowNavigationUI = False

    def _configureTemplateModelingStage(self, stageIndex: int) -> None:
        """Expose support selection in 4B and surface refinement in 5A."""

        if not hasattr(self, "ui"):
            return
        selectionStage = stageIndex == 5
        surfaceStage = stageIndex == 7
        if not (selectionStage or surfaceStage):
            return
        self.ui.templateModelingCollapsibleButton.text = (
            _("Step 4B — Select Support Teeth and Build Anatomy Draft")
            if selectionStage
            else _("Step 5A — Define the Visible Support Surface")
        )
        self.ui.templateModelingDescriptionLabel.text = (
            _(
                "Select same-jaw support teeth and create the complete, world-RAS "
                "anatomy draft used by Step 4C collision screening. Source masks "
                "are never modified."
            )
            if selectionStage
            else _(
                "Refine the already selected support anatomy to the clinically "
                "visible erupted contact surface using the automatic plane or an "
                "editable boundary."
            )
        )
        selectionWidgets = (
            self.ui.templateTargetToothTitleLabel,
            self.ui.templateTargetToothValueLabel,
            self.ui.templateSupportTeethTitleLabel,
            self.ui.templateSupportTeethListWidget,
            self.ui.draftTemplateSupportModelTitleLabel,
            self.ui.draftTemplateSupportModelSelector,
            self.ui.reviewSegmentationForTemplateButton,
            self.ui.createDraftTemplateSupportModelButton,
            self.ui.deleteDraftTemplateSupportModelButton,
        )
        surfaceWidgets = (
            self.ui.templateSupportBoundaryCurveLabel,
            self.ui.templateSupportBoundaryCurveSelector,
            self.ui.templateSupportSelectionModeLabel,
            self.ui.templateSupportDirectionValueLabel,
            self.ui.flipTemplateSupportDirectionButton,
            self.ui.templateSupportCurveSamplingSpacingLabel,
            self.ui.templateSupportCurveSamplingSpacingSpinBox,
            self.ui.templateTerminalSupportCoverageLabel,
            self.ui.templateTerminalSupportCoverageSpinBox,
            self.ui.visibleTemplateSupportModelLabel,
            self.ui.visibleTemplateSupportModelSelector,
            self.ui.templateSupportBoundaryPlaneLabel,
            self.ui.templateSupportBoundaryPlaneSelector,
            self.ui.templateSupportPlaneDepthLabel,
            self.ui.templateSupportPlaneDepthSpinBox,
            self.ui.templateSupportCrownCapLabel,
            self.ui.templateSupportCrownCapSpinBox,
            self.ui.createTemplateSupportPlaneButton,
            self.ui.generateTemplateSupportBoundaryFromPlaneButton,
            self.ui.createTemplateSupportBoundaryButton,
            self.ui.generateVisibleTemplateSupportModelButton,
            self.ui.deleteTemplateSupportSelectionButton,
            self.ui.templateSupportSurfaceStatusLabel,
        )
        for widget in selectionWidgets:
            widget.visible = selectionStage
        for widget in surfaceWidgets:
            if widget:
                widget.visible = surfaceStage
        self.ui.templateSupportViewControlsGroupBox.visible = True

    def _ensureWorkflowSectionVisible(self, section) -> None:
        if not self._workflowContentScrollArea:
            return
        self._workflowContentScrollArea.ensureWidgetVisible(section, 0, 0)
        scrollBar = self._workflowContentScrollArea.verticalScrollBar()
        scrollBar.setValue(max(0, int(section.y) - 4))

    def _updateWorkflowNavigationButtons(self) -> None:
        count = len(self._workflowStageEntries())
        index = int(self.ui.workflowStageComboBox.currentIndex)
        self.ui.previousWorkflowStageButton.enabled = index > 0
        self.ui.nextWorkflowStageButton.enabled = 0 <= index < count - 1

    def _recommendedWorkflowStageIndex(self) -> int:
        if not self._parameterNode:
            return 0
        if not self._parameterNode.inputVolume:
            # A brand-new empty scene must open on the Case stage so the
            # operator can deliberately create a de-identified case or open a
            # saved scene. Once a case label exists, imaging is the next
            # recommendation, but the navigator never skips Case at first
            # initialization merely because no volume is loaded yet.
            return 1 if self._parameterNode.caseName.strip() else 0
        segmentationNode = self._parameterNode.teethSegmentation
        if not segmentationNode:
            return 2
        if self.logic.getSegmentationReviewState(segmentationNode) != "Reviewed":
            return 3
        trajectoryNode = self._parameterNode.trajectoryLine
        if not trajectoryNode or trajectoryNode.GetNumberOfDefinedControlPoints() < 2:
            return 4
        if not trajectoryNode.GetLocked():
            return 4
        supportModel = self._parameterNode.draftTemplateSupportModel
        if (
            not supportModel
            or supportModel.GetAttribute("DENTOBOT.GeometryState") != "Current"
        ):
            return 5
        dockingModel = self._parameterNode.targetDockingAssemblyModel
        if (
            not dockingModel
            or dockingModel.GetAttribute("DENTOBOT.GeometryState") != "Current"
            or dockingModel.GetAttribute("DENTOBOT.OrientationState") != "Confirmed"
        ):
            return 6
        if not self._parameterNode.visibleTemplateSupportModel:
            return 7
        if not self._parameterNode.finalPrintableTemplateModel:
            return 8
        return 9

    def _updateWorkflowNavigationRecommendation(self) -> None:
        recommendedIndex = self._recommendedWorkflowStageIndex()
        entries = self._workflowStageEntries()
        recommendation = _("Recommended next: %1").replace(
            "%1",
            entries[recommendedIndex][0],
        )
        self.ui.workflowStageStatusLabel.text = "●"
        self.ui.workflowStageStatusLabel.toolTip = recommendation
        self.ui.workflowStageStatusLabel.accessibleName = recommendation
        currentIndex = int(self.ui.workflowStageComboBox.currentIndex)
        indicatorColor = "#207227" if currentIndex == recommendedIndex else "#1f5f99"
        self.ui.workflowStageStatusLabel.styleSheet = (
            f"color: {indicatorColor}; font-size: 15px;"
        )
        self.ui.workflowStageComboBox.toolTip = _(
            "Jump to one workflow stage. %1"
        ).replace("%1", recommendation)
        if not self._workflowNavigationInitializedFromScene:
            self._workflowNavigationInitializedFromScene = True
            self._setWorkflowStage(recommendedIndex, ensureVisible=False)

    def cleanup(self) -> None:
        self._isCleaningUp = True
        self._setRobotTransformInteractionVisible(False)
        self._disableRobotKeyboardShortcuts()
        self._hideViewControlsPalette(preservePreference=True)
        self._cancelBackendProcess(updateStatus=False)
        self._restoreTrajectoryVerificationViewState(updateUi=False)
        self._restoreCrossViewNavigation(updateUi=False)
        self._restoreTemplateFinalizationViewState(updateUi=False)
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        self._restoreWorkflowViewState(updateUi=False)
        self.setParameterNode(None)
        self.removeObservers()
        self._sceneObserversActive = False
        release_default_ros2_node_singleton()
        if self._viewControlsPalette:
            self._viewControlsPalette.deleteLater()
            self._viewControlsPalette = None
            self._viewControlsTabWidget = None

    def enter(self) -> None:
        self._addSceneObservers()
        self.initializeParameterNode()
        self._updateRobotKeyboardShortcutState()
        qt.QTimer.singleShot(0, self._restoreViewControlsPaletteOnEnter)

    def exit(self) -> None:
        self._setRobotTransformInteractionVisible(False)
        self._disableRobotKeyboardShortcuts()
        self._hideViewControlsPalette(preservePreference=True)
        self._restoreTrajectoryVerificationViewState(updateUi=False)
        self._restoreCrossViewNavigation(updateUi=False)
        self._restoreAssistedTrajectoryFocus(updateUi=False)
        self._restoreTemplateFinalizationViewState(updateUi=False)
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        self._restoreWorkflowViewState(updateUi=False)
        self.setParameterNode(None)
        self._removeSceneObservers()

    def _addSceneObservers(self) -> None:
        if self._sceneObserversActive:
            return
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.StartCloseEvent, self.onSceneStartClose)
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.EndCloseEvent, self.onSceneEndClose)
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.EndImportEvent, self.onSceneEndImport)
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.StartSaveEvent, self.onSceneStartSave)
        self.addObserver(slicer.mrmlScene, slicer.mrmlScene.EndSaveEvent, self.onSceneEndSave)
        self._sceneObserversActive = True

    def _removeSceneObservers(self) -> None:
        if not self._sceneObserversActive:
            return
        self.removeObserver(slicer.mrmlScene, slicer.mrmlScene.StartCloseEvent, self.onSceneStartClose)
        self.removeObserver(slicer.mrmlScene, slicer.mrmlScene.EndCloseEvent, self.onSceneEndClose)
        self.removeObserver(slicer.mrmlScene, slicer.mrmlScene.EndImportEvent, self.onSceneEndImport)
        self.removeObserver(slicer.mrmlScene, slicer.mrmlScene.StartSaveEvent, self.onSceneStartSave)
        self.removeObserver(slicer.mrmlScene, slicer.mrmlScene.EndSaveEvent, self.onSceneEndSave)
        self._sceneObserversActive = False

    def onSceneStartClose(self, caller=None, event=None) -> None:
        del caller, event
        self._loadedCaseBundlePath = ""
        self._caseBundleRobotProfileCompatible = None
        self._workflowNavigationInitializedFromScene = False
        self._resumeTrajectoryVerificationAfterSave = False
        self._trajectoryVerificationResumeStateAfterSave = None
        self._resumeTemplateSupportBoundaryFocusAfterSave = False
        self._resumeAssistedTrajectoryFocusAfterSave = False
        self._resumeCrossViewNavigationAfterSave = False
        self._resumeWorkflowViewPresetAfterSave = ""
        self._resumeWorkflowViewPriorStateAfterSave = None
        self._resumeWorkflowViewVisibleKeysAfterSave.clear()
        self._restoreTrajectoryVerificationViewState(updateUi=False)
        self._restoreCrossViewNavigation(updateUi=False)
        self._restoreAssistedTrajectoryFocus(updateUi=False)
        self._restoreTemplateFinalizationViewState(updateUi=False)
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        self._restoreWorkflowViewState(updateUi=False)
        self._cancelBackendProcess(
            updateStatus=True,
            message=_("Backend process cancelled because the scene is closing."),
        )
        if self._step6MotionPreviewTimer is not None:
            self._step6MotionPreviewTimer.stop()
            self._step6MotionPreviewTimer = None
        self._step6MotionPreviewIndex = 0
        self._step6MotionPlan = None
        mrmlRobotModels = self.logic.robotModelNodes() if self.logic else []
        self.setParameterNode(None)
        try:
            if find_ros2_robot_by_name(ROS2_ROBOT_NAME) is not None:
                disconnected, message = disconnect_dentobot_motion_control(
                    mrmlRobotModels,
                )
                if not disconnected:
                    logging.warning(
                        "Could not fully disconnect DENTOBOT ROS motion control "
                        "before scene close: %s",
                        message,
                    )
        except Exception:
            logging.exception(
                "Could not disconnect DENTOBOT ROS motion control before scene close"
            )
        finally:
            # These MRML publishers/subscribers are Python-owned adapter state.
            # Release them before Slicer removes the ROS scene nodes so no stale
            # callback or wrapped VTK object survives into the replacement scene.
            shutdown_slicer_adapter()
        self._lastDisplayedVolumeId = None
        self._loadedVolumeDisplaySettingsByNodeId.clear()

    def onSceneEndClose(self, caller=None, event=None) -> None:
        del caller, event
        ensure_default_ros2_node_in_scene()
        qt.QTimer.singleShot(0, self._initializeAfterSceneClose)

    def _initializeAfterSceneClose(self) -> None:
        if self.parent.isEntered and self._parameterNode is None:
            self.initializeParameterNode()

    def onSceneEndImport(self, caller=None, event=None) -> None:
        """Rebind the persisted workflow node after every MRML scene import."""

        del caller, event
        marked = mark_slicer_ros2_runtime_nodes_transient()
        cleared = clear_legacy_dentobot_moveit_source_attributes()
        clearedActive = clear_stale_ros2_motion_active_attributes()
        if marked:
            logging.warning(
                "Excluded %d imported SlicerROS2 runtime node(s) from future "
                "DENTOBOT scene saves",
                marked,
            )
        if cleared:
            logging.warning(
                "Cleared legacy MoveIt persistence tags from %d DENTOBOT "
                "source model(s)",
                cleared,
            )
        if self.parent.isEntered:
            self.initializeParameterNode()
            if clearedActive:
                logging.warning(
                    "Cleared %d stale persisted ROS-active flag(s); no live "
                    "SlicerROS2 robot was restored",
                    clearedActive,
                )
            self._revalidateImportedStep6ContextAfterLoad()

    def _revalidateImportedStep6ContextAfterLoad(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        if not self._parameterNode.step6PlanningContextImported:
            return
        issues = self.logic.step6PlanningContextFreshnessIssues(
            self._parameterNode
        )
        if not issues:
            return
        self._parameterNode.step6PlanningContextImported = False
        message = _(
            "Saved Step 6 context is stale and was deactivated: %1 Return to "
            "the indicated upstream step, regenerate, verify, and import again."
        ).replace("%1", " ".join(issues))
        logging.error(message)
        self._updateStep6PlanningUi(message, error=True)

    def onSceneStartSave(self, caller=None, event=None) -> None:
        """Keep transient verification presentation out of saved MRB state."""

        del caller, event
        mark_slicer_ros2_runtime_nodes_transient()
        self._resumeRos2MotionActiveBaseIdsAfterSave = []
        for node in slicer.util.getNodesByClass("vtkMRMLLinearTransformNode"):
            if node.GetAttribute(ROS2_MOTION_ACTIVE_ATTRIBUTE) != "true":
                continue
            self._resumeRos2MotionActiveBaseIdsAfterSave.append(node.GetID())
            node.RemoveAttribute(ROS2_MOTION_ACTIVE_ATTRIBUTE)
        self._resumeTrajectoryVerificationAfterSave = bool(
            self._trajectoryVerificationEnabled
        )
        if self._resumeTrajectoryVerificationAfterSave:
            priorState = self._trajectoryVerificationPriorSliceState or {}
            sliceNodeId = priorState.get("sliceNodeId")
            sliceNode = (
                slicer.mrmlScene.GetNodeByID(sliceNodeId)
                if sliceNodeId
                else None
            )
            trajectoryNode = (
                self._parameterNode.trajectoryLine if self._parameterNode else None
            )
            self._trajectoryVerificationResumeStateAfterSave = (
                {
                    "trajectoryNodeId": trajectoryNode.GetID(),
                    "sliceNodeId": sliceNode.GetID(),
                    "sliceToRas": self._captureSliceToRasElements(sliceNode),
                    "angleDeg": self._trajectoryVerificationAngleDeg,
                }
                if trajectoryNode and sliceNode
                else None
            )
            self._restoreTrajectoryVerificationViewState(updateUi=False)
        self._resumeTemplateSupportBoundaryFocusAfterSave = bool(
            self._templateSupportBoundaryFocusState
        )
        if self._resumeTemplateSupportBoundaryFocusAfterSave:
            self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        self._resumeAssistedTrajectoryFocusAfterSave = bool(
            self._assistedTrajectoryFocusState
        )
        if self._resumeAssistedTrajectoryFocusAfterSave:
            self._restoreAssistedTrajectoryFocus(updateUi=False)
        self._resumeCrossViewNavigationAfterSave = bool(
            self._crossViewNavigationPriorState
        )
        if self._resumeCrossViewNavigationAfterSave:
            self._restoreCrossViewNavigation(updateUi=False)
        self._resumeWorkflowViewPresetAfterSave = (
            self._workflowViewActivePresetKey
            if self._workflowViewPriorState
            else ""
        )
        self._resumeWorkflowViewPriorStateAfterSave = (
            self._workflowViewPriorState
        )
        self._resumeWorkflowViewVisibleKeysAfterSave = set(
            self._workflowViewVisibleKeys
        )
        if self._resumeWorkflowViewPriorStateAfterSave:
            self._restoreWorkflowViewState(updateUi=False)

    def onSceneEndSave(self, caller=None, event=None) -> None:
        del caller, event
        for node_id in self._resumeRos2MotionActiveBaseIdsAfterSave:
            node = slicer.mrmlScene.GetNodeByID(node_id)
            if node is not None:
                node.SetAttribute(ROS2_MOTION_ACTIVE_ATTRIBUTE, "true")
        self._resumeRos2MotionActiveBaseIdsAfterSave = []
        workflowViewPreset = self._resumeWorkflowViewPresetAfterSave
        workflowViewState = self._resumeWorkflowViewPriorStateAfterSave
        workflowViewVisibleKeys = set(
            self._resumeWorkflowViewVisibleKeysAfterSave
        )
        self._resumeWorkflowViewPresetAfterSave = ""
        self._resumeWorkflowViewPriorStateAfterSave = None
        self._resumeWorkflowViewVisibleKeysAfterSave.clear()
        if workflowViewState and self._parameterNode:
            self._workflowViewPriorState = workflowViewState
            self._workflowViewVisibleKeys = workflowViewVisibleKeys
            self._updateWorkflowViewControls()
            if workflowViewPreset == "custom":
                self._applyWorkflowViewKeys(
                    workflowViewVisibleKeys,
                    activePresetKey="custom",
                    updateStatus=False,
                )
            elif workflowViewPreset:
                self._applyWorkflowViewPreset(
                    workflowViewPreset,
                    updateStatus=False,
                )
        if self._resumeTrajectoryVerificationAfterSave:
            self._resumeTrajectoryVerificationAfterSave = False
            resumeState = self._trajectoryVerificationResumeStateAfterSave
            self._trajectoryVerificationResumeStateAfterSave = None
            try:
                self._enableTrajectoryVerificationView()
                trajectoryNode = (
                    self._parameterNode.trajectoryLine if self._parameterNode else None
                )
                sliceNode = (
                    slicer.mrmlScene.GetNodeByID(resumeState["sliceNodeId"])
                    if resumeState
                    else None
                )
                if (
                    resumeState
                    and trajectoryNode
                    and trajectoryNode.GetID() == resumeState["trajectoryNodeId"]
                    and sliceNode
                ):
                    matrix = self._matrixFromElements(resumeState["sliceToRas"])
                    sliceNode.GetSliceToRAS().DeepCopy(matrix)
                    sliceNode.UpdateMatrices()
                    self._trajectoryVerificationAngleDeg = float(
                        resumeState["angleDeg"]
                    )
                    self._trajectoryVerificationAppliedTrajectoryNodeId = (
                        trajectoryNode.GetID()
                    )
                    self._trajectoryVerificationLastAppliedAngleDeg = (
                        self._trajectoryVerificationAngleDeg
                    )
                    self._updateTrajectoryVerificationControls()
            except (RuntimeError, ValueError) as exc:
                self._setTrajectoryVerificationEnabledUi(False)
                self._setTrajectoryVerificationStatus(str(exc), error=True)

        resumeTemplateFocus = self._resumeTemplateSupportBoundaryFocusAfterSave
        self._resumeTemplateSupportBoundaryFocusAfterSave = False
        if resumeTemplateFocus:
            try:
                self._startTemplateSupportBoundaryFocus()
                self._updateTemplateModeling()
            except (RuntimeError, ValueError) as exc:
                self._templateStatusWarning = str(exc)
                self._updateTemplateModeling()
        resumeAssistedFocus = self._resumeAssistedTrajectoryFocusAfterSave
        self._resumeAssistedTrajectoryFocusAfterSave = False
        if resumeAssistedFocus:
            try:
                self._startAssistedTrajectoryFocus()
            except (RuntimeError, ValueError):
                self._updateAssistedTrajectoryControls()
        resumeCrossViewNavigation = self._resumeCrossViewNavigationAfterSave
        self._resumeCrossViewNavigationAfterSave = False
        if resumeCrossViewNavigation:
            try:
                self._enableCrossViewNavigation()
            except RuntimeError:
                self._setCrossViewNavigationChecked(False)

    def initializeParameterNode(self) -> None:
        if not self.logic:
            return

        self.setParameterNode(self.logic.getParameterNode())
        if os.name != "nt":
            if self._parameterNode.inferenceDevice == "cuda:0":
                self._parameterNode.inferenceDevice = "cpu"

        newlyLoadedVolume = self._newlyLoadedDicomVolume()
        if newlyLoadedVolume:
            self._parameterNode.inputVolume = newlyLoadedVolume
        elif not self._parameterNode.inputVolume:
            latestVolume = self.logic.getLatestScalarVolumeNode()
            if latestVolume:
                self._parameterNode.inputVolume = latestVolume
        if not self._parameterNode.teethSegmentation:
            latestSegmentation = self.logic.getLatestTeethSegmentationNode()
            if latestSegmentation:
                self._parameterNode.teethSegmentation = latestSegmentation

        self._reconcileAuthoritativeSegmentationSourceVolume()

        self._updateFromParameterNode()

    def _reconcileAuthoritativeSegmentationSourceVolume(self) -> None:
        """Keep planning views on the selected segmentation's referenced CBCT."""

        if not self._parameterNode or not self.logic:
            return
        segmentationNode = self._parameterNode.teethSegmentation
        if not segmentationNode:
            return
        try:
            sourceVolume = self.logic.getSegmentationSourceVolume(
                segmentationNode
            )
        except ValueError:
            return
        if self._parameterNode.inputVolume is not sourceVolume:
            previousVolume = self._parameterNode.inputVolume
            logging.warning(
                "Reconciled workflow CBCT %s to authoritative segmentation source %s",
                previousVolume.GetID() if previousVolume else "none",
                sourceVolume.GetID(),
            )
            self._parameterNode.inputVolume = sourceVolume
        selectionNode = slicer.app.applicationLogic().GetSelectionNode()
        if selectionNode.GetActiveVolumeID() != sourceVolume.GetID():
            self._showVolumeInSliceViews(sourceVolume)

    def setParameterNode(self, parameterNode: DENTOWorkflowParameterNode | None) -> None:
        if self._workflowViewPriorState:
            self._restoreWorkflowViewState(updateUi=False)
        self._restoreAssistedTrajectoryFocus(updateUi=False)
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        if self._parameterNode:
            if self._parameterNodeGuiTag is not None:
                self._parameterNode.disconnectGui(self._parameterNodeGuiTag)
            self.removeObserver(self._parameterNode, vtk.vtkCommand.ModifiedEvent, self._updateFromParameterNode)

        self._parameterNode = parameterNode
        self._parameterNodeGuiTag = None

        if self._parameterNode:
            wasUpdating = self._updatingFromParameterNode
            self._updatingFromParameterNode = True
            try:
                self._parameterNodeGuiTag = self._parameterNode.connectGui(self.ui)
            finally:
                self._updatingFromParameterNode = wasUpdating
            self.addObserver(self._parameterNode, vtk.vtkCommand.ModifiedEvent, self._updateFromParameterNode)
            self._updateFromParameterNode()
        else:
            self._bindSegmentationReviewNode(None)
            self._clearSegmentationReview()
            self._bindPlanningTrajectoryNode(None)
            self._bindAssistedTrajectoryEntryNode(None)
            self._clearPlanning()
            self._bindTemplateSupportBoundaryNode(None)
            self._bindTemplateInsertionDirectionNode(None)
            self._bindSelectedGuideTrajectoryNodes([])
            self._clearTemplateModeling()
            self._clearTemplateGuide()
            self._clearTemplateFinalization()
            self._clearRobotPlacement()

    def _newlyLoadedDicomVolume(self) -> vtkMRMLScalarVolumeNode | None:
        if self._volumeNodeIdsBeforeDICOM is None or not self.logic:
            return None

        previousNodeIds = self._volumeNodeIdsBeforeDICOM
        self._volumeNodeIdsBeforeDICOM = None
        newVolumes = [
            node for node in self.logic.getScalarVolumeNodes()
            if node.GetID() not in previousNodeIds
        ]
        return newVolumes[-1] if newVolumes else None

    def _updateFromParameterNode(self, caller=None, event=None) -> None:
        del caller, event
        if (
            self._updatingFromParameterNode
            or self._restoringTrajectoryAssociation
            or not self._parameterNode
            or not self.logic
        ):
            return
        self._updatingFromParameterNode = True
        try:
            self._updateFromParameterNodeOnce()
        finally:
            self._updatingFromParameterNode = False

    def _updateFromParameterNodeOnce(self) -> None:
        """Perform one non-reentrant parameter-to-widget synchronization."""

        volumeNode = self._parameterNode.inputVolume
        self.ui.showVolumeButton.enabled = volumeNode is not None
        self._updateBackendControls()
        self._bindSegmentationReviewNode(self._parameterNode.teethSegmentation)
        self._updateSegmentationReview()
        self._bindPlanningTrajectoryNode(self._parameterNode.trajectoryLine)
        self._bindAssistedTrajectoryEntryNode(
            self._parameterNode.assistedTrajectoryEntries
        )
        self._updatePlanning()
        self._updateTargetDocking()
        self._bindTemplateSupportBoundaryNode(
            self._parameterNode.templateSupportBoundaryCurve
        )
        self._bindTemplateInsertionDirectionNode(
            self._parameterNode.templateInsertionDirection
        )
        self._updateTemplateModeling()
        self._updateTemplateGuide()
        self._updateTemplateFinalization()
        self._bindDraftJawLandmarksNode(self._parameterNode.draftJawLandmarks)
        self._updateRobotPlacement()
        self._updateWorkflowNavigationRecommendation()
        self._refreshWorkflowViewAfterStateChange()

        if not volumeNode:
            self._setMetadataPlaceholders()
            self.ui.statusLabel.text = _("No CBCT volume selected.")
            self.ui.statusLabel.styleSheet = "color: #b36b00;"
            self._lastDisplayedVolumeId = None
            return

        try:
            metadata = self.logic.getVolumeMetadata(volumeNode)
        except ValueError as exc:
            self._setMetadataPlaceholders()
            self.ui.statusLabel.text = str(exc)
            self.ui.statusLabel.styleSheet = "color: #b00020;"
            return

        self.ui.volumeNameValueLabel.text = metadata["name"]
        self.ui.dimensionsValueLabel.text = metadata["dimensions"]
        self.ui.spacingValueLabel.text = metadata["spacing"]
        self.ui.scalarTypeValueLabel.text = metadata["scalarType"]
        self.ui.scalarRangeValueLabel.text = metadata["scalarRange"]
        self.ui.orientationValueLabel.text = metadata["orientation"]
        self.ui.geometryStatusValueLabel.text = metadata["geometryStatus"]
        self.ui.statusLabel.text = _("Ready. The selected volume is available for inspection.")
        self.ui.statusLabel.styleSheet = "color: #207227;"

        if volumeNode.GetID() != self._lastDisplayedVolumeId:
            self._showVolumeInSliceViews(volumeNode)

    def _bindSegmentationReviewNode(self, segmentationNode) -> None:
        """Observe the selected segmentation and its display state exactly once."""

        sourceVolume = None
        sourceVolumeDisplayNode = None
        if segmentationNode and self.logic:
            try:
                sourceVolume = self.logic.getSegmentationSourceVolume(
                    segmentationNode
                )
            except ValueError:
                pass
            if sourceVolume:
                sourceVolume.CreateDefaultDisplayNodes()
                sourceVolumeDisplayNode = sourceVolume.GetDisplayNode()
        if segmentationNode is self._reviewSegmentationNode:
            displayNode = segmentationNode.GetDisplayNode() if segmentationNode else None
            if (
                displayNode is self._reviewDisplayNode
                and sourceVolumeDisplayNode is self._reviewSourceVolumeDisplayNode
            ):
                return

        if self._reviewSegmentationNode:
            self.removeObserver(
                self._reviewSegmentationNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onReviewSegmentationModified,
            )
            for segmentationEvent in (
                slicer.vtkSegmentation.SourceRepresentationModified,
                slicer.vtkSegmentation.SegmentAdded,
                slicer.vtkSegmentation.SegmentRemoved,
            ):
                self.removeObserver(
                    self._reviewSegmentationNode,
                    segmentationEvent,
                    self._onReviewSegmentationContentModified,
                )
        if self._reviewDisplayNode:
            self.removeObserver(
                self._reviewDisplayNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onReviewDisplayModified,
            )
        if self._reviewSourceVolumeDisplayNode:
            self.removeObserver(
                self._reviewSourceVolumeDisplayNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onReviewSourceVolumeDisplayModified,
            )

        self._reviewSegmentationNode = segmentationNode
        self._reviewDisplayNode = None
        self._reviewSourceVolumeNode = None
        self._reviewSourceVolumeDisplayNode = None

        if not segmentationNode:
            return

        segmentationNode.CreateDefaultDisplayNodes()
        self._reviewDisplayNode = segmentationNode.GetDisplayNode()
        self.addObserver(
            segmentationNode,
            vtk.vtkCommand.ModifiedEvent,
            self._onReviewSegmentationModified,
        )
        for segmentationEvent in (
            slicer.vtkSegmentation.SourceRepresentationModified,
            slicer.vtkSegmentation.SegmentAdded,
            slicer.vtkSegmentation.SegmentRemoved,
        ):
            self.addObserver(
                segmentationNode,
                segmentationEvent,
                self._onReviewSegmentationContentModified,
            )
        if self._reviewDisplayNode:
            self.addObserver(
                self._reviewDisplayNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onReviewDisplayModified,
            )
        self._reviewSourceVolumeNode = sourceVolume
        self._reviewSourceVolumeDisplayNode = sourceVolumeDisplayNode
        if self._reviewSourceVolumeDisplayNode:
            volumeNodeId = sourceVolume.GetID()
            if volumeNodeId not in self._loadedVolumeDisplaySettingsByNodeId:
                self._loadedVolumeDisplaySettingsByNodeId[volumeNodeId] = (
                    self.logic.getScalarVolumeDisplaySettings(sourceVolume)
                )
            self.addObserver(
                self._reviewSourceVolumeDisplayNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onReviewSourceVolumeDisplayModified,
            )

    def _onReviewSegmentationModified(self, caller=None, event=None) -> None:
        if not self._updatingSegmentationReviewUI:
            self._rebuildSegmentTree()
            self._refreshSegmentationInspection()
            self._updatePlanning()
            self._updateTemplateModeling()

    def _onReviewDisplayModified(self, caller=None, event=None) -> None:
        if not self._updatingSegmentationReviewUI:
            self._syncSegmentationDisplayControls()

    def _onReviewSourceVolumeDisplayModified(self, caller=None, event=None) -> None:
        if not self._updatingSegmentationReviewUI:
            self._syncSegmentationDisplayControls()

    def _onReviewSegmentationContentModified(
        self,
        caller=None,
        event=None,
    ) -> None:
        del event
        if (
            self._processingSegmentationContentChange
            or not self.logic
            or not self._reviewSegmentationNode
        ):
            return
        self._processingSegmentationContentChange = True
        self._updatingSegmentationReviewUI = True
        try:
            wasReviewed = self.logic.invalidateSegmentationReviewAfterEdit(
                self._reviewSegmentationNode
            )
        finally:
            self._updatingSegmentationReviewUI = False
            self._processingSegmentationContentChange = False

        self._rebuildSegmentTree()
        self._refreshSegmentationInspection()
        self._validTrajectoryPointsByNodeId.clear()
        self._updatePlanning()
        self._markCurrentDraftTemplateModelStale(
            _("Source segmentation content changed.")
        )
        self._updateTemplateModeling()
        self.ui.segmentationReviewStatusLabel.text = (
            _(
                "Mask content changed. Review state was reset to "
                "Needs Correction."
            )
            if wasReviewed
            else _(
                "Mask content changed. Inference metrics now describe the "
                "pre-edit result."
            )
        )
        self.ui.segmentationReviewStatusLabel.styleSheet = "color: #b36b00;"

    def _clearSegmentationReview(self) -> None:
        if not hasattr(self, "ui"):
            return
        self._updatingSegmentationReviewUI = True
        try:
            self._segmentReviewRecordsById = {}
            self.ui.segmentTreeWidget.clear()
            self.ui.segmentSearchLineEdit.clear()
            self.ui.segmentation2DCheckBox.checked = False
            self.ui.segmentation3DCheckBox.checked = False
            self.ui.segmentation2DOpacitySlider.value = 0
            self.ui.segmentation3DOpacitySlider.value = 0
            self.ui.segmentation2DOpacityValueLabel.text = _("0%")
            self.ui.segmentation3DOpacityValueLabel.text = _("0%")
            self.ui.segmentation2DRenderingModeComboBox.currentIndex = 0
            self.ui.cbctInterpolationCheckBox.checked = False
            self.ui.cbctAutoWindowLevelCheckBox.checked = False
            self.ui.cbctWindowSpinBox.value = 1.0
            self.ui.cbctLevelSpinBox.value = 0.0
            if self._cbctWindowSlider:
                self._cbctWindowSlider.enabled = False
                self._cbctWindowSlider.minimum = 1
                self._cbctWindowSlider.maximum = 10
                self._cbctWindowSlider.value = 10
                self._cbctWindowSliderValueLabel.text = _("--")
            if self._cbctLevelSlider:
                self._cbctLevelSlider.enabled = False
                self._cbctLevelSlider.minimum = -10
                self._cbctLevelSlider.maximum = 10
                self._cbctLevelSlider.value = 0
                self._cbctLevelSliderValueLabel.text = _("--")
            self.ui.cbctInvertGrayscaleCheckBox.checked = False
            self.ui.cbctGrayscaleDisplayStatusLabel.text = _(
                "Select a referenced source CBCT."
            )
            self.ui.cbctGrayscaleDisplayStatusLabel.styleSheet = ""
            self.ui.segmentationDisplayQualityStatusLabel.text = _(
                "Select a segmentation to configure review rendering."
            )
            self.ui.segmentationDisplayQualityStatusLabel.styleSheet = ""
            self._setSelectedSegmentDetailPlaceholders()
            self._setSegmentationProvenancePlaceholders()
            self._reviewMetadataWarning = ""
            self.ui.segmentationReviewStatusLabel.text = _(
                "Select a segmentation to review."
            )
            self.ui.segmentationReviewStatusLabel.styleSheet = "color: #b36b00;"
            self._setSegmentationReviewControlsEnabled(False)
            if self._applySceneDisplayPresetButton:
                self._applySceneDisplayPresetButton.enabled = bool(
                    self._parameterNode
                    and self._parameterNode.sceneDisplayPresetJson.strip()
                )
        finally:
            self._updatingSegmentationReviewUI = False

    def _setSegmentationReviewControlsEnabled(self, enabled: bool) -> None:
        for widget in (
            self.ui.segmentSearchLineEdit,
            self.ui.segmentTreeWidget,
            self.ui.showAllSegmentsButton,
            self.ui.hideAllSegmentsButton,
            self.ui.segmentation2DCheckBox,
            self.ui.segmentation3DCheckBox,
            self.ui.segmentation2DOpacitySlider,
            self.ui.segmentation3DOpacitySlider,
            self.ui.segmentation2DRenderingModeComboBox,
            self.ui.cbctInterpolationCheckBox,
            self.ui.cbctAutoWindowLevelCheckBox,
            self.ui.cbctWindowSpinBox,
            self.ui.cbctLevelSpinBox,
            self.ui.cbctInvertGrayscaleCheckBox,
            self.ui.cbctRestoreLoadedDisplayButton,
            self.ui.reviewStateComboBox,
        ):
            widget.enabled = enabled
        if self._cbctWindowSlider:
            self._cbctWindowSlider.enabled = bool(
                enabled and not self.ui.cbctAutoWindowLevelCheckBox.checked
            )
        if self._cbctLevelSlider:
            self._cbctLevelSlider.enabled = bool(
                enabled and not self.ui.cbctAutoWindowLevelCheckBox.checked
            )
        currentItem = self.ui.segmentTreeWidget.currentItem()
        hasSelectedSegment = bool(
            enabled and currentItem and currentItem.data(0, qt.Qt.UserRole)
        )
        self.ui.isolateSegmentButton.enabled = hasSelectedSegment
        self.ui.editSelectedSegmentButton.enabled = hasSelectedSegment

    def _updateSegmentationReview(self) -> None:
        if not self._reviewSegmentationNode or not self.logic:
            self._clearSegmentationReview()
            return
        self._updatingSegmentationReviewUI = True
        try:
            self._reviewMetadataWarning = (
                self.logic.ensureSegmentationReviewMetadata(
                    self._reviewSegmentationNode
                )
            )
            self.logic.ensureSegmentationDisplayQualityDefaults(
                self._reviewSegmentationNode
            )
        finally:
            self._updatingSegmentationReviewUI = False
        self._bindSegmentationReviewNode(self._reviewSegmentationNode)
        self._setSegmentationReviewControlsEnabled(True)
        self._rebuildSegmentTree()
        self._syncSegmentationDisplayControls()
        self._refreshSegmentationInspection()

    def _rebuildSegmentTree(self) -> None:
        if not self._reviewSegmentationNode or not self.logic:
            self._clearSegmentationReview()
            return

        selectedItem = self.ui.segmentTreeWidget.currentItem()
        selectedSegmentId = (
            str(selectedItem.data(0, qt.Qt.UserRole))
            if selectedItem and selectedItem.data(0, qt.Qt.UserRole)
            else None
        )
        records = self.logic.getSegmentationReviewRecords(
            self._reviewSegmentationNode
        )
        self._segmentReviewRecordsById = {
            record["segmentId"]: record for record in records
        }

        self._updatingSegmentationReviewUI = True
        try:
            treeWidget = self.ui.segmentTreeWidget
            treeWidget.clear()
            groups: dict[str, object] = {}
            selectedTreeItem = None
            displayNode = self._reviewSegmentationNode.GetDisplayNode()

            for record in records:
                category = record["category"]
                groupItem = groups.get(category)
                if groupItem is None:
                    groupItem = qt.QTreeWidgetItem(treeWidget)
                    groupItem.setText(0, category)
                    groupItem.setFirstColumnSpanned(True)
                    groupFont = groupItem.font(0)
                    groupFont.setBold(True)
                    groupItem.setFont(0, groupFont)
                    groups[category] = groupItem

                segmentItem = qt.QTreeWidgetItem(groupItem)
                segmentItem.setText(0, record["displayName"])
                segmentItem.setText(1, record["sourceName"])
                segmentItem.setToolTip(
                    0,
                    _("Source label: %1").replace("%1", record["sourceName"]),
                )
                segmentItem.setData(0, qt.Qt.UserRole, record["segmentId"])
                segmentItem.setCheckState(
                    0,
                    qt.Qt.Checked
                    if displayNode.GetSegmentVisibility(record["segmentId"])
                    else qt.Qt.Unchecked,
                )
                if record["segmentId"] == selectedSegmentId:
                    selectedTreeItem = segmentItem

            treeWidget.expandAll()
            if selectedTreeItem:
                treeWidget.setCurrentItem(selectedTreeItem)
        finally:
            self._updatingSegmentationReviewUI = False

        self._applySegmentFilter(self.ui.segmentSearchLineEdit.text)
        self._updateSegmentationReviewStatus()

    def _syncSegmentationDisplayControls(self) -> None:
        if not self._reviewSegmentationNode:
            self._clearSegmentationReview()
            return
        displayNode = self._reviewSegmentationNode.GetDisplayNode()
        if not displayNode:
            self._clearSegmentationReview()
            return

        self._updatingSegmentationReviewUI = True
        try:
            self.ui.segmentation2DCheckBox.checked = bool(
                displayNode.GetVisibility2D()
            )
            self.ui.segmentation3DCheckBox.checked = bool(
                displayNode.GetVisibility3D()
            )
            opacity2D = int(round(float(displayNode.GetOpacity2DFill()) * 100.0))
            opacity3D = int(round(float(displayNode.GetOpacity3D()) * 100.0))
            self.ui.segmentation2DOpacitySlider.value = opacity2D
            self.ui.segmentation3DOpacitySlider.value = opacity3D
            self.ui.segmentation2DOpacityValueLabel.text = f"{opacity2D}%"
            self.ui.segmentation3DOpacityValueLabel.text = f"{opacity3D}%"
            renderingMode = self.logic.getSegmentation2DRenderingMode(
                self._reviewSegmentationNode
            )
            self.ui.segmentation2DRenderingModeComboBox.currentIndex = (
                0
                if renderingMode
                == self.logic.SEGMENTATION_2D_RENDERING_MODE_SMOOTH
                else 1
            )
            sourceVolume = None
            try:
                sourceVolume = self.logic.getSegmentationSourceVolume(
                    self._reviewSegmentationNode
                )
            except ValueError:
                pass
            cbctInterpolated = bool(
                sourceVolume
                and self.logic.getScalarVolumeInterpolation(sourceVolume)
            )
            self.ui.cbctInterpolationCheckBox.checked = cbctInterpolated
            if sourceVolume:
                displaySettings = self.logic.getScalarVolumeDisplaySettings(
                    sourceVolume
                )
                scalarRange = sourceVolume.GetImageData().GetScalarRange()
                scalarSpan = max(float(scalarRange[1] - scalarRange[0]), 1.0)
                windowMaximum = max(
                    scalarSpan * 20.0,
                    float(displaySettings["window"]) * 2.0,
                    100.0,
                )
                levelMargin = scalarSpan * 10.0
                self.ui.cbctWindowSpinBox.minimum = 0.01
                self.ui.cbctWindowSpinBox.maximum = windowMaximum
                self.ui.cbctWindowSpinBox.singleStep = max(
                    scalarSpan / 100.0,
                    0.1,
                )
                self.ui.cbctLevelSpinBox.minimum = (
                    float(scalarRange[0]) - levelMargin
                )
                self.ui.cbctLevelSpinBox.maximum = (
                    float(scalarRange[1]) + levelMargin
                )
                self.ui.cbctLevelSpinBox.singleStep = max(
                    scalarSpan / 100.0,
                    0.1,
                )
                sliderScale = float(self._displaySliderScale)
                displayWindow = float(displaySettings["window"])
                displayLevel = float(displaySettings["level"])
                self._cbctWindowSlider.minimum = 1
                self._cbctWindowSlider.maximum = max(
                    1,
                    int(math.ceil(windowMaximum * sliderScale)),
                )
                self._cbctLevelSlider.minimum = int(
                    math.floor(
                        min(
                            float(scalarRange[0]) - levelMargin,
                            displayLevel - displayWindow,
                        )
                        * sliderScale
                    )
                )
                self._cbctLevelSlider.maximum = int(
                    math.ceil(
                        max(
                            float(scalarRange[1]) + levelMargin,
                            displayLevel + displayWindow,
                        )
                        * sliderScale
                    )
                )
                self.ui.cbctAutoWindowLevelCheckBox.checked = bool(
                    displaySettings["autoWindowLevel"]
                )
                self.ui.cbctWindowSpinBox.value = float(
                    displaySettings["window"]
                )
                self.ui.cbctLevelSpinBox.value = float(
                    displaySettings["level"]
                )
                windowValue = displayWindow
                levelValue = displayLevel
                self._cbctWindowSlider.value = int(
                    round(windowValue * sliderScale)
                )
                self._cbctLevelSlider.value = int(
                    round(levelValue * sliderScale)
                )
                self._cbctWindowSliderValueLabel.text = f"{windowValue:.1f}"
                self._cbctLevelSliderValueLabel.text = f"{levelValue:.1f}"
                self.ui.cbctInvertGrayscaleCheckBox.checked = bool(
                    displaySettings["invertedGrayscale"]
                )
                self.ui.cbctGrayscaleDisplayStatusLabel.text = _(
                    "Display only — window %1, level %2, %3 grayscale; "
                    "source voxels unchanged."
                ).replace(
                    "%1", f"{float(displaySettings['window']):.2f}"
                ).replace(
                    "%2", f"{float(displaySettings['level']):.2f}"
                ).replace(
                    "%3",
                    _("inverted")
                    if displaySettings["invertedGrayscale"]
                    else _("standard"),
                )
                self.ui.cbctGrayscaleDisplayStatusLabel.styleSheet = (
                    "color: #1f5f99;"
                )
            else:
                self.ui.cbctAutoWindowLevelCheckBox.checked = False
                self.ui.cbctWindowSpinBox.value = 1.0
                self.ui.cbctLevelSpinBox.value = 0.0
                self._cbctWindowSlider.minimum = 1
                self._cbctWindowSlider.maximum = 10
                self._cbctWindowSlider.value = 10
                self._cbctLevelSlider.minimum = -10
                self._cbctLevelSlider.maximum = 10
                self._cbctLevelSlider.value = 0
                self._cbctWindowSliderValueLabel.text = _("--")
                self._cbctLevelSliderValueLabel.text = _("--")
                self.ui.cbctInvertGrayscaleCheckBox.checked = False
                self.ui.cbctGrayscaleDisplayStatusLabel.text = _(
                    "The segmentation has no available source CBCT reference."
                )
                self.ui.cbctGrayscaleDisplayStatusLabel.styleSheet = (
                    "color: #b36b00;"
                )
            hasSourceVolume = bool(sourceVolume)
            self.ui.cbctAutoWindowLevelCheckBox.enabled = hasSourceVolume
            self.ui.cbctWindowSpinBox.enabled = bool(
                hasSourceVolume
                and not self.ui.cbctAutoWindowLevelCheckBox.checked
            )
            self.ui.cbctLevelSpinBox.enabled = bool(
                hasSourceVolume
                and not self.ui.cbctAutoWindowLevelCheckBox.checked
            )
            self._cbctWindowSlider.enabled = bool(
                hasSourceVolume
                and not self.ui.cbctAutoWindowLevelCheckBox.checked
            )
            self._cbctLevelSlider.enabled = bool(
                hasSourceVolume
                and not self.ui.cbctAutoWindowLevelCheckBox.checked
            )
            self.ui.cbctInvertGrayscaleCheckBox.enabled = hasSourceVolume
            self.ui.cbctInterpolationCheckBox.enabled = hasSourceVolume
            self.ui.cbctRestoreLoadedDisplayButton.enabled = bool(
                hasSourceVolume
                and sourceVolume.GetID()
                in self._loadedVolumeDisplaySettingsByNodeId
            )
            self._applySceneDisplayPresetButton.enabled = bool(
                self._parameterNode
                and self._parameterNode.sceneDisplayPresetJson.strip()
            )
            presetJson = (
                self._parameterNode.sceneDisplayPresetJson.strip()
                if self._parameterNode
                else ""
            )
            if presetJson:
                try:
                    savedPreset = json.loads(presetJson)
                    savedUtc = str(savedPreset.get("savedUtc") or _("unknown time"))
                    self._displayPresetStatusLabel.text = _(
                        "A case display preset is stored in this scene (%1)."
                    ).replace("%1", savedUtc)
                    self._displayPresetStatusLabel.styleSheet = "color: #207227;"
                except (TypeError, ValueError, json.JSONDecodeError):
                    self._displayPresetStatusLabel.text = _(
                        "The stored case display preset is invalid; save a new preset."
                    )
                    self._displayPresetStatusLabel.styleSheet = "color: #b00020;"
            else:
                self._displayPresetStatusLabel.text = _(
                    "Current MRML display settings save with the scene; no "
                    "separate preset has been stored yet."
                )
                self._displayPresetStatusLabel.styleSheet = "color: #1f5f99;"
            if renderingMode == self.logic.SEGMENTATION_2D_RENDERING_MODE_SMOOTH:
                modeText = _(
                    "Optional derived surface preview; non-authoritative and "
                    "not additional anatomical resolution."
                )
                modeColor = "#b36b00"
            else:
                modeText = _(
                    "Authoritative native binary-mask pixels, including the "
                    "acquired voxel stair-steps."
                )
                modeColor = "#207227"
            if sourceVolume:
                spacingText = " × ".join(
                    f"{float(value):.2f}" for value in sourceVolume.GetSpacing()
                )
                cbctText = _(
                    " CBCT: %1 mm voxels; interpolation %2."
                ).replace("%1", spacingText).replace(
                    "%2", _("on") if cbctInterpolated else _("off")
                )
            else:
                cbctText = _(" Source CBCT reference is unavailable.")
            self.ui.segmentationDisplayQualityStatusLabel.text = (
                modeText + cbctText
            )
            self.ui.segmentationDisplayQualityStatusLabel.styleSheet = (
                f"color: {modeColor};"
            )

            treeWidget = self.ui.segmentTreeWidget
            for groupIndex in range(treeWidget.topLevelItemCount):
                groupItem = treeWidget.topLevelItem(groupIndex)
                for childIndex in range(groupItem.childCount()):
                    segmentItem = groupItem.child(childIndex)
                    segmentId = str(segmentItem.data(0, qt.Qt.UserRole))
                    segmentItem.setCheckState(
                        0,
                        qt.Qt.Checked
                        if displayNode.GetSegmentVisibility(segmentId)
                        else qt.Qt.Unchecked,
                    )
        finally:
            self._updatingSegmentationReviewUI = False
        self._updateSegmentationReviewStatus()

    def _applySegmentFilter(self, filterText: str) -> None:
        filterText = str(filterText).strip().lower()
        treeWidget = self.ui.segmentTreeWidget
        for groupIndex in range(treeWidget.topLevelItemCount):
            groupItem = treeWidget.topLevelItem(groupIndex)
            visibleChildren = 0
            for childIndex in range(groupItem.childCount()):
                segmentItem = groupItem.child(childIndex)
                segmentId = str(segmentItem.data(0, qt.Qt.UserRole))
                record = self._segmentReviewRecordsById.get(segmentId, {})
                matches = not filterText or filterText in record.get("searchText", "")
                segmentItem.setHidden(not matches)
                visibleChildren += int(matches)
            groupItem.setHidden(visibleChildren == 0)
        self._updateSegmentationReviewStatus()

    def _updateSegmentationReviewStatus(self) -> None:
        if not self._reviewSegmentationNode:
            return
        displayNode = self._reviewSegmentationNode.GetDisplayNode()
        if not displayNode:
            return
        totalCount = len(self._segmentReviewRecordsById)
        visibleCount = sum(
            int(displayNode.GetSegmentVisibility(segmentId))
            for segmentId in self._segmentReviewRecordsById
        )
        matchingCount = sum(
            1
            for record in self._segmentReviewRecordsById.values()
            if not self.ui.segmentSearchLineEdit.text.strip().lower()
            or self.ui.segmentSearchLineEdit.text.strip().lower()
            in record["searchText"]
        )
        self.ui.segmentationReviewStatusLabel.text = (
            _("%1 of %2 labels match; %3 are visible.")
            .replace("%1", str(matchingCount))
            .replace("%2", str(totalCount))
            .replace("%3", str(visibleCount))
        )
        self.ui.segmentationReviewStatusLabel.styleSheet = "color: #207227;"

    def _selectedReviewSegmentId(self) -> str | None:
        currentItem = self.ui.segmentTreeWidget.currentItem()
        if not currentItem:
            return None
        value = currentItem.data(0, qt.Qt.UserRole)
        return str(value) if value else None

    def onReviewSegmentationSelectionChanged(self, segmentationNode) -> None:
        if (
            not self._parameterNode
            or self._restoringTrajectoryAssociation
            or self._updatingFromParameterNode
        ):
            return
        currentNode = self._parameterNode.teethSegmentation
        currentNodeId = currentNode.GetID() if currentNode else None
        selectedNodeId = segmentationNode.GetID() if segmentationNode else None
        if currentNodeId != selectedNodeId:
            self._restoringTrajectoryAssociation = True
            wasModifying = self._parameterNode.StartModify()
            try:
                self._markCurrentDraftTemplateModelStale(
                    _("Authoritative source segmentation changed.")
                )
                if self._parameterNode.trajectoryLine and self.logic:
                    self.logic.clearTrajectoryTarget(
                        self._parameterNode.trajectoryLine
                    )
                    self._parameterNode.trajectoryLine.SetNodeReferenceID(
                        self.logic.TARGET_BOUNDS_ROI_REFERENCE_ROLE,
                        None,
                    )
                if (
                    self._parameterNode.targetToothBoundsRoi
                    and self._parameterNode.targetToothBoundsRoi.GetDisplayNode()
                ):
                    self._parameterNode.targetToothBoundsRoi.GetDisplayNode(
                    ).SetVisibility(False)
                self._parameterNode.targetToothSegmentId = ""
                self._validTrajectoryPointsByNodeId.clear()
                self._planningConstraintWarning = ""
                self._parameterNode.templateSupportToothSegmentIdsJson = "[]"
                self._parameterNode.teethSegmentation = segmentationNode
                self._reconcileAuthoritativeSegmentationSourceVolume()
            finally:
                self._parameterNode.EndModify(wasModifying)
                self._restoringTrajectoryAssociation = False
        self._bindSegmentationReviewNode(segmentationNode)
        self._updateSegmentationReview()
        # Parameter-node GUI bindings do not guarantee that the planning
        # refresh observer runs after this selection callback on every Slicer
        # version. Refresh Step 4A explicitly so existing segmentations become
        # immediately available to the target-tooth selector.
        self._updatePlanning()
        self._updateTemplateModeling()

    def onSegmentSearchTextChanged(self, filterText: str) -> None:
        if not self._updatingSegmentationReviewUI:
            self._applySegmentFilter(filterText)

    def onSegmentTreeItemChanged(self, item, column: int) -> None:
        if self._updatingSegmentationReviewUI or column != 0:
            return
        segmentId = item.data(0, qt.Qt.UserRole)
        if not segmentId or not self._reviewSegmentationNode or not self.logic:
            return
        self.logic.setSegmentationSegmentVisibility(
            self._reviewSegmentationNode,
            str(segmentId),
            item.checkState(0) == qt.Qt.Checked,
        )

    def onSegmentTreeCurrentItemChanged(self, currentItem, previousItem) -> None:
        del previousItem
        if self._updatingSegmentationReviewUI:
            return
        segmentId = (
            str(currentItem.data(0, qt.Qt.UserRole))
            if currentItem and currentItem.data(0, qt.Qt.UserRole)
            else None
        )
        self.ui.isolateSegmentButton.enabled = bool(segmentId)
        self.ui.editSelectedSegmentButton.enabled = bool(segmentId)
        if not segmentId:
            self._setSelectedSegmentDetailPlaceholders()
            if self._reviewSegmentationNode and self.logic:
                self._applyTargetPriorityHighlight()
            return
        record = self._segmentReviewRecordsById.get(segmentId)
        if record:
            if self._reviewSegmentationNode and self.logic:
                self._applyTargetPriorityHighlight()
            self.ui.segmentationReviewStatusLabel.text = (
                _(
                    "Review selection: %1. The Step 4A target remains the "
                    "priority viewport highlight when one is assigned."
                ).replace("%1", record["displayName"])
            )
            self.ui.segmentationReviewStatusLabel.styleSheet = "color: #1f5f99;"
            self._updateSelectedSegmentDetails(segmentId)

    def onShowAllSegments(self) -> None:
        if self._reviewSegmentationNode and self.logic:
            self.logic.setAllSegmentationSegmentsVisibility(
                self._reviewSegmentationNode,
                True,
            )
            self.logic.setSegmentationSegmentHighlight(
                self._reviewSegmentationNode,
                None,
            )

    def onHideAllSegments(self) -> None:
        if self._reviewSegmentationNode and self.logic:
            self.logic.setSegmentationSegmentHighlight(
                self._reviewSegmentationNode,
                None,
            )
            self.logic.setAllSegmentationSegmentsVisibility(
                self._reviewSegmentationNode,
                False,
            )

    def onIsolateSelectedSegment(self) -> None:
        segmentId = self._selectedReviewSegmentId()
        if segmentId and self._reviewSegmentationNode and self.logic:
            self.logic.setSegmentationSegmentHighlight(
                self._reviewSegmentationNode,
                None,
            )
            self.logic.isolateSegmentationSegment(
                self._reviewSegmentationNode,
                segmentId,
            )

    def onEditSelectedSegment(self) -> None:
        segmentId = self._selectedReviewSegmentId()
        if not segmentId or not self._reviewSegmentationNode or not self.logic:
            slicer.util.errorDisplay(
                _("Select a segmentation label before opening Segment Editor.")
            )
            return

        with slicer.util.tryWithErrorDisplay(
            _("Could not open the selected label in Segment Editor.")
        ):
            segmentEditorModule = getattr(
                slicer.modules,
                "segmenteditor",
                None,
            )
            if not segmentEditorModule:
                raise RuntimeError(
                    _("The built-in Segment Editor module is unavailable.")
                )
            moduleWidget = segmentEditorModule.widgetRepresentation().self()
            if not moduleWidget or not moduleWidget.editor:
                raise RuntimeError(
                    _("The built-in Segment Editor widget is unavailable.")
                )
            handoff = self.logic.beginSegmentationCorrection(
                self._reviewSegmentationNode,
                segmentId,
            )
            self.logic.setSegmentationSegmentHighlight(
                self._reviewSegmentationNode,
                None,
            )
            self.logic.setSegmentationSegmentVisibility(
                self._reviewSegmentationNode,
                segmentId,
                True,
            )
            slicer.util.setSliceViewerLayers(
                background=handoff["sourceVolume"],
                fit=False,
            )
            moduleWidget.editor.setSegmentationNode(
                handoff["segmentationNode"]
            )
            moduleWidget.editor.setSourceVolumeNode(handoff["sourceVolume"])
            moduleWidget.editor.setCurrentSegmentID(handoff["segmentId"])
            moduleWidget.editor.setActiveEffect(None)
            slicer.util.selectModule("SegmentEditor")

    def onSegmentation2DVisibilityToggled(self, visible: bool) -> None:
        if (
            not self._updatingSegmentationReviewUI
            and self._reviewSegmentationNode
            and self.logic
        ):
            self.logic.setSegmentationVisibility2D(
                self._reviewSegmentationNode,
                visible,
            )

