    def onCbctWindowLevelSliderChanged(self, _value: int) -> None:
        if (
            self._updatingSegmentationReviewUI
            or not self._reviewSegmentationNode
            or not self.logic
        ):
            return
        window = float(self._cbctWindowSlider.value) / self._displaySliderScale
        level = float(self._cbctLevelSlider.value) / self._displaySliderScale
        self._cbctWindowSliderValueLabel.text = f"{window:.1f}"
        self._cbctLevelSliderValueLabel.text = f"{level:.1f}"
        with slicer.util.tryWithErrorDisplay(
            _("Could not change the source CBCT window/level display.")
        ):
            sourceVolume = self.logic.getSegmentationSourceVolume(
                self._reviewSegmentationNode
            )
            self.logic.setScalarVolumeWindowLevel(sourceVolume, window, level)
        self._syncSegmentationDisplayControls()

    def _currentSceneDisplayPreset(self) -> dict:
        """Capture a node-independent display parameter set for this MRB."""

        if not self._parameterNode or not self.logic:
            raise ValueError(_("DENTOWorkflow is not ready."))
        segmentationNode = self._reviewSegmentationNode
        segmentationDisplay = (
            segmentationNode.GetDisplayNode() if segmentationNode else None
        )
        baselineDisplay = {}
        if (
            segmentationNode
            and self._workflowViewPriorState
            and self._workflowViewPriorState.get("segmentationNodeId")
            == segmentationNode.GetID()
        ):
            baselineDisplay = self._workflowViewPriorState.get(
                "segmentationDisplay", {}
            )
        if segmentationDisplay:
            segmentation2DVisible = bool(
                baselineDisplay.get(
                    "visibility2D",
                    segmentationDisplay.GetVisibility2D(),
                )
            )
            segmentation3DVisible = bool(
                baselineDisplay.get(
                    "visibility3D",
                    segmentationDisplay.GetVisibility3D(),
                )
            )
            segmentation2DOpacity = float(
                baselineDisplay.get(
                    "opacity2DFill",
                    segmentationDisplay.GetOpacity2DFill(),
                )
            )
            segmentation3DOpacity = float(
                baselineDisplay.get(
                    "opacity3D",
                    segmentationDisplay.GetOpacity3D(),
                )
            )
            renderingMode = self.logic.getSegmentation2DRenderingMode(
                segmentationNode
            )
        else:
            segmentation2DVisible = bool(
                self.ui.segmentation2DCheckBox.checked
            )
            segmentation3DVisible = bool(
                self.ui.segmentation3DCheckBox.checked
            )
            segmentation2DOpacity = float(
                self.ui.segmentation2DOpacitySlider.value
            ) / 100.0
            segmentation3DOpacity = float(
                self.ui.segmentation3DOpacitySlider.value
            ) / 100.0
            renderingMode = (
                self.logic.SEGMENTATION_2D_RENDERING_MODE_SMOOTH
                if int(self.ui.segmentation2DRenderingModeComboBox.currentIndex)
                == 0
                else self.logic.SEGMENTATION_2D_RENDERING_MODE_NATIVE
            )

        sourceVolume = None
        if segmentationNode:
            try:
                sourceVolume = self.logic.getSegmentationSourceVolume(
                    segmentationNode
                )
            except ValueError:
                pass
        volumeDisplay = (
            self.logic.getScalarVolumeDisplaySettings(sourceVolume)
            if sourceVolume
            else {
                "autoWindowLevel": bool(
                    self.ui.cbctAutoWindowLevelCheckBox.checked
                ),
                "window": float(self._cbctWindowSlider.value)
                / self._displaySliderScale,
                "level": float(self._cbctLevelSlider.value)
                / self._displaySliderScale,
                "invertedGrayscale": bool(
                    self.ui.cbctInvertGrayscaleCheckBox.checked
                ),
            }
        )
        return {
            "version": 2,
            "scope": "DENTOWorkflowSceneDisplayParameters",
            "segmentation2DVisible": segmentation2DVisible,
            "segmentation3DVisible": segmentation3DVisible,
            "segmentation2DOpacity": segmentation2DOpacity,
            "segmentation3DOpacity": segmentation3DOpacity,
            "segmentation2DRenderingMode": renderingMode,
            "autoWindowLevel": bool(volumeDisplay["autoWindowLevel"]),
            "window": float(volumeDisplay["window"]),
            "level": float(volumeDisplay["level"]),
            "invertedGrayscale": bool(volumeDisplay["invertedGrayscale"]),
            "interpolate": bool(
                self.logic.getScalarVolumeInterpolation(sourceVolume)
                if sourceVolume
                else self.ui.cbctInterpolationCheckBox.checked
            ),
            "savedUtc": datetime.now(timezone.utc).isoformat(),
        }

    def onSaveSceneDisplayPreset(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode:
            return
        try:
            preset = self._currentSceneDisplayPreset()
            self._parameterNode.sceneDisplayPresetJson = json.dumps(
                preset,
                sort_keys=True,
                separators=(",", ":"),
            )
            self._applySceneDisplayPresetButton.enabled = True
            self._displayPresetStatusLabel.text = _(
                "Node-independent display parameters saved in this MRML scene at %1."
            ).replace("%1", preset["savedUtc"])
            self._displayPresetStatusLabel.styleSheet = "color: #207227;"
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onApplySceneDisplayPreset(self, checked: bool = False) -> None:
        del checked
        if not self._parameterNode or not self.logic:
            return
        try:
            preset = json.loads(self._parameterNode.sceneDisplayPresetJson)
            if not isinstance(preset, dict) or int(preset.get("version", 0)) not in {1, 2}:
                raise ValueError(_("The saved case display preset is invalid."))
            segmentationNode = self._reviewSegmentationNode
            if not segmentationNode:
                self._displayPresetStatusLabel.text = _(
                    "Display parameters are stored in this scene. Select an "
                    "authoritative segmentation to apply them."
                )
                self._displayPresetStatusLabel.styleSheet = "color: #b36b00;"
                return
            sourceVolume = None
            try:
                sourceVolume = self.logic.getSegmentationSourceVolume(
                    segmentationNode
                )
            except ValueError:
                pass

            activeWorkflowPreset = self._workflowViewActivePresetKey
            activeWorkflowKeys = set(self._workflowViewVisibleKeys)
            if self._workflowViewPriorState:
                self._restoreWorkflowViewState(updateUi=False)
            self.logic.setSegmentationVisibility2D(
                segmentationNode,
                bool(preset["segmentation2DVisible"]),
            )
            self.logic.setSegmentationVisibility3D(
                segmentationNode,
                bool(preset["segmentation3DVisible"]),
            )
            self.logic.setSegmentationOpacity2D(
                segmentationNode,
                float(preset["segmentation2DOpacity"]),
            )
            self.logic.setSegmentationOpacity3D(
                segmentationNode,
                float(preset["segmentation3DOpacity"]),
            )
            self.logic.setSegmentation2DRenderingMode(
                segmentationNode,
                str(preset["segmentation2DRenderingMode"]),
            )
            if sourceVolume:
                if bool(preset["autoWindowLevel"]):
                    self.logic.setScalarVolumeAutoWindowLevel(sourceVolume, True)
                else:
                    self.logic.setScalarVolumeWindowLevel(
                        sourceVolume,
                        float(preset["window"]),
                        float(preset["level"]),
                    )
                self.logic.setScalarVolumeInvertedGrayscale(
                    sourceVolume,
                    bool(preset["invertedGrayscale"]),
                )
                self.logic.setScalarVolumeInterpolation(
                    sourceVolume,
                    bool(preset["interpolate"]),
                )
            if activeWorkflowPreset == "custom":
                self._applyWorkflowViewKeys(
                    activeWorkflowKeys,
                    activePresetKey="custom",
                    updateStatus=False,
                )
            elif activeWorkflowPreset:
                self._applyWorkflowViewPreset(
                    activeWorkflowPreset,
                    updateStatus=False,
                )
            self._syncSegmentationDisplayControls()
            self._displayPresetStatusLabel.text = _(
                "Saved scene display parameters applied; source voxels and masks are unchanged."
                if sourceVolume
                else "Segmentation display parameters applied; CBCT grayscale settings "
                "remain stored until a referenced source volume is available."
            )
            self._displayPresetStatusLabel.styleSheet = "color: #207227;"
        except (KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onCbctInvertGrayscaleToggled(self, inverted: bool) -> None:
        if (
            self._updatingSegmentationReviewUI
            or not self._reviewSegmentationNode
            or not self.logic
        ):
            return
        with slicer.util.tryWithErrorDisplay(
            _("Could not change the source CBCT grayscale direction.")
        ):
            sourceVolume = self.logic.getSegmentationSourceVolume(
                self._reviewSegmentationNode
            )
            self.logic.setScalarVolumeInvertedGrayscale(
                sourceVolume,
                inverted,
            )
        self._syncSegmentationDisplayControls()

    def onRestoreLoadedCbctDisplay(self) -> None:
        if not self._reviewSegmentationNode or not self.logic:
            return
        with slicer.util.tryWithErrorDisplay(
            _("Could not restore the loaded source CBCT display settings.")
        ):
            sourceVolume = self.logic.getSegmentationSourceVolume(
                self._reviewSegmentationNode
            )
            baseline = self._loadedVolumeDisplaySettingsByNodeId.get(
                sourceVolume.GetID()
            )
            if not baseline:
                raise ValueError(
                    _("No loaded display baseline is available for this CBCT.")
                )
            self.logic.restoreScalarVolumeDisplaySettings(
                sourceVolume,
                baseline,
            )
        self._syncSegmentationDisplayControls()

    def _setSelectedSegmentDetailPlaceholders(self) -> None:
        for label in (
            self.ui.selectedAnatomyValueLabel,
            self.ui.selectedSourceLabelValueLabel,
            self.ui.selectedFdiValueLabel,
            self.ui.selectedLabelIdValueLabel,
            self.ui.selectedVoxelCountValueLabel,
            self.ui.selectedVolumeValueLabel,
            self.ui.selectedMetricsStatusValueLabel,
        ):
            label.text = _("--")

    def _setSegmentationProvenancePlaceholders(self) -> None:
        for label in (
            self.ui.provenanceRunIdValueLabel,
            self.ui.provenanceSourceVolumeValueLabel,
            self.ui.provenanceBackendValueLabel,
            self.ui.provenanceModelValueLabel,
            self.ui.provenanceDeviceValueLabel,
            self.ui.provenanceTimingValueLabel,
            self.ui.provenanceCompletedValueLabel,
            self.ui.reviewUpdatedValueLabel,
            self.ui.correctionActivityValueLabel,
        ):
            label.text = _("--")
        self.ui.reviewStateComboBox.setCurrentIndex(0)
        self.ui.provenanceWarningLabel.text = ""

    def _refreshSegmentationInspection(self) -> None:
        self._updateSelectedSegmentDetails(self._selectedReviewSegmentId())
        self._updateSegmentationProvenance()

    def _updateSelectedSegmentDetails(self, segmentId: str | None) -> None:
        if not segmentId or not self._reviewSegmentationNode or not self.logic:
            self._setSelectedSegmentDetailPlaceholders()
            return
        try:
            details = self.logic.getSegmentationSegmentDetails(
                self._reviewSegmentationNode,
                segmentId,
            )
        except ValueError:
            self._setSelectedSegmentDetailPlaceholders()
            return

        self.ui.selectedAnatomyValueLabel.text = details["displayName"]
        self.ui.selectedSourceLabelValueLabel.text = details["sourceName"]
        self.ui.selectedFdiValueLabel.text = (
            _("FDI %1").replace("%1", details["fdiNumber"])
            if details["fdiNumber"]
            else _("--")
        )
        self.ui.selectedLabelIdValueLabel.text = (
            str(details["labelId"])
            if details["labelId"] is not None
            else _("--")
        )
        self.ui.selectedVoxelCountValueLabel.text = (
            f"{int(details['voxelCount']):,}"
            if details["voxelCount"] is not None
            else _("--")
        )
        volumeMm3 = details["volumeMm3"]
        self.ui.selectedVolumeValueLabel.text = (
            f"{float(volumeMm3):,.2f} mm\u00b3 "
            f"({float(volumeMm3) / 1000.0:,.3f} cm\u00b3)"
            if volumeMm3 is not None
            else _("--")
        )
        if details["voxelCount"] is None or details["volumeMm3"] is None:
            metricsStatus = _("Inference metrics unavailable")
        elif details["metricsValidity"] == "current":
            metricsStatus = _("Current for imported inference result")
        else:
            metricsStatus = _("Baseline inference values retained for comparison")
        self.ui.selectedMetricsStatusValueLabel.text = metricsStatus

    def _updateSegmentationProvenance(self) -> None:
        if not self._reviewSegmentationNode or not self.logic:
            self._setSegmentationProvenancePlaceholders()
            return
        provenance = self.logic.getSegmentationProvenance(
            self._reviewSegmentationNode
        )
        self._updatingSegmentationReviewUI = True
        try:
            self.ui.provenanceRunIdValueLabel.text = provenance["runId"]
            self.ui.provenanceSourceVolumeValueLabel.text = provenance[
                "sourceVolume"
            ]
            self.ui.provenanceBackendValueLabel.text = provenance["backend"]
            self.ui.provenanceModelValueLabel.text = provenance["model"]
            self.ui.provenanceDeviceValueLabel.text = provenance["device"]
            self.ui.provenanceTimingValueLabel.text = provenance["timing"]
            self.ui.provenanceCompletedValueLabel.text = provenance[
                "completedAtUtc"
            ]
            self.ui.reviewStateComboBox.setCurrentIndex(
                self.logic.REVIEW_STATES.index(provenance["reviewState"])
            )
            self.ui.reviewUpdatedValueLabel.text = provenance[
                "reviewUpdatedUtc"
            ]
            self.ui.correctionActivityValueLabel.text = provenance[
                "correctionActivityUtc"
            ]
            warnings = []
            if self._reviewMetadataWarning:
                warnings.append(self._reviewMetadataWarning)
            if provenance["metricsValidity"] != "current":
                warnings.append(
                    _(
                        "Per-label voxel and volume values describe the "
                        "imported inference result and may not match corrected "
                        "masks."
                    )
                )
            self.ui.provenanceWarningLabel.text = " ".join(warnings)
        finally:
            self._updatingSegmentationReviewUI = False

    def onReviewStateChanged(self, index: int) -> None:
        if (
            self._updatingSegmentationReviewUI
            or not self._reviewSegmentationNode
            or not self.logic
        ):
            return
        if index < 0 or index >= len(self.logic.REVIEW_STATES):
            return
        state = self.logic.REVIEW_STATES[index]
        try:
            self.logic.setSegmentationReviewState(
                self._reviewSegmentationNode,
                state,
            )
            self._updateSegmentationProvenance()
            self.ui.segmentationReviewStatusLabel.text = (
                _("Workflow review state saved as %1.")
                .replace("%1", state)
            )
            self.ui.segmentationReviewStatusLabel.styleSheet = "color: #207227;"
            self._updateTemplateModeling()
        except ValueError as exc:
            slicer.util.errorDisplay(str(exc))

    def _bindPlanningTrajectoryNode(self, trajectoryNode) -> None:
        """Observe the selected trajectory once so measurements stay current."""

        candidateDisplayNode = (
            trajectoryNode.GetDisplayNode() if trajectoryNode else None
        )
        if (
            trajectoryNode is self._planningTrajectoryNode
            and candidateDisplayNode is self._planningTrajectoryDisplayNode
        ):
            return
        if self._planningTrajectoryDisplayNode:
            self.removeObserver(
                self._planningTrajectoryDisplayNode,
                slicer.vtkMRMLMarkupsDisplayNode.JumpToPointEvent,
                self._onPlanningTrajectoryJumpToPoint,
            )
        self._planningTrajectoryDisplayNode = None
        if self._planningTrajectoryNode:
            for trajectoryEvent in (
                vtk.vtkCommand.ModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointPositionDefinedEvent,
                slicer.vtkMRMLMarkupsNode.PointModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointRemovedEvent,
            ):
                self.removeObserver(
                    self._planningTrajectoryNode,
                    trajectoryEvent,
                    self._onPlanningTrajectoryModified,
                )
            self.removeObserver(
                self._planningTrajectoryNode,
                slicer.vtkMRMLMarkupsNode.PointStartInteractionEvent,
                self._onPlanningTrajectoryInteractionStarted,
            )
            self.removeObserver(
                self._planningTrajectoryNode,
                slicer.vtkMRMLMarkupsNode.PointEndInteractionEvent,
                self._onPlanningTrajectoryInteractionEnded,
            )
        self._trajectoryVerificationPointInteractionActive = False
        self._planningTrajectoryNode = trajectoryNode
        if trajectoryNode:
            trajectoryNode.SetSelectable(True)
            trajectoryNode.CreateDefaultDisplayNodes()
            self._planningTrajectoryDisplayNode = trajectoryNode.GetDisplayNode()
            for trajectoryEvent in (
                vtk.vtkCommand.ModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointPositionDefinedEvent,
                slicer.vtkMRMLMarkupsNode.PointModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointRemovedEvent,
            ):
                self.addObserver(
                    trajectoryNode,
                    trajectoryEvent,
                    self._onPlanningTrajectoryModified,
                )
            self.addObserver(
                trajectoryNode,
                slicer.vtkMRMLMarkupsNode.PointStartInteractionEvent,
                self._onPlanningTrajectoryInteractionStarted,
            )
            self.addObserver(
                trajectoryNode,
                slicer.vtkMRMLMarkupsNode.PointEndInteractionEvent,
                self._onPlanningTrajectoryInteractionEnded,
            )
            if self._planningTrajectoryDisplayNode:
                self.addObserver(
                    self._planningTrajectoryDisplayNode,
                    slicer.vtkMRMLMarkupsDisplayNode.JumpToPointEvent,
                    self._onPlanningTrajectoryJumpToPoint,
                )

    def _onPlanningTrajectoryJumpToPoint(self, caller=None, event=None) -> None:
        """Navigate to a clicked Entry/Target even when geometry is locked."""

        del event
        trajectoryNode = self._planningTrajectoryNode
        if not caller or not trajectoryNode:
            return
        try:
            pointIndex = int(caller.GetActiveControlPoint())
        except (AttributeError, TypeError, ValueError):
            pointIndex = -1
        if (
            pointIndex < 0
            or pointIndex >= trajectoryNode.GetNumberOfControlPoints()
            or not trajectoryNode.GetNthControlPointPositionStatus(pointIndex)
            == slicer.vtkMRMLMarkupsNode.PositionDefined
        ):
            return
        pointRas = [0.0, 0.0, 0.0]
        trajectoryNode.GetNthControlPointPositionWorld(pointIndex, pointRas)
        try:
            self._enableCrossViewNavigation()
            crosshairNode = self._workflowCrosshairNode()
            crosshairNode.SetCrosshairRAS(pointRas)
            slicer.modules.markups.logic().JumpSlicesToLocation(
                float(pointRas[0]),
                float(pointRas[1]),
                float(pointRas[2]),
                True,
            )
        except Exception:
            logging.debug(
                "Could not navigate linked views to trajectory control point %d.",
                pointIndex,
            )

    def _bindAssistedTrajectoryEntryNode(self, entryNode) -> None:
        if entryNode is self._assistedTrajectoryEntryNode:
            return
        if self._assistedTrajectoryEntryNode:
            for entryEvent in (
                vtk.vtkCommand.ModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointPositionDefinedEvent,
                slicer.vtkMRMLMarkupsNode.PointModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointRemovedEvent,
            ):
                self.removeObserver(
                    self._assistedTrajectoryEntryNode,
                    entryEvent,
                    self._onAssistedTrajectoryEntryModified,
                )
        self._assistedTrajectoryEntryNode = entryNode
        if entryNode:
            for entryEvent in (
                vtk.vtkCommand.ModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointPositionDefinedEvent,
                slicer.vtkMRMLMarkupsNode.PointModifiedEvent,
                slicer.vtkMRMLMarkupsNode.PointRemovedEvent,
            ):
                self.addObserver(
                    entryNode,
                    entryEvent,
                    self._onAssistedTrajectoryEntryModified,
                )

    def _onAssistedTrajectoryEntryModified(self, caller=None, event=None) -> None:
        del caller, event
        if not self._updatingPlanningUI:
            self._updateAssistedTrajectoryControls()

    def _onPlanningTrajectoryInteractionStarted(self, caller=None, event=None) -> None:
        del event
        if (
            caller
            and self.logic
            and self.logic.isDentobotTrajectoryNode(caller)
            and not self._confirmAndDeleteTrajectoryDependents(
                caller,
                _("edit its Entry/Target points"),
            )
        ):
            self.logic.stopTrajectoryPlacement()
            caller.SetLocked(True)
            self._updatePlanning()
            return
        if self._trajectoryVerificationEnabled:
            self._trajectoryVerificationPointInteractionActive = True

    def _onPlanningTrajectoryInteractionEnded(self, caller=None, event=None) -> None:
        del caller, event
        wasActive = self._trajectoryVerificationPointInteractionActive
        self._trajectoryVerificationPointInteractionActive = False
        if not wasActive or not self._trajectoryVerificationEnabled:
            return
        self._updatePlanning()

    def _onPlanningTrajectoryModified(self, caller=None, event=None) -> None:
        del event
        if (
            self._updatingPlanningUI
            or self._restoringTrajectoryAssociation
            or not self.logic
        ):
            return
        self._updatingPlanningUI = True
        try:
            if self._planningTrajectoryNode:
                self.logic.labelTrajectoryControlPoints(
                    self._planningTrajectoryNode
                )
                self._enforceTrajectoryBounds(
                    self._planningTrajectoryNode
                )
        finally:
            self._updatingPlanningUI = False
        if self._parameterNode and caller:
            try:
                dockingSummary = self.logic.getTargetDockingAssemblySummary(
                    self._parameterNode.targetDockingAssemblyModel
                )
                if caller in dockingSummary["trajectories"]:
                    reason = _("A Step 4A source trajectory changed.")
                    self.logic.markTargetDockingAssemblyStale(
                        self._parameterNode.targetDockingAssemblyModel,
                        reason,
                    )
                    self.logic.markFinalPrintableTemplateStale(
                        self._parameterNode.finalPrintableTemplateModel,
                        reason,
                    )
            except (RuntimeError, ValueError, json.JSONDecodeError):
                pass
        self._updatePlanning()
        self._updateTargetDocking()

    def _setTrajectoryVerificationStatus(
        self,
        message: str,
        *,
        error: bool = False,
        active: bool = False,
    ) -> None:
        if not hasattr(self, "ui"):
            return
        self.ui.trajectoryVerificationStatusLabel.text = message
        self.ui.trajectoryVerificationStatusLabel.styleSheet = (
            "color: #b00020;"
            if error
            else "color: #207227;"
            if active
            else "color: #666666;"
        )

    def _setTrajectoryVerificationEnabledUi(self, enabled: bool) -> None:
        if not hasattr(self, "ui"):
            return
        self._updatingTrajectoryVerificationUI = True
        try:
            self.ui.trajectoryVerificationEnabledCheckBox.checked = bool(enabled)
            self.ui.trajectoryVerificationRotationSlider.enabled = bool(enabled)
            self.ui.resetTrajectoryVerificationButton.enabled = bool(enabled)
        finally:
            self._updatingTrajectoryVerificationUI = False

    def _trajectoryVerificationInputs(self) -> dict:
        if not self._parameterNode or not self.logic:
            raise ValueError(_("DENTO Workflow is not initialized."))
        trajectoryNode = self._parameterNode.trajectoryLine
        summary = self.logic.getTrajectorySummary(trajectoryNode)
        if summary["definedPointCount"] != 2 or not summary["isValid"]:
            raise ValueError(
                _("Define a complete non-zero Entry/Target trajectory first.")
            )
        volumeNode = None
        association = self.logic.getTrajectoryTargetAssociation(trajectoryNode)
        if association:
            try:
                volumeNode = self.logic.getSegmentationSourceVolume(
                    association["segmentationNode"]
                )
            except ValueError as exc:
                raise ValueError(
                    _(
                        "The trajectory's authoritative segmentation has no available "
                        "source CBCT. Restore that referenced volume before verification."
                    )
                ) from exc
        if volumeNode is None:
            volumeNode = self._parameterNode.inputVolume
        if (
            not volumeNode
            or not volumeNode.IsA("vtkMRMLScalarVolumeNode")
            or not volumeNode.GetImageData()
        ):
            raise ValueError(_("Select or restore the trajectory's source CBCT first."))
        layoutManager = slicer.app.layoutManager() if slicer.app else None
        if not layoutManager:
            raise RuntimeError(_("Slicer's layout manager is unavailable."))
        viewNames = [str(name) for name in layoutManager.sliceViewNames()]
        if not viewNames:
            raise RuntimeError(
                _("No 2D slice view is available. Exit the Step 5C isolated 3D view first.")
            )
        sliceViewName = "Red" if "Red" in viewNames else viewNames[0]
        sliceWidget = layoutManager.sliceWidget(sliceViewName)
        if not sliceWidget:
            raise RuntimeError(_("Slicer could not access the verification slice view."))
        sliceNode = sliceWidget.mrmlSliceNode()
        compositeNode = sliceWidget.mrmlSliceCompositeNode()
        if not sliceNode or not compositeNode:
            raise RuntimeError(_("The verification slice MRML nodes are unavailable."))
        return {
            "volumeNode": volumeNode,
            "trajectoryNode": trajectoryNode,
            "summary": summary,
            "sliceViewName": sliceViewName,
            "sliceWidget": sliceWidget,
            "sliceNode": sliceNode,
            "compositeNode": compositeNode,
        }

    @staticmethod
    def _captureSliceToRasElements(sliceNode) -> tuple[float, ...]:
        matrix = sliceNode.GetSliceToRAS()
        return tuple(
            float(matrix.GetElement(row, column))
            for row in range(4)
            for column in range(4)
        )

    @staticmethod
    def _matrixFromElements(elements: tuple[float, ...]) -> vtk.vtkMatrix4x4:
        if len(elements) != 16:
            raise ValueError(_("A saved slice matrix must contain 16 elements."))
        matrix = vtk.vtkMatrix4x4()
        for row in range(4):
            for column in range(4):
                matrix.SetElement(row, column, float(elements[4 * row + column]))
        return matrix

    @staticmethod
    def _sliceMatricesDiffer(first, second, tolerance: float = 1e-8) -> bool:
        return any(
            abs(float(first.GetElement(row, column)) - float(second.GetElement(row, column)))
            > tolerance
            for row in range(4)
            for column in range(4)
        )

    def _captureTrajectoryVerificationSliceState(self, inputs: dict) -> dict:
        sliceNode = inputs["sliceNode"]
        compositeNode = inputs["compositeNode"]
        volumeNode = inputs["volumeNode"]
        volumeNode.CreateDefaultDisplayNodes()
        volumeDisplayNode = volumeNode.GetDisplayNode()
        return {
            "sliceViewName": inputs["sliceViewName"],
            "sliceNodeId": sliceNode.GetID(),
            "compositeNodeId": compositeNode.GetID(),
            "sliceToRas": self._captureSliceToRasElements(sliceNode),
            "fieldOfView": tuple(float(value) for value in sliceNode.GetFieldOfView()),
            "backgroundVolumeId": compositeNode.GetBackgroundVolumeID(),
            "foregroundVolumeId": compositeNode.GetForegroundVolumeID(),
            "labelVolumeId": compositeNode.GetLabelVolumeID(),
            "foregroundOpacity": float(compositeNode.GetForegroundOpacity()),
            "labelOpacity": float(compositeNode.GetLabelOpacity()),
            "linkedControl": bool(compositeNode.GetLinkedControl()),
            "hotLinkedControl": bool(compositeNode.GetHotLinkedControl()),
            "volumeDisplayNodeId": (
                volumeDisplayNode.GetID() if volumeDisplayNode else None
            ),
            "volumeInterpolate": (
                bool(volumeDisplayNode.GetInterpolate())
                if volumeDisplayNode and hasattr(volumeDisplayNode, "GetInterpolate")
                else None
            ),
        }

    def _captureTrajectoryVerificationDisplayState(self, trajectoryNode) -> None:
        self._restoreTrajectoryVerificationDisplayState()
        displayNode = trajectoryNode.GetDisplayNode() if trajectoryNode else None
        if trajectoryNode and not displayNode:
            trajectoryNode.CreateDefaultDisplayNodes()
            displayNode = trajectoryNode.GetDisplayNode()
        if not displayNode:
            raise RuntimeError(_("Slicer could not create the trajectory overlay display."))
        self._trajectoryVerificationPriorDisplayState = {
            "trajectoryNodeId": trajectoryNode.GetID(),
            "visibility": bool(displayNode.GetVisibility()),
            "visibility2D": bool(displayNode.GetVisibility2D()),
            "sliceProjection": bool(displayNode.GetSliceProjection()),
            "sliceProjectionUseFiducialColor": bool(
                displayNode.GetSliceProjectionUseFiducialColor()
            ),
            "sliceProjectionOpacity": float(displayNode.GetSliceProjectionOpacity()),
        }
        displayNode.SetVisibility(True)
        displayNode.SetVisibility2D(True)
        displayNode.SetSliceProjection(True)
        displayNode.SetSliceProjectionUseFiducialColor(True)
        displayNode.SetSliceProjectionOpacity(1.0)

    def _restoreTrajectoryVerificationDisplayState(self) -> None:
        state = self._trajectoryVerificationPriorDisplayState
        self._trajectoryVerificationPriorDisplayState = None
        if not state:
            return
        trajectoryNode = slicer.mrmlScene.GetNodeByID(state["trajectoryNodeId"])
        displayNode = trajectoryNode.GetDisplayNode() if trajectoryNode else None
        if not displayNode:
            return
        displayNode.SetVisibility(state["visibility"])
        displayNode.SetVisibility2D(state["visibility2D"])
        displayNode.SetSliceProjection(state["sliceProjection"])
        displayNode.SetSliceProjectionUseFiducialColor(
            state["sliceProjectionUseFiducialColor"]
        )
        displayNode.SetSliceProjectionOpacity(state["sliceProjectionOpacity"])

    def _trajectoryVerificationFieldOfView(
        self,
        inputs: dict,
        sliceMatrix,
    ) -> tuple[float, float]:
        """Fit the target bounds and trajectory with a small margin."""

        summary = inputs["summary"]
        midpoint = np.asarray(
            [sliceMatrix.GetElement(row, 3) for row in range(3)],
            dtype=float,
        )
        xAxis = np.asarray(
            [sliceMatrix.GetElement(row, 0) for row in range(3)],
            dtype=float,
        )
        yAxis = np.asarray(
            [sliceMatrix.GetElement(row, 1) for row in range(3)],
            dtype=float,
        )
        projectedX = []
        projectedY = []
        roiNode = self._parameterNode.targetToothBoundsRoi if self._parameterNode else None
        if roiNode and roiNode.IsA("vtkMRMLMarkupsROINode"):
            bounds = [0.0] * 6
            roiNode.GetRASBounds(bounds)
            if all(math.isfinite(value) for value in bounds):
                for rValue in (bounds[0], bounds[1]):
                    for aValue in (bounds[2], bounds[3]):
                        for sValue in (bounds[4], bounds[5]):
                            relative = np.asarray((rValue, aValue, sValue)) - midpoint
                            projectedX.append(float(np.dot(relative, xAxis)))
                            projectedY.append(float(np.dot(relative, yAxis)))
        for point in (summary["entryRas"], summary["targetRas"]):
            relative = np.asarray(point, dtype=float) - midpoint
            projectedX.append(float(np.dot(relative, xAxis)))
            projectedY.append(float(np.dot(relative, yAxis)))

        projectedWidth = max(projectedX) - min(projectedX)
        projectedHeight = max(projectedY) - min(projectedY)
        if roiNode and roiNode.IsA("vtkMRMLMarkupsROINode"):
            roiSize = [0.0, 0.0, 0.0]
            roiNode.GetSizeWorld(roiSize)
            rotationInvariantExtent = float(np.linalg.norm(roiSize))
        else:
            rotationInvariantExtent = 0.0
        contentWidth = max(projectedWidth, rotationInvariantExtent, 5.0) * 1.25
        contentHeight = max(
            projectedHeight,
            rotationInvariantExtent,
            float(summary["lengthMm"]),
            5.0,
        ) * 1.25
        dimensions = inputs["sliceNode"].GetDimensions()
        aspect = (
            float(dimensions[0]) / float(dimensions[1])
            if dimensions[0] > 0 and dimensions[1] > 0
            else 1.0
        )
        height = max(contentHeight, contentWidth / max(aspect, 1e-6))
        return height * aspect, height

    def _applyTrajectoryVerificationView(
        self,
        *,
        fit: bool,
        deterministicOrientation: bool = False,
    ) -> None:
        if not self._trajectoryVerificationEnabled:
            return
        inputs = self._trajectoryVerificationInputs()
        priorState = self._trajectoryVerificationPriorSliceState
        if (
            not priorState
            or inputs["sliceNode"].GetID() != priorState["sliceNodeId"]
            or inputs["compositeNode"].GetID() != priorState["compositeNodeId"]
        ):
            raise RuntimeError(
                _("The verification slice view changed. Disable and enable verification again.")
            )

        displayState = self._trajectoryVerificationPriorDisplayState
        if (
            not displayState
            or displayState["trajectoryNodeId"] != inputs["trajectoryNode"].GetID()
        ):
            self._captureTrajectoryVerificationDisplayState(inputs["trajectoryNode"])

        compositeNode = inputs["compositeNode"]
        if compositeNode.GetLinkedControl():
            compositeNode.SetLinkedControl(False)
        if compositeNode.GetHotLinkedControl():
            compositeNode.SetHotLinkedControl(False)
        sliceNode = inputs["sliceNode"]
        trajectoryNodeId = inputs["trajectoryNode"].GetID()
        continuousOrientationAvailable = bool(
            not deterministicOrientation
            and trajectoryNodeId == self._trajectoryVerificationAppliedTrajectoryNodeId
            and self._trajectoryVerificationLastAppliedAngleDeg is not None
        )
        if continuousOrientationAvailable:
            angleDeltaDeg = (
                self._trajectoryVerificationAngleDeg
                - self._trajectoryVerificationLastAppliedAngleDeg
            )
            matrix = self.logic.transportTrajectorySliceMatrix(
                sliceNode.GetSliceToRAS(),
                inputs["summary"]["entryRas"],
                inputs["summary"]["targetRas"],
                angleDeltaDeg,
            )
        else:
            matrix = self.logic.computeTrajectorySliceMatrix(
                inputs["summary"]["entryRas"],
                inputs["summary"]["targetRas"],
                self._trajectoryVerificationAngleDeg,
            )
        if self._sliceMatricesDiffer(sliceNode.GetSliceToRAS(), matrix):
            sliceNode.GetSliceToRAS().DeepCopy(matrix)
            sliceNode.UpdateMatrices()
        self._trajectoryVerificationAppliedTrajectoryNodeId = trajectoryNodeId
        self._trajectoryVerificationLastAppliedAngleDeg = (
            self._trajectoryVerificationAngleDeg
        )
        if fit:
            width, height = self._trajectoryVerificationFieldOfView(inputs, matrix)
            currentFieldOfView = sliceNode.GetFieldOfView()
            sliceNode.SetFieldOfView(width, height, currentFieldOfView[2])
            sliceNode.UpdateMatrices()

        if compositeNode.GetBackgroundVolumeID() != inputs["volumeNode"].GetID():
            compositeNode.SetBackgroundVolumeID(inputs["volumeNode"].GetID())
        volumeDisplayNode = inputs["volumeNode"].GetDisplayNode()
        if volumeDisplayNode and hasattr(volumeDisplayNode, "SetInterpolate"):
            volumeDisplayNode.SetInterpolate(
                bool(self.ui.trajectoryVerificationSmoothInterpolationCheckBox.checked)
            )

        self._setTrajectoryVerificationStatus(
            _(
                "%1 view: longitudinal Entry→Target plane at %2°. "
                "Point drags stay in this plane; use Rotation to inspect circumference."
            )
            .replace("%1", inputs["sliceViewName"])
            .replace("%2", f"{self._trajectoryVerificationAngleDeg:.0f}"),
            active=True,
        )

    def _applyPendingTrajectoryVerificationUpdate(self) -> None:
        self._trajectoryVerificationUpdatePending = False
        if (
            not self._trajectoryVerificationEnabled
            or self._trajectoryVerificationPointInteractionActive
        ):
            return
        try:
            self._applyTrajectoryVerificationView(fit=False)
        except (RuntimeError, ValueError) as exc:
            self._restoreTrajectoryVerificationViewState(updateUi=True)
            self._setTrajectoryVerificationStatus(str(exc), error=True)

    def _scheduleTrajectoryVerificationUpdate(self) -> None:
        if (
            not self._trajectoryVerificationEnabled
            or self._trajectoryVerificationPointInteractionActive
            or self._trajectoryVerificationUpdatePending
        ):
            return
        self._trajectoryVerificationUpdatePending = True
        # Collapse rapid slider/wheel events to roughly one display refresh per
        # 60 Hz frame. Slicer's native reslice pipeline still performs the only
        # image operation; no volume is generated or copied.
        qt.QTimer.singleShot(16, self._applyPendingTrajectoryVerificationUpdate)

    def _enableTrajectoryVerificationView(self) -> None:
        if self._templateFinalizationViewIsolated():
            self._restoreTemplateFinalizationViewState(updateUi=True)
        inputs = self._trajectoryVerificationInputs()
        if self._trajectoryVerificationPriorSliceState:
            self._restoreTrajectoryVerificationViewState(updateUi=False)
            inputs = self._trajectoryVerificationInputs()
        self._trajectoryVerificationPriorSliceState = (
            self._captureTrajectoryVerificationSliceState(inputs)
        )
        self._trajectoryVerificationEnabled = True
        self._trajectoryVerificationPointInteractionActive = False
        self._trajectoryVerificationAppliedTrajectoryNodeId = None
        self._trajectoryVerificationLastAppliedAngleDeg = None
        self._captureTrajectoryVerificationDisplayState(inputs["trajectoryNode"])
        try:
            self._applyTrajectoryVerificationView(
                fit=True,
                deterministicOrientation=True,
            )
        except Exception:
            self._restoreTrajectoryVerificationViewState(updateUi=False)
            raise
        self._setTrajectoryVerificationEnabledUi(True)

    def _restoreTrajectoryVerificationViewState(self, *, updateUi: bool) -> None:
        state = self._trajectoryVerificationPriorSliceState
        self._trajectoryVerificationPriorSliceState = None
        self._trajectoryVerificationEnabled = False
        self._trajectoryVerificationUpdatePending = False
        self._trajectoryVerificationPointInteractionActive = False
        self._trajectoryVerificationAppliedTrajectoryNodeId = None
        self._trajectoryVerificationLastAppliedAngleDeg = None
        self._restoreTrajectoryVerificationDisplayState()
        if state:
            sliceNode = slicer.mrmlScene.GetNodeByID(state["sliceNodeId"])
            compositeNode = slicer.mrmlScene.GetNodeByID(state["compositeNodeId"])
            if sliceNode and sliceNode.IsA("vtkMRMLSliceNode"):
                matrix = self._matrixFromElements(state["sliceToRas"])
                sliceNode.GetSliceToRAS().DeepCopy(matrix)
                sliceNode.UpdateMatrices()
                sliceNode.SetFieldOfView(*state["fieldOfView"])
            if compositeNode and compositeNode.IsA("vtkMRMLSliceCompositeNode"):
                compositeNode.SetLinkedControl(False)
                compositeNode.SetHotLinkedControl(False)
                compositeNode.SetBackgroundVolumeID(state["backgroundVolumeId"])
                compositeNode.SetForegroundVolumeID(state["foregroundVolumeId"])
                compositeNode.SetLabelVolumeID(state["labelVolumeId"])
                compositeNode.SetForegroundOpacity(state["foregroundOpacity"])
                compositeNode.SetLabelOpacity(state["labelOpacity"])
                compositeNode.SetHotLinkedControl(state["hotLinkedControl"])
                compositeNode.SetLinkedControl(state["linkedControl"])
            volumeDisplayNode = (
                slicer.mrmlScene.GetNodeByID(state.get("volumeDisplayNodeId"))
                if state.get("volumeDisplayNodeId")
                else None
            )
            if (
                volumeDisplayNode
                and state.get("volumeInterpolate") is not None
                and hasattr(volumeDisplayNode, "SetInterpolate")
            ):
                volumeDisplayNode.SetInterpolate(bool(state["volumeInterpolate"]))
        if updateUi:
            self._setTrajectoryVerificationEnabledUi(False)

    def onTrajectoryVerificationToggled(self, enabled: bool) -> None:
        if self._updatingTrajectoryVerificationUI:
            return
        if not enabled:
            self._restoreTrajectoryVerificationViewState(updateUi=True)
            self._updateTrajectoryVerificationControls()
            return
        try:
            self._enableTrajectoryVerificationView()
            self._updateTrajectoryVerificationControls()
        except (RuntimeError, ValueError) as exc:
            self._restoreTrajectoryVerificationViewState(updateUi=True)
            self._setTrajectoryVerificationStatus(str(exc), error=True)

    def onTrajectoryVerificationRotationChanged(self, angleDeg: int) -> None:
        if self._updatingTrajectoryVerificationUI:
            return
        self._trajectoryVerificationAngleDeg = float(angleDeg)
        self.ui.trajectoryVerificationRotationValueLabel.text = f"{int(angleDeg)}°"
        if self._parameterNode:
            self._presentSelectedTrajectory(
                self._parameterNode.trajectoryLine,
                centerSlices=True,
            )
        self._scheduleTrajectoryVerificationUpdate()

    def onTrajectoryVerificationSmoothingToggled(self, checked: bool) -> None:
        del checked
        if self._updatingTrajectoryVerificationUI:
            return
        if not self._trajectoryVerificationEnabled:
            return
        try:
            inputs = self._trajectoryVerificationInputs()
            displayNode = inputs["volumeNode"].GetDisplayNode()
            if displayNode and hasattr(displayNode, "SetInterpolate"):
                displayNode.SetInterpolate(
                    bool(
                        self.ui.trajectoryVerificationSmoothInterpolationCheckBox.checked
                    )
                )
        except (RuntimeError, ValueError) as exc:
            self._setTrajectoryVerificationStatus(str(exc), error=True)

    def onResetTrajectoryVerification(self) -> None:
        self._trajectoryVerificationAngleDeg = 0.0
        self._updatingTrajectoryVerificationUI = True
        try:
            self.ui.trajectoryVerificationRotationSlider.value = 0
            self.ui.trajectoryVerificationRotationValueLabel.text = _("0°")
        finally:
            self._updatingTrajectoryVerificationUI = False
        if self._trajectoryVerificationEnabled:
            try:
                self._applyTrajectoryVerificationView(
                    fit=True,
                    deterministicOrientation=True,
                )
            except (RuntimeError, ValueError) as exc:
                self._restoreTrajectoryVerificationViewState(updateUi=True)
                self._setTrajectoryVerificationStatus(str(exc), error=True)

    def _updateTrajectoryVerificationControls(self) -> None:
        if not hasattr(self, "ui"):
            return
        canEnable = False
        reason = _("Complete Entry and Target and select a CBCT to enable verification.")
        if self._parameterNode and self.logic:
            try:
                inputs = self._trajectoryVerificationInputs()
                canEnable = True
                reason = _("Ready to align the %1 slice view through Entry and Target.").replace(
                    "%1", inputs["sliceViewName"]
                )
            except (RuntimeError, ValueError) as exc:
                reason = str(exc)
        if self._trajectoryVerificationEnabled and not canEnable:
            self._restoreTrajectoryVerificationViewState(updateUi=True)

        self._updatingTrajectoryVerificationUI = True
        try:
            self.ui.trajectoryVerificationEnabledCheckBox.enabled = bool(
                canEnable or self._trajectoryVerificationEnabled
            )
            self.ui.trajectoryVerificationEnabledCheckBox.checked = bool(
                self._trajectoryVerificationEnabled
            )
            self.ui.trajectoryVerificationRotationSlider.enabled = bool(
                self._trajectoryVerificationEnabled
            )
            self.ui.resetTrajectoryVerificationButton.enabled = bool(
                self._trajectoryVerificationEnabled
            )
            self.ui.trajectoryVerificationRotationSlider.value = int(
                round(self._trajectoryVerificationAngleDeg)
            )
            self.ui.trajectoryVerificationRotationValueLabel.text = (
                f"{self._trajectoryVerificationAngleDeg:.0f}°"
            )
        finally:
            self._updatingTrajectoryVerificationUI = False
        if self._trajectoryVerificationEnabled:
            self._scheduleTrajectoryVerificationUpdate()
        else:
            self._setTrajectoryVerificationStatus(reason)

    def _ensureTargetBounds(
        self,
        segmentationNode,
        targetRecord: dict,
    ) -> tuple[float, ...] | None:
        """Create/update the visible active-tooth AABB and persist its node."""

        if not self._parameterNode or not self.logic:
            return None
        previousRoi = self._parameterNode.targetToothBoundsRoi
        candidateRoi = previousRoi
        if not self.logic.isTargetBoundsRoiForTarget(
            candidateRoi,
            segmentationNode,
            targetRecord["segmentId"],
        ):
            candidateRoi = self.logic.findTargetBoundsRoi(
                segmentationNode,
                targetRecord["segmentId"],
            )
        try:
            roiNode, bounds = self.logic.createOrUpdateTargetBoundsRoi(
                segmentationNode,
                targetRecord["segmentId"],
                candidateRoi,
            )
        except (RuntimeError, ValueError) as exc:
            self._planningConstraintWarning = str(exc)
            self.ui.targetBoundsValueLabel.text = _("--")
            return None

        if (
            previousRoi
            and previousRoi is not roiNode
            and previousRoi.GetDisplayNode()
        ):
            previousRoi.GetDisplayNode().SetVisibility(False)
        if self._parameterNode.targetToothBoundsRoi is not roiNode:
            self._parameterNode.targetToothBoundsRoi = roiNode
        self.ui.targetBoundsValueLabel.text = (
            self.logic.formatRasBounds(bounds)
        )
        trajectoryNode = self._parameterNode.trajectoryLine
        if trajectoryNode:
            if trajectoryNode.GetNodeReference(
                self.logic.TARGET_BOUNDS_ROI_REFERENCE_ROLE
            ) is not roiNode:
                trajectoryNode.SetNodeReferenceID(
                    self.logic.TARGET_BOUNDS_ROI_REFERENCE_ROLE,
                    roiNode.GetID(),
                )
        return bounds

    def _enforceTrajectoryBounds(self, trajectoryNode) -> bool:
        """Reject or restore any trajectory point outside the target-tooth AABB."""

        if (
            not trajectoryNode
            or not self._parameterNode
            or not self.logic
            or not self._parameterNode.teethSegmentation
            or not self._parameterNode.targetToothSegmentId
        ):
            return True
        try:
            report = self.logic.getTrajectoryBoundsReport(
                trajectoryNode,
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
            )
        except ValueError as exc:
            self._planningConstraintWarning = str(exc)
            return False

        invalidIndices = report["invalidPointIndices"]
        if not invalidIndices:
            summary = report["summary"]
            currentPoints = [
                list(point)
                for point in (
                    summary["entryRas"],
                    summary["targetRas"],
                )
                if point is not None
            ]
            previousPoints = self._validTrajectoryPointsByNodeId.get(
                trajectoryNode.GetID(),
                [],
            )
            if (
                not self._planningConstraintWarning
                or currentPoints != previousPoints
            ):
                self._planningConstraintWarning = ""
            self._validTrajectoryPointsByNodeId[
                trajectoryNode.GetID()
            ] = currentPoints
            return True

        previousPoints = self._validTrajectoryPointsByNodeId.get(
            trajectoryNode.GetID(),
            [],
        )
        bounds = report["bounds"]
        wasModifying = trajectoryNode.StartModify()
        try:
            for pointIndex in sorted(invalidIndices, reverse=True):
                previousPoint = (
                    previousPoints[pointIndex]
                    if pointIndex < len(previousPoints)
                    else None
                )
                if (
                    previousPoint is not None
                    and self.logic.isRasPointWithinBounds(
                        previousPoint,
                        bounds,
                    )
                ):
                    trajectoryNode.SetNthControlPointPositionWorld(
                        pointIndex,
                        previousPoint,
                    )
                else:
                    trajectoryNode.RemoveNthControlPoint(pointIndex)
        finally:
            trajectoryNode.EndModify(wasModifying)

        rejectedNames = ", ".join(
            ("Entry", "Target")[index] for index in invalidIndices
        )
        self._planningConstraintWarning = (
            _(
                "%1 was outside the selected tooth bounds and was rejected. "
                "Place both points inside the orange target box."
            ).replace("%1", rejectedNames)
        )
        return False

    def _applyTargetPriorityHighlight(self) -> None:
        """Keep the Step 4A target dominant over Step 3 review selection."""

        if self._templateSupportBoundaryFocusState:
            return
        if (
            not self._parameterNode
            or not self.logic
            or not self._parameterNode.teethSegmentation
        ):
            return
        segmentationNode = self._parameterNode.teethSegmentation
        targetId = self._parameterNode.targetToothSegmentId
        if targetId in self._targetToothRecordsById:
            self.logic.setSegmentationVisibility2D(segmentationNode, True)
            self.logic.setSegmentationVisibility3D(segmentationNode, True)
            self.logic.setSegmentationSegmentVisibility(
                segmentationNode,
                targetId,
                True,
            )
            self.logic.setSegmentationSegmentHighlight(
                segmentationNode,
                targetId,
            )
            treeWidget = self.ui.segmentTreeWidget
            targetItem = None
            for groupIndex in range(treeWidget.topLevelItemCount):
                groupItem = treeWidget.topLevelItem(groupIndex)
                for childIndex in range(groupItem.childCount()):
                    item = groupItem.child(childIndex)
                    if str(item.data(0, qt.Qt.UserRole)) == targetId:
                        targetItem = item
                        break
                if targetItem:
                    break
            if targetItem and treeWidget.currentItem() is not targetItem:
                self._updatingSegmentationReviewUI = True
                try:
                    treeWidget.setCurrentItem(targetItem)
                finally:
                    self._updatingSegmentationReviewUI = False
                self._updateSelectedSegmentDetails(targetId)
        else:
            selectedId = self._selectedReviewSegmentId()
            self.logic.setSegmentationSegmentHighlight(
                segmentationNode,
                selectedId,
            )

    @staticmethod
    def _nodeSelectorComboBox(selector):
        """Return the PythonQt-accessible combo embedded in a node selector."""

        return next(
            (
                child
                for child in selector.children()
                if hasattr(child, "setItemData")
                and hasattr(child, "count")
            ),
            None,
        )

    def _updateNodeSelectorLineageSwatches(
        self,
        selector,
        acceptsNode,
    ) -> None:
        """Show persisted lineage colors beside owned nodes in a selector."""

        if not selector or not self.logic:
            return
        comboBox = self._nodeSelectorComboBox(selector)
        if comboBox is None:
            return
        for index in range(comboBox.count):
            node = selector.nodeFromIndex(index)
            if not acceptsNode(node):
                continue
            color = self.logic.lineageColorFromNode(node)
            if not color:
                comboBox.setItemData(
                    index,
                    qt.QColor(),
                    qt.Qt.DecorationRole,
                )
                continue
            qColor = qt.QColor(
                *(int(round(component * 255.0)) for component in color)
            )
            comboBox.setItemData(index, qColor, qt.Qt.DecorationRole)

    def _updateTrajectorySelectorColorSwatches(self) -> None:
        """Decorate every persisted trajectory group in the shared selector."""

        if not hasattr(self, "ui") or not self.logic:
            return
        self._updateNodeSelectorLineageSwatches(
            self.ui.trajectorySelector,
            self.logic.isDentobotTrajectoryNode,
        )

    @staticmethod
    def _lineageStyleSheet(
        color: tuple[float, float, float] | None,
        *,
        borderWidth: int = 8,
    ) -> str:
        """Return a readable Qt style using a lineage color as the anchor."""

        if not color:
            return (
                "QLabel { color: #555555; background-color: #eeeeee; "
                f"border-left: {borderWidth}px solid #999999; "
                "border-radius: 3px; padding: 5px 8px; }"
            )
        rgb = tuple(
            int(round(max(0.0, min(1.0, component)) * 255.0))
            for component in color
        )
        background = tuple(
            int(round(255 - (255 - component) * 0.18))
            for component in rgb
        )
        return (
            "QLabel { color: #151515; "
            f"background-color: rgb{background}; "
            f"border-left: {borderWidth}px solid rgb{rgb}; "
            "border-radius: 3px; padding: 5px 8px; font-weight: 600; }"
        )

    def _lineageSourceNode(self, nodes, targetSegmentId: str = ""):
        """Choose the first colored node matching the requested target."""

        if not self.logic:
            return None
        for node in nodes:
            if not node or not self.logic.lineageColorFromNode(node):
                continue
            if (
                targetSegmentId
                and node.GetAttribute(
                    self.logic.LINEAGE_TARGET_SEGMENT_ATTRIBUTE
                )
                != targetSegmentId
            ):
                continue
            return node
        if targetSegmentId:
            for className in (
                "vtkMRMLMarkupsLineNode",
                "vtkMRMLModelNode",
                "vtkMRMLMarkupsROINode",
            ):
                for node in slicer.util.getNodesByClass(className):
                    if (
                        node.GetAttribute(
                            self.logic.LINEAGE_TARGET_SEGMENT_ATTRIBUTE
                        )
                        == targetSegmentId
                        and self.logic.lineageColorFromNode(node)
                    ):
                        return node
        return None

    def _updateLineageBadge(
        self,
        label,
        node,
        linkedSteps: str,
        emptyText: str,
    ) -> None:
        """Render an explicit target-lineage badge in a downstream step."""

        color = self.logic.lineageColorFromNode(node) if node else None
        label.styleSheet = self._lineageStyleSheet(color)
        if not color:
            label.text = emptyText
            return
        fdiNumber = node.GetAttribute(
            self.logic.LINEAGE_TARGET_FDI_ATTRIBUTE
        ) or ""
        segmentId = node.GetAttribute(
            self.logic.LINEAGE_TARGET_SEGMENT_ATTRIBUTE
        ) or ""
        targetName = (
            _("FDI %1").replace("%1", fdiNumber)
            if fdiNumber
            else segmentId
            if segmentId
            else _("target tooth")
        )
        rgb255 = tuple(int(round(component * 255.0)) for component in color)
        colorHex = "#{:02X}{:02X}{:02X}".format(*rgb255)
        label.text = (
            _("%1 lineage: %2  •  %3  •  %4")
            .replace("%1", linkedSteps)
            .replace("%2", targetName)
            .replace("%3", colorHex)
            .replace("%4", _("same parent/child group"))
        )

    def _clearPlanning(self) -> None:
        if not hasattr(self, "ui"):
            return
        if self._trajectoryVerificationEnabled:
            self._restoreTrajectoryVerificationViewState(updateUi=False)
        self._updatingPlanningUI = True
        try:
            self._targetToothRecordsById = {}
            self.ui.targetToothComboBox.clear()
            self.ui.targetToothComboBox.addItem(_("Select target tooth..."), "")
            self.ui.targetToothComboBox.enabled = False
            self.ui.targetToothValueLabel.text = _("--")
            self.ui.targetToothSourceValueLabel.text = _("--")
            self.ui.createTrajectoryButton.enabled = False
            self.ui.placeTrajectoryButton.enabled = False
            self.ui.placeTrajectoryButton.text = _("Place Both Points")
            self.ui.undoTrajectoryPointButton.enabled = False
            self.ui.resetTrajectoryButton.enabled = False
            self.ui.deleteTrajectoryButton.enabled = False
            self.ui.lockTrajectoryButton.enabled = False
            self.ui.lockTrajectoryButton.checked = False
            self.ui.trajectoryLockStatusLabel.text = _(
                "NO TRAJECTORY SELECTED"
            )
            self.ui.trajectoryLockStatusLabel.styleSheet = (
                "color: #666666; font-weight: 600;"
            )
            self.ui.focusPlanningTargetButton.enabled = False
            self.ui.framePlanningTargetButton.enabled = False
            self.ui.restorePlanningViewButton.enabled = False
            self.ui.trajectoryEntryValueLabel.text = _("--")
            self.ui.trajectoryTargetValueLabel.text = _("--")
            self.ui.trajectoryLengthValueLabel.text = _("--")
            self.ui.targetBoundsValueLabel.text = _("--")
            self._planningConstraintWarning = ""
            self.ui.planningStatusLabel.text = _(
                "Select a dental segmentation before defining a target tooth."
            )
            self.ui.planningStatusLabel.styleSheet = "color: #b36b00;"
        finally:
            self._updatingPlanningUI = False
        self._updateTrajectoryPlacementModeControls()
        self._updateTrajectoryVerificationControls()
        self._updateAssistedTrajectoryControls()

    def _updateAssistedTrajectoryControls(self) -> None:
        if not hasattr(self, "ui") or not self._parameterNode or not self.logic:
            return
        segmentationNode = self._parameterNode.teethSegmentation
        segmentId = self._parameterNode.targetToothSegmentId
        targetRecord = self._targetToothRecordsById.get(segmentId)
        requestedCount = int(self._parameterNode.assistedTrajectoryCount)
        if requestedCount not in (1, 2):
            requestedCount = 2
            self._parameterNode.assistedTrajectoryCount = requestedCount

        entryNode = self._parameterNode.assistedTrajectoryEntries
        summary = None
        associationError = ""
        if entryNode and targetRecord:
            try:
                summary = self.logic.validateAssistedTrajectoryEntryAssociation(
                    entryNode,
                    segmentationNode,
                    segmentId,
                    requestedCount,
                )
            except ValueError as exc:
                associationError = str(exc)

        existingCount = (
            len(self.logic.dentobotTrajectoriesForTarget(segmentationNode, segmentId))
            if segmentationNode and targetRecord
            else 0
        )
        reviewed = bool(
            segmentationNode
            and self.logic.getSegmentationReviewState(segmentationNode) == "Reviewed"
        )
        self._updatingPlanningUI = True
        try:
            comboIndex = self.ui.assistedTrajectoryCountComboBox.findData(
                requestedCount
            )
            if comboIndex >= 0:
                self.ui.assistedTrajectoryCountComboBox.setCurrentIndex(comboIndex)
            canPrepare = bool(targetRecord and reviewed and existingCount == 0)
            self.ui.assistedTrajectoryCountComboBox.enabled = canPrepare
            self.ui.placeAssistedTrajectoryEntriesButton.enabled = canPrepare
            self.ui.generateAssistedTrajectoriesButton.enabled = bool(
                canPrepare and summary and summary["isComplete"]
            )
            self.ui.restoreAssistedTrajectoryFocusButton.enabled = bool(
                self._assistedTrajectoryFocusState
            )
            self.ui.restorePlanningViewButton.enabled = bool(
                self._workflowViewPriorState
            )
        finally:
            self._updatingPlanningUI = False

        if not targetRecord:
            message = _("Select a target tooth in Step 4A.")
            style = "color: #b36b00;"
        elif not reviewed:
            message = _("Mark the authoritative segmentation Reviewed first.")
            style = "color: #b36b00;"
        elif existingCount:
            message = _(
                "This tooth already has %1 trajectory node(s). Delete that set "
                "before assisted regeneration; existing plans are never overwritten."
            ).replace("%1", str(existingCount))
            style = "color: #b36b00;"
        elif associationError:
            message = associationError
            style = "color: #b36b00;"
        elif not summary:
            message = _(
                "Choose one or two trajectories, then place only the crown entry point(s)."
            )
            style = "color: #1f5f99;"
        elif not summary["isComplete"]:
            message = _("Placed %1 of %2 crown entry point(s).").replace(
                "%1", str(summary["definedPointCount"])
            ).replace("%2", str(summary["expectedCount"]))
            style = "color: #1f5f99;"
        else:
            message = _(
                "Entry points complete. Generate geometric root targets, then "
                "verify and correct every resulting trajectory in the oblique MPR."
            )
            style = "color: #207227;"
        self.ui.assistedTrajectoryStatusLabel.text = message
        self.ui.assistedTrajectoryStatusLabel.styleSheet = style

    def _startAssistedTrajectoryFocus(self) -> None:
        if not self._parameterNode or not self.logic:
            raise RuntimeError(_("DENTOWorkflow is not ready for target focus."))
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        self._restoreAssistedTrajectoryFocus(updateUi=False)
        segmentationNode = self._parameterNode.teethSegmentation
        segmentId = self._parameterNode.targetToothSegmentId
        boundsRoi = self._parameterNode.targetToothBoundsRoi
        self._assistedTrajectoryFocusState = self.logic.applyTargetToothFocus(
            segmentationNode,
            segmentId,
            boundsRoi,
        )
        bounds = self.logic.getTargetToothBoundsWorld(
            segmentationNode,
            segmentId,
        )
        self._frameRasBoundsInViews(bounds)
        self._syncSegmentationDisplayControls()
        self._updateAssistedTrajectoryControls()

    @staticmethod
    def _workflowCrosshairNode() -> vtkMRMLCrosshairNode:
        """Return Slicer's singleton crosshair used by native 2D/3D picking."""

        node = slicer.mrmlScene.GetSingletonNode(
            "default",
            "vtkMRMLCrosshairNode",
        )
        if not node:
            raise RuntimeError(_("Slicer's shared crosshair node is unavailable."))
        return node

    def _setCrossViewNavigationChecked(self, checked: bool) -> None:
        if not hasattr(self, "ui"):
            return
        self._updatingCrossViewNavigationUI = True
        try:
            self.ui.crossViewNavigationCheckBox.checked = bool(checked)
        finally:
            self._updatingCrossViewNavigationUI = False

    def _enableCrossViewNavigation(self) -> None:
        """Enable accurate native crosshair picking and centred slice jumps."""

        crosshairNode = self._workflowCrosshairNode()
        if self._crossViewNavigationPriorState is None:
            self._crossViewNavigationPriorState = {
                "nodeId": crosshairNode.GetID(),
                "mode": int(crosshairNode.GetCrosshairMode()),
                "behavior": int(crosshairNode.GetCrosshairBehavior()),
                "thickness": int(crosshairNode.GetCrosshairThickness()),
                "fastPick3D": bool(crosshairNode.GetFastPick3D()),
            }
        wasModifying = crosshairNode.StartModify()
        try:
            crosshairNode.SetCrosshairMode(vtkMRMLCrosshairNode.ShowBasic)
            crosshairNode.SetCrosshairBehavior(
                vtkMRMLCrosshairNode.CenteredJumpSlice
            )
            crosshairNode.SetCrosshairThickness(vtkMRMLCrosshairNode.Fine)
            crosshairNode.SetFastPick3D(False)
        finally:
            crosshairNode.EndModify(wasModifying)
        self._setCrossViewNavigationChecked(True)

    def _restoreCrossViewNavigation(self, updateUi: bool = True) -> None:
        """Restore the exact native crosshair state captured on enable."""

        state = self._crossViewNavigationPriorState
        self._crossViewNavigationPriorState = None
        if state:
            crosshairNode = slicer.mrmlScene.GetNodeByID(state.get("nodeId"))
            if not crosshairNode:
                try:
                    crosshairNode = self._workflowCrosshairNode()
                except RuntimeError:
                    crosshairNode = None
            if crosshairNode:
                wasModifying = crosshairNode.StartModify()
                try:
                    crosshairNode.SetCrosshairMode(int(state["mode"]))
                    crosshairNode.SetCrosshairBehavior(int(state["behavior"]))
                    crosshairNode.SetCrosshairThickness(int(state["thickness"]))
                    crosshairNode.SetFastPick3D(bool(state["fastPick3D"]))
                finally:
                    crosshairNode.EndModify(wasModifying)
        if updateUi:
            self._setCrossViewNavigationChecked(False)

    def onCrossViewNavigationToggled(self, checked: bool) -> None:
        if self._updatingCrossViewNavigationUI:
            return
        try:
            if checked:
                self._enableCrossViewNavigation()
            else:
                self._restoreCrossViewNavigation(updateUi=False)
        except RuntimeError as exc:
            self._restoreCrossViewNavigation(updateUi=True)
            slicer.util.errorDisplay(str(exc))

    @staticmethod
    def _frameRasBoundsInViews(bounds) -> tuple[float, float, float]:
        """Centre finite world-RAS bounds in native Slicer 2D/3D views."""

        values = np.asarray(tuple(bounds), dtype=float)
        if values.shape != (6,) or not np.all(np.isfinite(values)):
            raise ValueError(_("Six finite world-RAS bounds are required."))
        minimum = np.asarray((values[0], values[2], values[4]), dtype=float)
        maximum = np.asarray((values[1], values[3], values[5]), dtype=float)
        extents = maximum - minimum
        if np.any(extents < 0.0):
            raise ValueError(_("World-RAS bounds have reversed limits."))
        center = (minimum + maximum) * 0.5
        paddedSpan = max(float(np.max(extents)) * 1.35, 2.0)

        try:
            slicer.modules.markups.logic().JumpSlicesToLocation(
                float(center[0]),
                float(center[1]),
                float(center[2]),
                True,
            )
        except Exception:
            logging.debug("Could not centre active slice views on workflow bounds.")

        layoutManager = slicer.app.layoutManager()
        if layoutManager:
            try:
                sliceViewNames = tuple(layoutManager.sliceViewNames())
            except Exception:
                sliceViewNames = ()
            for sliceViewName in sliceViewNames:
                try:
                    sliceWidget = layoutManager.sliceWidget(sliceViewName)
                    sliceView = sliceWidget.sliceView()
                    sliceNode = sliceWidget.mrmlSliceNode()
                    widthValue = getattr(sliceView, "width", 1)
                    heightValue = getattr(sliceView, "height", 1)
                    viewWidth = max(
                        int(widthValue() if callable(widthValue) else widthValue),
                        1,
                    )
                    viewHeight = max(
                        int(heightValue() if callable(heightValue) else heightValue),
                        1,
                    )
                    aspect = float(viewWidth) / float(viewHeight)
                    if aspect >= 1.0:
                        fieldWidth = paddedSpan * aspect
                        fieldHeight = paddedSpan
                    else:
                        fieldWidth = paddedSpan
                        fieldHeight = paddedSpan / aspect
                    oldField = sliceNode.GetFieldOfView()
                    fieldDepth = max(float(oldField[2]), paddedSpan)
                    sliceNode.SetFieldOfView(
                        fieldWidth,
                        fieldHeight,
                        fieldDepth,
                    )
                    sliceNode.UpdateMatrices()
                except Exception:
                    logging.debug(
                        "Could not fit workflow bounds in slice view %s.",
                        sliceViewName,
                    )

            try:
                threeDViewCount = int(layoutManager.threeDViewCount)
            except (AttributeError, TypeError, ValueError):
                try:
                    threeDViewCount = int(layoutManager.threeDViewCount())
                except Exception:
                    threeDViewCount = 0
            radius = max(float(np.linalg.norm(extents)) * 0.5, 1.0)
            for viewIndex in range(threeDViewCount):
                try:
                    threeDView = layoutManager.threeDWidget(viewIndex).threeDView()
                    cameraNode = threeDView.cameraNode()
                    camera = cameraNode.GetCamera()
                    oldPosition = np.asarray(camera.GetPosition(), dtype=float)
                    oldFocalPoint = np.asarray(camera.GetFocalPoint(), dtype=float)
                    outward = oldPosition - oldFocalPoint
                    norm = float(np.linalg.norm(outward))
                    if norm <= 1e-6 or not math.isfinite(norm):
                        outward = np.asarray((0.0, -1.0, 0.0), dtype=float)
                    else:
                        outward /= norm
                    camera.SetFocalPoint(*center.tolist())
                    camera.SetPosition(
                        *(center + outward * max(radius * 3.8, 8.0)).tolist()
                    )
                    camera.SetParallelScale(max(paddedSpan * 0.5, 1.0))
                    camera.OrthogonalizeViewUp()
                    cameraNode.Modified()
                    threeDView.resetCameraClippingRange()
                    threeDView.forceRender()
                except Exception:
                    logging.debug(
                        "Could not fit workflow bounds in 3D view %d.",
                        viewIndex,
                    )
        return tuple(float(value) for value in center)

    def onFocusPlanningTarget(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            self.logic.validateTargetTooth(
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
            )
            self._applyWorkflowViewPreset("trajectory_only")
            self._enableCrossViewNavigation()
            self.onFramePlanningTarget()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onRestorePlanningView(self) -> None:
        self._restoreWorkflowViewState(updateUi=True)
        self._updatePlanning()

    def onFramePlanningTarget(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            bounds = self.logic.getTargetToothBoundsWorld(
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
            )
            self._frameRasBoundsInViews(bounds)
            self._presentSelectedTrajectory(
                self._parameterNode.trajectoryLine,
                centerSlices=True,
            )
            self._enableCrossViewNavigation()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def _presentSelectedTrajectory(
        self,
        trajectoryNode,
        *,
        centerSlices: bool = True,
    ) -> None:
        """Reveal the exact selected line and centre slices without changing geometry."""

        if not trajectoryNode or not self.logic:
            return
        displayNode = trajectoryNode.GetDisplayNode()
        if displayNode:
            displayNode.SetVisibility(True)
            if hasattr(displayNode, "SetVisibility2D"):
                displayNode.SetVisibility2D(True)
            if hasattr(displayNode, "SetVisibility3D"):
                displayNode.SetVisibility3D(True)
            displayNode.SetPointLabelsVisibility(True)
            displayNode.SetPropertiesLabelVisibility(True)
            displayNode.SetSliceProjection(True)
            displayNode.SetSliceProjectionUseFiducialColor(True)
            displayNode.SetSliceProjectionOpacity(1.0)
        trajectoryNode.SetSelectable(True)
        try:
            summary = self.logic.getTrajectorySummary(trajectoryNode)
        except ValueError:
            return
        points = [
            np.asarray(point, dtype=float)
            for point in (summary["entryRas"], summary["targetRas"])
            if point is not None
        ]
        if not points:
            return
        center = np.mean(np.vstack(points), axis=0)
        if centerSlices:
            try:
                slicer.modules.markups.logic().JumpSlicesToLocation(
                    float(center[0]),
                    float(center[1]),
                    float(center[2]),
                    True,
                )
            except Exception:
                logging.debug("Could not centre slices on the selected trajectory.")

    def _restoreAssistedTrajectoryFocus(self, updateUi: bool = True) -> None:
        state = self._assistedTrajectoryFocusState
        self._assistedTrajectoryFocusState = None
        if state and self.logic:
            self.logic.restoreTargetToothFocus(state)
        if (
            updateUi
            and not self._isCleaningUp
            and hasattr(self, "ui")
            and self._reviewSegmentationNode
        ):
            self._syncSegmentationDisplayControls()
            self._updateAssistedTrajectoryControls()

    def onRestoreAssistedTrajectoryFocus(self) -> None:
        self._restoreAssistedTrajectoryFocus(updateUi=True)

    def onAssistedTrajectoryCountChanged(self, index: int) -> None:
        if self._updatingPlanningUI or not self._parameterNode:
            return
        value = self.ui.assistedTrajectoryCountComboBox.itemData(index)
        try:
            count = int(value)
        except (TypeError, ValueError):
            return
        if count not in (1, 2):
            return
        self._parameterNode.assistedTrajectoryCount = count
        self._updateAssistedTrajectoryControls()

    def onPlaceAssistedTrajectoryEntries(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            segmentationNode = self._parameterNode.teethSegmentation
            segmentId = self._parameterNode.targetToothSegmentId
            self.logic.validateTargetTooth(segmentationNode, segmentId)
            if self.logic.getSegmentationReviewState(segmentationNode) != "Reviewed":
                raise ValueError(
                    _("Mark the authoritative segmentation Reviewed first.")
                )
            if self.logic.dentobotTrajectoriesForTarget(
                segmentationNode, segmentId
            ):
                raise ValueError(
                    _(
                        "Delete the target tooth's existing trajectory set before "
                        "placing a new assisted set."
                    )
                )
            currentNode = self._parameterNode.assistedTrajectoryEntries
            if self.logic.isAssistedTrajectoryEntryNode(currentNode):
                currentSummary = self.logic.getAssistedTrajectoryEntrySummary(
                    currentNode
                )
                if currentSummary["definedPointCount"] and not slicer.util.confirmYesNoDisplay(
                    _(
                        "Replace the current assisted crown entry points? The "
                        "existing points will be removed."
                    ),
                    windowTitle=_("Replace assisted Step 4A entries"),
                ):
                    return
            entryNode, _summary = self.logic.createOrResetAssistedTrajectoryEntries(
                segmentationNode,
                segmentId,
                self._parameterNode.assistedTrajectoryCount,
                currentNode,
            )
            self._parameterNode.assistedTrajectoryEntries = entryNode
            self._bindAssistedTrajectoryEntryNode(entryNode)
            self._startAssistedTrajectoryFocus()
            self.logic.startAssistedTrajectoryEntryPlacement(entryNode)
            self._updateAssistedTrajectoryControls()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onGenerateAssistedTrajectories(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            self.logic.stopTrajectoryPlacement()
            trajectories, analysis = self.logic.generateAssistedTrajectories(
                self._parameterNode.assistedTrajectoryEntries,
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
                self._parameterNode.assistedTrajectoryCount,
                self._parameterNode.targetToothBoundsRoi,
            )
            self._parameterNode.trajectoryLine = trajectories[0]
            self._bindPlanningTrajectoryNode(trajectories[0])
            self._restoreAssistedTrajectoryFocus(updateUi=False)
            separation = analysis.get("rootSeparationMm")
            detail = (
                _(" Root-branch separation estimate: %1 mm.").replace(
                    "%1", f"{float(separation):.2f}"
                )
                if separation is not None
                else ""
            )
            slicer.util.infoDisplay(
                _(
                    "Created %1 unlocked assisted trajectory node(s).%2 These "
                    "targets come from complete-tooth surface geometry, not a "
                    "canal centreline. Verify and correct every Entry/Target in "
                    "the trajectory-aligned MPR before approval."
                ).replace("%1", str(len(trajectories))).replace("%2", detail),
                windowTitle=_("Assisted Step 4A trajectories"),
            )
            self._updatePlanning()
            self._updateTemplateModeling()
            self._updateTemplateGuide()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def _targetDockingParameters(self) -> dict:
        if not self._parameterNode:
            raise ValueError(_("DENTOWorkflow has no active parameter node."))
        return normalize_target_docking_parameters(
            pattern_radius_mm=self._parameterNode.targetDockingPatternRadiusMm,
            outer_diameter_mm=self._parameterNode.targetDockingOuterDiameterMm,
            bore_diameter_mm=self._parameterNode.targetDockingBoreDiameterMm,
            connector_diameter_mm=(
                self._parameterNode.targetDockingConnectorDiameterMm
            ),
            connector_thickness_mm=(
                self._parameterNode.targetDockingConnectorThicknessMm
            ),
            shared_depth_mm=self._parameterNode.targetDockingSharedDepthMm,
            individual_depths_mm=(
                self._parameterNode.targetDockingDepth1Mm,
                self._parameterNode.targetDockingDepth2Mm,
                self._parameterNode.targetDockingDepth3Mm,
                self._parameterNode.targetDockingDepth4Mm,
            ),
            individual_depths_enabled=(
                self._parameterNode.targetDockingIndividualDepthsEnabled
            ),
            yaw_deg=self._parameterNode.targetDockingYawDeg,
            collision_clearance_mm=(
                self._parameterNode.targetDockingCollisionClearanceMm
            ),
            clearance_mm=self._parameterNode.templateDockingClearanceMm,
            reinforcement_radial_mm=(
                self._parameterNode.templateReinforcementRadialMm
            ),
            processing_resolution_mm=(
                self._parameterNode.templateSamplingSpacingMm
            ),
        )

    def _updateTargetDocking(self) -> None:
        if self._updatingTargetDockingUI or not hasattr(self, "ui"):
            return
        if not self._parameterNode or not self.logic:
            self.ui.generateTargetDockingAssemblyButton.enabled = False
            self.ui.deleteTargetDockingAssemblyButton.enabled = False
            self.ui.targetDockingTrajectorySummaryLabel.text = _("--")
            return
        individual = bool(
            self._parameterNode.targetDockingIndividualDepthsEnabled
        )
        self.ui.targetDockingIndividualDepthsWidget.visible = individual
        self.ui.targetDockingSharedDepthSpinBox.enabled = not individual
        planeNode = self._parameterNode.targetDockingReferencePlane
        assemblyModel = self._parameterNode.targetDockingAssemblyModel
        desiredYaw = int(round(float(self._parameterNode.targetDockingYawDeg)))
        self._updatingTargetDockingUI = True
        try:
            if int(self.ui.targetDockingYawSlider.value) != desiredYaw:
                self.ui.targetDockingYawSlider.value = desiredYaw
            self.ui.targetDockingYawValueLabel.text = f"{desiredYaw}°"
            if self.ui.targetDockingReferencePlaneSelector.currentNode() is not planeNode:
                self.ui.targetDockingReferencePlaneSelector.setCurrentNode(planeNode)
            if self.ui.targetDockingAssemblyModelSelector.currentNode() is not assemblyModel:
                self.ui.targetDockingAssemblyModelSelector.setCurrentNode(assemblyModel)
        finally:
            self._updatingTargetDockingUI = False

        inputError = ""
        trajectories = []
        parameters = None
        supportSummary = None
        try:
            segmentationNode = self._parameterNode.teethSegmentation
            targetSegmentId = self._parameterNode.targetToothSegmentId
            self.logic.validateTargetTooth(segmentationNode, targetSegmentId)
            if self.logic.getSegmentationReviewState(segmentationNode) != "Reviewed":
                raise ValueError(_("Mark the authoritative segmentation Reviewed first."))
            trajectories = self.logic.targetDockingTrajectoriesForTarget(
                segmentationNode,
                targetSegmentId,
            )
            supportSummary = self.logic.getDraftTemplateSupportModelSummary(
                self._parameterNode.draftTemplateSupportModel
            )
            if supportSummary["geometryState"] != "Current":
                raise ValueError(_("Update the stale Step 4B support draft first."))
            if supportSummary["sourceSegmentation"] is not segmentationNode:
                raise ValueError(_("The Step 4B support draft uses another segmentation."))
            if supportSummary["targetSegmentId"] != targetSegmentId:
                raise ValueError(_("The Step 4B support draft uses another target tooth."))
            parameters = self._targetDockingParameters()
        except (RuntimeError, ValueError) as exc:
            inputError = str(exc)
        self.ui.targetDockingTrajectorySummaryLabel.text = (
            ", ".join(node.GetName() or _("Unnamed") for node in trajectories)
            if trajectories
            else _("--")
        )
        self._bindSelectedGuideTrajectoryNodes(trajectories)

        summary = None
        outputError = ""
        if assemblyModel:
            try:
                summary = self.logic.getTargetDockingAssemblySummary(assemblyModel)
                trajectoryGeometry = []
                for node in trajectories:
                    trajectorySummary = self.logic.getTrajectorySummary(node)
                    trajectoryGeometry.append(
                        {
                            "entryRas": [
                                float(value)
                                for value in trajectorySummary["entryRas"]
                            ],
                            "targetRas": [
                                float(value)
                                for value in trajectorySummary["targetRas"]
                            ],
                        }
                    )
                staleReason = ""
                if inputError:
                    staleReason = inputError
                elif summary["segmentation"] is not self._parameterNode.teethSegmentation:
                    staleReason = _("The authoritative segmentation changed.")
                elif summary["targetSegmentId"] != self._parameterNode.targetToothSegmentId:
                    staleReason = _("The target tooth changed.")
                elif summary["trajectories"] != trajectories:
                    staleReason = _("The target trajectory set changed.")
                elif summary.get("supportModel") is not self._parameterNode.draftTemplateSupportModel:
                    staleReason = _("The Step 4B support-anatomy draft changed.")
                elif summary.get("supportSegmentIds") != supportSummary["supportSegmentIds"]:
                    staleReason = _("The Step 4B support-tooth selection changed.")
                elif summary.get("supportDraftUpdatedUtc") != supportSummary["updatedUtc"]:
                    staleReason = _("The Step 4B support-anatomy geometry changed.")
                elif summary["parametersJson"] != json.dumps(
                    parameters,
                    sort_keys=True,
                    separators=(",", ":"),
                ):
                    staleReason = _("A Step 4C docking dimension changed.")
                elif summary["trajectoryGeometryJson"] != json.dumps(
                    trajectoryGeometry,
                    sort_keys=True,
                    separators=(",", ":"),
                ):
                    staleReason = _("A source trajectory geometry changed.")
                if staleReason:
                    self.logic.markTargetDockingAssemblyStale(
                        assemblyModel,
                        staleReason,
                    )
                    self.logic.markFinalPrintableTemplateStale(
                        self._parameterNode.finalPrintableTemplateModel,
                        staleReason,
                    )
                    summary = self.logic.getTargetDockingAssemblySummary(
                        assemblyModel
                    )
                elif (
                    summary["geometryState"] == "Stale"
                    and summary["staleReason"]
                    in {
                        _("A Step 4C docking parameter changed."),
                        _("A source guide trajectory changed."),
                        _(
                            "The requested Step 4C yaw changed; apply it to "
                            "rebuild the draft."
                        ),
                    }
                ):
                    # Parameter-wrapper signals may fire while an MRB restores
                    # widget values. If all authoritative references, stored
                    # dimensions, and trajectory geometry still agree, the
                    # stale mark was a no-op UI synchronization artifact. The
                    # orientation remains Draft and still requires confirmation.
                    assemblyModel.SetAttribute("DENTOBOT.GeometryState", "Current")
                    assemblyModel.SetAttribute("DENTOBOT.StaleReason", None)
                    summary = self.logic.getTargetDockingAssemblySummary(
                        assemblyModel
                    )
            except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
                outputError = str(exc)
        self.ui.generateTargetDockingAssemblyButton.enabled = bool(
            trajectories and parameters and supportSummary and not outputError
        )
        self.ui.deleteTargetDockingAssemblyButton.enabled = bool(
            self.logic.isTargetDockingAssemblyModelNode(assemblyModel)
        )
        isCurrent = bool(summary and summary["geometryState"] == "Current")
        isConfirmed = bool(
            isCurrent and summary.get("orientationState") == "Confirmed"
        )
        self._parameterNode.targetDockingYawConfirmed = isConfirmed
        self.ui.applyTargetDockingYawButton.enabled = bool(
            trajectories
            and parameters
            and not outputError
            and self.logic.isTargetDockingAssemblyModelNode(assemblyModel)
        )
        self.ui.confirmTargetDockingYawButton.enabled = isCurrent
        self.ui.targetDockingOrientationStateLabel.text = (
            _("CONFIRMED — dock orientation may enter Step 5B fusion")
            if isConfirmed
            else _("DRAFT — inspect, adjust yaw if needed, then confirm")
        )
        self.ui.targetDockingOrientationStateLabel.styleSheet = (
            "color: #207227; font-weight: 700;"
            if isConfirmed
            else "color: #b36b00; font-weight: 700;"
        )
        if summary:
            collisionScreen = summary["metrics"].get("collisionScreen") or {}
            autoYawSearch = summary["metrics"].get("autoYawSearch") or {}
            collisionCount = int(collisionScreen.get("collidingDockCount", 0))
            obstacleCount = int(collisionScreen.get("obstacleSurfaceCount", 0))
            freeCandidates = autoYawSearch.get("collisionFreeCandidateCount")
            autoSuffix = (
                _("; %1 collision-free sweep candidate(s)").replace(
                    "%1", str(freeCandidates)
                )
                if freeCandidates is not None
                else ""
            )
            omittedCount = len(summary.get("omittedObstacleSegmentIds") or [])
            omittedSuffix = (
                _("; WARNING: %1 same-jaw tooth surface(s) could not be screened")
                .replace("%1", str(omittedCount))
                if omittedCount
                else ""
            )
            self.ui.targetDockingAutoYawStatusLabel.text = (
                _(
                    "Yaw %1° screened against %2 other same-jaw whole-tooth "
                    "surface(s): %3 dock collision(s)%4%5. Draft screen only."
                )
                .replace("%1", f"{float(summary['metrics'].get('yawDeg', 0.0)):.1f}")
                .replace("%2", str(obstacleCount))
                .replace("%3", str(collisionCount))
                .replace("%4", autoSuffix)
                .replace("%5", omittedSuffix)
            )
            self.ui.targetDockingAutoYawStatusLabel.styleSheet = (
                "color: #207227;" if not collisionCount and not omittedCount
                else "color: #b36b00;"
            )
        else:
            self.ui.targetDockingAutoYawStatusLabel.text = _(
                "Generate a draft to calculate yaw against all other "
                "same-jaw whole-tooth surfaces."
            )
            self.ui.targetDockingAutoYawStatusLabel.styleSheet = "color: #1f5f99;"
        if outputError:
            message, style = outputError, "color: #b00020;"
        elif inputError:
            message, style = inputError, "color: #b36b00;"
        elif isCurrent:
            message = _(
                "Four independent docks are current at yaw %1°: top/opening "
                "faces on the target-crown occlusal plane, %2 mm radius, %3 mm "
                "bore, maximum face-plane residual %4 mm. %5"
            ).replace("%1", f"{parameters['yawDeg']:.1f}").replace(
                "%2", f"{parameters['patternRadiusMm']:.2f}"
            ).replace(
                "%3",
                f"{parameters['boreDiameterMm']:.2f}",
            ).replace(
                "%4",
                f"{summary['metrics'].get('topPlaneMaxResidualMm', 0.0):.4f}",
            ).replace(
                "%5",
                _("Orientation confirmed.")
                if isConfirmed
                else _("Draft orientation still requires confirmation."),
            )
            style = "color: #207227;" if isConfirmed else "color: #b36b00;"
        elif summary:
            message = _("Step 4C assembly is stale: %1").replace(
                "%1",
                summary["staleReason"] or _("regeneration required"),
            )
            style = "color: #b36b00;"
        else:
            message = _(
                "Ready to generate four independent occlusal-plane docks from the locked trajectory set."
            )
            style = "color: #1f5f99;"
        self.ui.targetDockingStatusLabel.text = message
        self.ui.targetDockingStatusLabel.styleSheet = style

    def onTargetDockingInputChanged(self, *args) -> None:
        del args
        if self._updatingTargetDockingUI or not self._parameterNode or not self.logic:
            return
        reason = _("A Step 4C docking parameter changed.")
        assemblyModel = self._parameterNode.targetDockingAssemblyModel
        if self.logic.isTargetDockingAssemblyModelNode(assemblyModel):
            try:
                storedParametersJson = (
                    assemblyModel.GetAttribute("DENTOBOT.ParametersJson") or ""
                )
                currentParametersJson = json.dumps(
                    self._targetDockingParameters(),
                    sort_keys=True,
                    separators=(",", ":"),
                )
            except (RuntimeError, ValueError):
                storedParametersJson = ""
                currentParametersJson = "invalid"
            if storedParametersJson == currentParametersJson:
                qt.QTimer.singleShot(0, self._updateTargetDocking)
                return
        self._parameterNode.targetDockingYawConfirmed = False
        for node in (
            self._parameterNode.targetDockingAssemblyModel,
            self._parameterNode.targetDockingReferencePlane,
        ):
            if node:
                node.SetAttribute("DENTOBOT.OrientationState", "Draft")
                node.SetAttribute("DENTOBOT.OrientationConfirmedUtc", None)
        self.logic.markTargetDockingAssemblyStale(
            self._parameterNode.targetDockingAssemblyModel,
            reason,
        )
        self.logic.markFinalPrintableTemplateStale(
            self._parameterNode.finalPrintableTemplateModel,
            reason,
        )
        qt.QTimer.singleShot(0, self._updateTargetDocking)

    def onTargetDockingYawChanged(self, value: int) -> None:
        if self._updatingTargetDockingUI or not self._parameterNode or not self.logic:
            return
        yaw = float(value)
        self.ui.targetDockingYawValueLabel.text = f"{int(value)}°"
        self._parameterNode.targetDockingYawDeg = yaw
        self._parameterNode.targetDockingYawConfirmed = False
        assemblyModel = self._parameterNode.targetDockingAssemblyModel
        planeNode = self._parameterNode.targetDockingReferencePlane
        for node in (assemblyModel, planeNode):
            if node:
                node.SetAttribute("DENTOBOT.OrientationState", "Draft")
                node.SetAttribute("DENTOBOT.OrientationConfirmedUtc", None)
        if self.logic.isTargetDockingAssemblyModelNode(assemblyModel):
            try:
                storedParameters = json.loads(
                    assemblyModel.GetAttribute("DENTOBOT.ParametersJson") or "{}"
                )
            except json.JSONDecodeError:
                storedParameters = {}
            if not math.isclose(
                float(storedParameters.get("yawDeg", math.inf)),
                yaw,
                abs_tol=1e-9,
            ):
                reason = _(
                    "The requested Step 4C yaw changed; apply it to rebuild the draft."
                )
                self.logic.markTargetDockingAssemblyStale(assemblyModel, reason)
                self.logic.markFinalPrintableTemplateStale(
                    self._parameterNode.finalPrintableTemplateModel,
                    reason,
                )
        qt.QTimer.singleShot(0, self._updateTargetDocking)

    def _regenerateTargetDocking(self, *, autoSelectYaw: bool) -> None:
        trajectories = self.logic.targetDockingTrajectoriesForTarget(
            self._parameterNode.teethSegmentation,
            self._parameterNode.targetToothSegmentId,
        )
        planeNode, assemblyModel, details = (
            self.logic.createOrUpdateTargetDockingAssembly(
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
                trajectories,
                self._targetDockingParameters(),
                supportModel=self._parameterNode.draftTemplateSupportModel,
                planeNode=self._parameterNode.targetDockingReferencePlane,
                assemblyModel=self._parameterNode.targetDockingAssemblyModel,
                autoSelectYaw=autoSelectYaw,
                measurementsVisible=(
                    self._parameterNode.targetDockingMeasurementsVisible
                ),
            )
        )
        wasModifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.targetDockingReferencePlane = planeNode
            self._parameterNode.targetDockingAssemblyModel = assemblyModel
            self._parameterNode.targetDockingYawDeg = float(
                details["parameters"]["yawDeg"]
            )
            self._parameterNode.targetDockingYawConfirmed = False
        finally:
            self._parameterNode.EndModify(wasModifying)
        self.logic.markFinalPrintableTemplateStale(
            self._parameterNode.finalPrintableTemplateModel,
            _("The Step 4C docking assembly was regenerated."),
        )
        logging.info(
            "Generated Step 4C four-dock draft %s at yaw %.1f degrees "
            "with %d docks and %d screened collisions",
            assemblyModel.GetID(),
            float(details["parameters"]["yawDeg"]),
            details["metrics"]["dockCount"],
            int(
                details["metrics"].get("collisionScreen", {}).get(
                    "collidingDockCount", 0
                )
            ),
        )
        self._updateTargetDocking()
        self._updateTemplateGuide()

    def onApplyTargetDockingYaw(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            self._regenerateTargetDocking(autoSelectYaw=False)
        except (RuntimeError, ValueError) as exc:
            self.ui.targetDockingStatusLabel.text = str(exc)
            self.ui.targetDockingStatusLabel.styleSheet = "color: #b00020;"
            slicer.util.errorDisplay(str(exc))

    def onConfirmTargetDockingYaw(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        assemblyModel = self._parameterNode.targetDockingAssemblyModel
        try:
            summary = self.logic.getTargetDockingAssemblySummary(assemblyModel)
            if summary["geometryState"] != "Current":
                raise ValueError(_("Apply or regenerate the stale Step 4C draft first."))
            expectedParametersJson = json.dumps(
                self._targetDockingParameters(),
                sort_keys=True,
                separators=(",", ":"),
            )
            if summary["parametersJson"] != expectedParametersJson:
                raise ValueError(
                    _("Apply the current docking dimensions and yaw before confirmation.")
                )
            collisionScreen = summary["metrics"].get("collisionScreen") or {}
            collisionCount = int(collisionScreen.get("collidingDockCount", 0))
            omittedCount = len(summary.get("omittedObstacleSegmentIds") or [])
            if (collisionCount or omittedCount) and not slicer.util.confirmYesNoDisplay(
                _(
                    "This draft reports %1 colliding dock(s), and %2 same-jaw "
                    "tooth surface(s) were omitted from screening. The screen "
                    "uses sampled segmentation surfaces and is not clinical "
                    "collision validation. Confirm this orientation anyway?"
                )
                .replace("%1", str(collisionCount))
                .replace("%2", str(omittedCount)),
                windowTitle=_("Confirm Step 4C draft orientation"),
            ):
                return
            timestamp = datetime.now(timezone.utc).isoformat()
            for node in (assemblyModel, summary["plane"]):
                node.SetAttribute("DENTOBOT.OrientationState", "Confirmed")
                node.SetAttribute("DENTOBOT.OrientationConfirmedUtc", timestamp)
            self._parameterNode.targetDockingYawConfirmed = True
            self.logic.markFinalPrintableTemplateStale(
                self._parameterNode.finalPrintableTemplateModel,
                _("The Step 4C dock orientation confirmation changed."),
            )
            self._updateTargetDocking()
            self._updateTemplateGuide()
        except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onTargetDockingMeasurementsVisibilityChanged(self, visible: bool) -> None:
        if self._updatingTargetDockingUI or not self._parameterNode:
            return
        self._parameterNode.targetDockingMeasurementsVisible = bool(visible)
        assemblyModel = self._parameterNode.targetDockingAssemblyModel
        if assemblyModel:
            role = self.logic.TARGET_DOCKING_MEASUREMENT_REFERENCE_ROLE
            for index in range(assemblyModel.GetNumberOfNodeReferences(role)):
                node = assemblyModel.GetNthNodeReference(role, index)
                displayNode = node.GetDisplayNode() if node else None
                if displayNode:
                    displayNode.SetVisibility(bool(visible))
                    displayNode.SetVisibility2D(bool(visible))
                    displayNode.SetVisibility3D(bool(visible))
        self._refreshWorkflowViewAfterStateChange()

    def onTargetDockingReferencePlaneSelectionChanged(self, planeNode) -> None:
        if self._updatingTargetDockingUI or not self._parameterNode:
            return
        self._parameterNode.targetDockingReferencePlane = planeNode
        self._updateTargetDocking()

    def onTargetDockingAssemblySelectionChanged(self, assemblyModel) -> None:
        if self._updatingTargetDockingUI or not self._parameterNode:
            return
        self._parameterNode.targetDockingAssemblyModel = assemblyModel
        self._updateTargetDocking()

    def onGenerateTargetDockingAssembly(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            self._regenerateTargetDocking(autoSelectYaw=True)
        except (RuntimeError, ValueError) as exc:
            self.ui.targetDockingStatusLabel.text = str(exc)
            self.ui.targetDockingStatusLabel.styleSheet = "color: #b00020;"
            slicer.util.errorDisplay(str(exc))

    def onDeleteTargetDockingAssembly(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        assemblyModel = self._parameterNode.targetDockingAssemblyModel
        if not self.logic.isTargetDockingAssemblyModelNode(assemblyModel):
            slicer.util.errorDisplay(_("Select the DENTOBOT Step 4C assembly."))
            return
        if not slicer.util.confirmYesNoDisplay(
            _(
                "Delete the Step 4C four-dock assembly and reference plane? "
                "Any integrated Step 5B final template will also be deleted. "
                "The segmentation and trajectories are preserved."
            ),
            windowTitle=_("Delete Step 4C docking assembly"),
        ):
            return
        try:
            self._deleteFinalPrintableTemplateCascade()
            removals = self.logic.deleteTargetDockingAssembly(assemblyModel)
            logging.info("Deleted Step 4C docking subtree containing %d nodes", len(removals))
            self._updateTargetDocking()
            self._updateTemplateGuide()
            self._updateTemplateFinalization()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def _updatePlanning(self) -> None:
        if not self._parameterNode or not self.logic:
            self._clearPlanning()
            return

        trajectoryNode = self._parameterNode.trajectoryLine
        trajectoryAssociationError = ""
        association = None
        if trajectoryNode:
            try:
                association = self.logic.getTrajectoryTargetAssociation(
                    trajectoryNode
                )
            except ValueError as exc:
                trajectoryAssociationError = str(exc)
        if association:
            associatedSegmentation = association["segmentationNode"]
            associatedTargetId = association["targetRecord"]["segmentId"]
            associatedRoi = association["targetBoundsRoi"]
            if (
                self._parameterNode.teethSegmentation is not associatedSegmentation
                or self._parameterNode.targetToothSegmentId != associatedTargetId
                or self._parameterNode.targetToothBoundsRoi is not associatedRoi
            ):
                self._restoringTrajectoryAssociation = True
                wasModifying = self._parameterNode.StartModify()
                try:
                    self._parameterNode.teethSegmentation = associatedSegmentation
                    self._parameterNode.targetToothSegmentId = associatedTargetId
                    self._parameterNode.targetToothBoundsRoi = associatedRoi
                finally:
                    self._parameterNode.EndModify(wasModifying)
                    self._restoringTrajectoryAssociation = False

        segmentationNode = self._parameterNode.teethSegmentation
        if not segmentationNode:
            self._clearPlanning()
            return

        wasUpdatingPlanningUI = self._updatingPlanningUI
        self._updatingPlanningUI = True
        try:
            self.logic.refreshWorkflowLineageColors()
            self.logic.refreshManagedTrajectoryNames()
            self.logic.refreshWorkflowNodeStepTags()
            if self.ui.trajectorySelector.currentNode() is not trajectoryNode:
                wasRestoringAssociation = self._restoringTrajectoryAssociation
                self._restoringTrajectoryAssociation = True
                try:
                    self.ui.trajectorySelector.setCurrentNode(trajectoryNode)
                finally:
                    self._restoringTrajectoryAssociation = (
                        wasRestoringAssociation
                    )
        finally:
            self._updatingPlanningUI = wasUpdatingPlanningUI

        try:
            targetRecords = self.logic.getTargetToothRecords(segmentationNode)
        except ValueError as exc:
            self._clearPlanning()
            self.ui.planningStatusLabel.text = str(exc)
            self.ui.planningStatusLabel.styleSheet = "color: #b00020;"
            return

        self._targetToothRecordsById = {
            record["segmentId"]: record for record in targetRecords
        }
        requestedTargetId = self._parameterNode.targetToothSegmentId
        targetRecord = self._targetToothRecordsById.get(requestedTargetId)
        if requestedTargetId and not targetRecord:
            if self._parameterNode.trajectoryLine:
                self.logic.clearTrajectoryTarget(
                    self._parameterNode.trajectoryLine
                )
            self._parameterNode.targetToothSegmentId = ""
            requestedTargetId = ""

        self._updatingPlanningUI = True
        try:
            self.ui.targetToothComboBox.clear()
            self.ui.targetToothComboBox.addItem(_("Select target tooth..."), "")
            selectedIndex = 0
            for index, record in enumerate(targetRecords, start=1):
                self.ui.targetToothComboBox.addItem(
                    record["displayName"],
                    record["segmentId"],
                )
                if record["segmentId"] == requestedTargetId:
                    selectedIndex = index
            self.ui.targetToothComboBox.setCurrentIndex(selectedIndex)
            self.ui.targetToothComboBox.enabled = bool(targetRecords)
            self.ui.createTrajectoryButton.enabled = bool(targetRecord)
            if targetRecord:
                self.ui.targetToothValueLabel.text = targetRecord["displayName"]
                self.ui.targetToothSourceValueLabel.text = targetRecord[
                    "sourceName"
                ]
            else:
                self.ui.targetToothValueLabel.text = _("--")
                self.ui.targetToothSourceValueLabel.text = _("--")
        finally:
            self._updatingPlanningUI = False

        targetBounds = None
        if trajectoryAssociationError:
            self._planningConstraintWarning = trajectoryAssociationError
        if targetRecord:
            targetBounds = self._ensureTargetBounds(
                segmentationNode,
                targetRecord,
            )
            self._applyTargetPriorityHighlight()
        else:
            self.ui.targetBoundsValueLabel.text = _("--")
            roiNode = self._parameterNode.targetToothBoundsRoi
            if roiNode and roiNode.GetDisplayNode():
                roiNode.GetDisplayNode().SetVisibility(False)

        self._updatingPlanningUI = True
        try:
            self.ui.focusPlanningTargetButton.enabled = bool(
                targetRecord and targetBounds is not None
            )
            self.ui.framePlanningTargetButton.enabled = bool(
                targetRecord and targetBounds is not None
            )
            self.ui.restorePlanningViewButton.enabled = bool(
                self._assistedTrajectoryFocusState
            )
        finally:
            self._updatingPlanningUI = False

        self.logic.refreshWorkflowLineageColors()
        self.logic.applyTrajectoryGroupEmphasis(
            segmentationNode,
            targetRecord["segmentId"] if targetRecord else "",
            trajectoryNode,
        )
        self._updateTrajectorySelectorColorSwatches()

        self._bindPlanningTrajectoryNode(trajectoryNode)
        if targetRecord and trajectoryNode and not trajectoryAssociationError:
            currentTargetNode = trajectoryNode.GetNodeReference(
                self.logic.TARGET_SEGMENTATION_REFERENCE_ROLE
            )
            currentTargetId = trajectoryNode.GetAttribute(
                "DENTOBOT.TargetSegmentID"
            )
            if (
                currentTargetNode is not segmentationNode
                or currentTargetId != targetRecord["segmentId"]
            ):
                self._updatingPlanningUI = True
                try:
                    self.logic.configureTrajectoryTarget(
                        trajectoryNode,
                        segmentationNode,
                        targetRecord["segmentId"],
                    )
                finally:
                    self._updatingPlanningUI = False
            roiNode = self._parameterNode.targetToothBoundsRoi
            if roiNode and trajectoryNode.GetNodeReference(
                self.logic.TARGET_BOUNDS_ROI_REFERENCE_ROLE
            ) is not roiNode:
                trajectoryNode.SetNodeReferenceID(
                    self.logic.TARGET_BOUNDS_ROI_REFERENCE_ROLE,
                    roiNode.GetID(),
                )
            if (
                targetBounds is not None
                and not self._planningConstraintWarning
            ):
                self._enforceTrajectoryBounds(trajectoryNode)

        summary = None
        if trajectoryNode:
            try:
                summary = self.logic.getTrajectorySummary(trajectoryNode)
            except ValueError:
                summary = None
        pointCount = summary["definedPointCount"] if summary else 0
        isLocked = bool(trajectoryNode and trajectoryNode.GetLocked())
        if trajectoryNode:
            trajectoryNode.SetSelectable(True)
            displayNode = trajectoryNode.GetDisplayNode()
            if displayNode:
                displayNode.SetPointLabelsVisibility(True)
                displayNode.SetPropertiesLabelVisibility(True)
        self._updatingPlanningUI = True
        try:
            self.ui.placeTrajectoryButton.enabled = bool(
                targetRecord
                and targetBounds is not None
                and trajectoryNode
                and not isLocked
                and pointCount < 2
            )
            self.ui.placeTrajectoryButton.text = (
                _("Place Both Points")
                if pointCount == 0
                else _("Place Target")
                if pointCount == 1
                else _("Trajectory Complete")
            )
            self.ui.undoTrajectoryPointButton.enabled = bool(
                trajectoryNode and pointCount > 0 and not isLocked
            )
            self.ui.resetTrajectoryButton.enabled = bool(
                trajectoryNode and pointCount > 0
            )
            self.ui.deleteTrajectoryButton.enabled = bool(
                trajectoryNode
                and self.logic.isDentobotTrajectoryNode(trajectoryNode)
            )
            canLock = bool(
                targetRecord
                and trajectoryNode
                and summary
                and summary["isValid"]
                and not self._planningConstraintWarning
            )
            self.ui.lockTrajectoryButton.enabled = bool(canLock or isLocked)
            self.ui.lockTrajectoryButton.checked = isLocked
            self.ui.lockTrajectoryButton.text = (
                _("Unlock Entry / Target Pair")
                if isLocked
                else _("Lock Valid Entry / Target Pair")
            )
            if not trajectoryNode:
                lockStatus = _("NO TRAJECTORY SELECTED")
                lockStyle = "color: #666666; font-weight: 600;"
            elif isLocked:
                lockStatus = _(
                    "LOCKED — geometry edits are disabled; point selection and "
                    "linked-view navigation remain available."
                )
                lockStyle = "color: #207227; font-weight: 700;"
            else:
                lockStatus = _(
                    "EDITABLE — Entry and Target can be placed or corrected."
                )
                lockStyle = "color: #b36b00; font-weight: 700;"
            self.ui.trajectoryLockStatusLabel.text = lockStatus
            self.ui.trajectoryLockStatusLabel.styleSheet = lockStyle
        finally:
            self._updatingPlanningUI = False
        self._updateTrajectoryPlacementModeControls()
        self._updateTrajectoryDetails(trajectoryNode)
        self._updatePlanningStatus(
            segmentationNode,
            targetRecord,
            trajectoryNode,
        )
        self._updateTrajectoryVerificationControls()
        self._updateAssistedTrajectoryControls()

    def _updateTrajectoryDetails(self, trajectoryNode) -> None:
        if not trajectoryNode or not self.logic:
            self.ui.trajectoryEntryValueLabel.text = _("--")
            self.ui.trajectoryTargetValueLabel.text = _("--")
            self.ui.trajectoryLengthValueLabel.text = _("--")
            return
        try:
            summary = self.logic.getTrajectorySummary(trajectoryNode)
        except ValueError as exc:
            self.ui.trajectoryEntryValueLabel.text = _("--")
            self.ui.trajectoryTargetValueLabel.text = _("--")
            self.ui.trajectoryLengthValueLabel.text = _("--")
            self.ui.planningStatusLabel.text = str(exc)
            self.ui.planningStatusLabel.styleSheet = "color: #b00020;"
            return

        self.ui.trajectoryEntryValueLabel.text = (
            self.logic.formatRasPoint(summary["entryRas"])
            if summary["entryRas"]
            else _("--")
        )
        self.ui.trajectoryTargetValueLabel.text = (
            self.logic.formatRasPoint(summary["targetRas"])
            if summary["targetRas"]
            else _("--")
        )
        self.ui.trajectoryLengthValueLabel.text = (
            f'{summary["lengthMm"]:.3f} mm'
            if summary["lengthMm"] is not None
            else _("--")
        )

    def _updatePlanningStatus(
        self,
        segmentationNode,
        targetRecord: dict | None,
        trajectoryNode,
    ) -> None:
        if not self._targetToothRecordsById:
            self.ui.planningStatusLabel.text = _(
                "The selected segmentation contains no recognized whole-tooth "
                "segments."
            )
            self.ui.planningStatusLabel.styleSheet = "color: #b00020;"
            return
        if not targetRecord:
            self.ui.planningStatusLabel.text = _(
                "Choose one tooth label as the draft planning target."
            )
            self.ui.planningStatusLabel.styleSheet = "color: #b36b00;"
            return
        if self._planningConstraintWarning:
            self.ui.planningStatusLabel.text = self._planningConstraintWarning
            self.ui.planningStatusLabel.styleSheet = "color: #b00020;"
            return
        if not trajectoryNode or not self.logic:
            self.ui.planningStatusLabel.text = _(
                "Target tooth saved. Create or select a trajectory line."
            )
            self.ui.planningStatusLabel.styleSheet = "color: #1f5f99;"
            return
        try:
            summary = self.logic.getTrajectorySummary(trajectoryNode)
        except ValueError as exc:
            self.ui.planningStatusLabel.text = str(exc)
            self.ui.planningStatusLabel.styleSheet = "color: #b00020;"
            return

        pointCount = summary["definedPointCount"]
        if pointCount == 0:
            message = _("Place the Entry point, followed by the Target point.")
            style = "color: #1f5f99;"
        elif pointCount == 1:
            message = _("Entry is defined. Place the Target point.")
            style = "color: #1f5f99;"
        elif not summary["isValid"]:
            message = _(
                "Entry and Target coincide. Move one point to define a "
                "non-zero trajectory."
            )
            style = "color: #b00020;"
        else:
            reviewState = self.logic.getSegmentationReviewState(
                segmentationNode
            )
            message = (
                _(
                    "Draft inputs complete for %1. Segmentation review state: "
                    "%2. This is not an approved drilling plan."
                )
                .replace("%1", targetRecord["displayName"])
                .replace("%2", reviewState)
            )
            style = "color: #207227;"
        self.ui.planningStatusLabel.text = message
        self.ui.planningStatusLabel.styleSheet = style

    @staticmethod
    def _workflowImpactText(impact: dict) -> str:
        return ", ".join(
            _("%1 (%2 object(s))")
            .replace("%1", str(stage["stage"]))
            .replace("%2", str(len(stage["nodeIds"])))
            for stage in impact.get("stages", [])
        )

    def _refreshAfterPlanningDownstreamDeletion(self) -> None:
        if not self._parameterNode:
            return
        self._bindTemplateSupportBoundaryNode(
            self._parameterNode.templateSupportBoundaryCurve
        )
        self._bindTemplateInsertionDirectionNode(
            self._parameterNode.templateInsertionDirection
        )
        self._updateTargetDocking()
        self._updateTemplateModeling()
        self._updateTemplateGuide()
        self._updateTemplateFinalization()
        self._updatePlanning()

    def _confirmAndDeleteTrajectoryDependents(
        self,
        trajectoryNode,
        actionText: str,
        *,
        impact: dict | None = None,
    ) -> bool:
        if not self.logic or not trajectoryNode:
            return True
        impact = impact or self.logic.getTrajectoryDependentWorkflowImpact(
            trajectoryNode
        )
        if not impact["hasDependents"]:
            if impact.get("flags", {}).get("selectedGuideReference"):
                try:
                    self.logic.deleteTrajectoryDependentWorkflow(
                        trajectoryNode,
                        impact=impact,
                    )
                except (RuntimeError, ValueError) as exc:
                    slicer.util.errorDisplay(str(exc))
                    return False
            return True
        trajectoryName = trajectoryNode.GetName() or _("Unnamed trajectory")
        if not slicer.util.confirmYesNoDisplay(
            _(
                "The trajectory “%1” already has downstream geometry. To %2, "
                "DENTOBOT must delete: %3. The authoritative segmentation, "
                "target tooth, target bounds, support-tooth choices, and other "
                "trajectories will be preserved. Continue?"
            ).replace("%1", trajectoryName).replace(
                "%2", actionText
            ).replace(
                "%3", self._workflowImpactText(impact)
            ),
            windowTitle=_("Backtrack dependent workflow"),
        ):
            return False
        try:
            result = self.logic.deleteTrajectoryDependentWorkflow(
                trajectoryNode,
                impact=impact,
            )
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))
            return False
        logging.info(
            "Backtracked %s before trajectory change; removed %d dependent nodes",
            trajectoryNode.GetID(),
            len(result["removedNodeIds"]),
        )
        self._refreshAfterPlanningDownstreamDeletion()
        return True

    def _confirmAndDeleteActivePlanningDownstream(
        self,
        actionText: str,
    ) -> bool:
        if not self.logic:
            return True
        impact = self.logic.getActivePlanningDownstreamImpact()
        if not impact["hasDependents"]:
            if impact.get("flags", {}).get("selectedGuideReference"):
                try:
                    self.logic.deleteActivePlanningDownstreamWorkflow(
                        impact=impact
                    )
                except (RuntimeError, ValueError) as exc:
                    slicer.util.errorDisplay(str(exc))
                    return False
            return True
        if not slicer.util.confirmYesNoDisplay(
            _(
                "The current target has downstream geometry. To %1, DENTOBOT "
                "must delete: %2. The authoritative segmentation, tooth masks, "
                "target bounds, and trajectory nodes will be preserved. Continue?"
            ).replace("%1", actionText).replace(
                "%2", self._workflowImpactText(impact)
            ),
            windowTitle=_("Backtrack current target workflow"),
        ):
            return False
        try:
            result = self.logic.deleteActivePlanningDownstreamWorkflow(
                impact=impact
            )
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))
            return False
        logging.info(
            "Backtracked active planning target; removed %d dependent nodes",
            len(result["removedNodeIds"]),
        )
        self._refreshAfterPlanningDownstreamDeletion()
        return True

    def onTargetToothChanged(self, index: int) -> None:
        if (
            self._updatingPlanningUI
            or self._restoringTrajectoryAssociation
            or not self._parameterNode
            or not self.logic
        ):
            return
        self._restoreAssistedTrajectoryFocus(updateUi=False)
        segmentId = (
            str(self.ui.targetToothComboBox.itemData(index))
            if index >= 0 and self.ui.targetToothComboBox.itemData(index)
            else ""
        )
        previousTargetId = self._parameterNode.targetToothSegmentId
        if segmentId != previousTargetId:
            if not self._confirmAndDeleteActivePlanningDownstream(
                _("switch the active target tooth")
            ):
                previousIndex = self.ui.targetToothComboBox.findData(
                    previousTargetId
                )
                self._updatingPlanningUI = True
                try:
                    self.ui.targetToothComboBox.setCurrentIndex(
                        previousIndex if previousIndex >= 0 else 0
                    )
                finally:
                    self._updatingPlanningUI = False
                return
            self._parameterNode.templateSupportToothSegmentIdsJson = "[]"

        trajectoryNode = self._parameterNode.trajectoryLine
        trajectoryAssociation = None
        trajectoryAssociationInvalid = False
        if trajectoryNode:
            self._validTrajectoryPointsByNodeId.pop(
                trajectoryNode.GetID(),
                None,
            )
            try:
                trajectoryAssociation = (
                    self.logic.getTrajectoryTargetAssociation(trajectoryNode)
                )
            except ValueError as exc:
                slicer.util.errorDisplay(str(exc))
                trajectoryAssociationInvalid = True

        retainedTrajectory = None if trajectoryAssociationInvalid else trajectoryNode
        if trajectoryAssociation and not trajectoryAssociationInvalid:
            associatedTargetId = trajectoryAssociation["targetRecord"][
                "segmentId"
            ]
            if associatedTargetId != segmentId:
                retainedTrajectory = None
        elif trajectoryNode and segmentId:
            try:
                self.logic.configureTrajectoryTarget(
                    trajectoryNode,
                    self._parameterNode.teethSegmentation,
                    segmentId,
                )
            except ValueError as exc:
                slicer.util.errorDisplay(str(exc))
                retainedTrajectory = None
        elif trajectoryNode and not segmentId:
            retainedTrajectory = None

        previousRoi = self._parameterNode.targetToothBoundsRoi
        if (
            segmentId != previousTargetId
            and previousRoi
            and previousRoi.GetDisplayNode()
        ):
            previousRoi.GetDisplayNode().SetVisibility(False)
        self._planningConstraintWarning = ""
        self._restoringTrajectoryAssociation = True
        wasModifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.targetToothSegmentId = segmentId
            self._parameterNode.trajectoryLine = retainedTrajectory
            if segmentId != previousTargetId:
                self._parameterNode.targetToothBoundsRoi = None
        finally:
            self._parameterNode.EndModify(wasModifying)
            self._restoringTrajectoryAssociation = False
        self._updatePlanning()
        self._updateTemplateModeling()
        self._applyTargetPriorityHighlight()

    def onTrajectorySelectionChanged(self, trajectoryNode) -> None:
        if (
            self._restoringTrajectoryAssociation
            or not self._parameterNode
            or not self.logic
        ):
            return
        previousNode = self._planningTrajectoryNode
        previousNodeId = previousNode.GetID() if previousNode else None
        selectedNodeId = trajectoryNode.GetID() if trajectoryNode else None
        association = None
        if trajectoryNode:
            try:
                association = self.logic.getTrajectoryTargetAssociation(
                    trajectoryNode
                )
            except ValueError as exc:
                slicer.util.errorDisplay(str(exc))
                self._restoringTrajectoryAssociation = True
                try:
                    self._parameterNode.trajectoryLine = previousNode
                    self.ui.trajectorySelector.setCurrentNode(previousNode)
                finally:
                    self._restoringTrajectoryAssociation = False
                return

        previousSegmentation = self._parameterNode.teethSegmentation
        previousTargetId = self._parameterNode.targetToothSegmentId
        if association:
            associatedSegmentation = association["segmentationNode"]
            associatedTargetId = association["targetRecord"]["segmentId"]
            if (
                previousSegmentation is not associatedSegmentation
                or previousTargetId != associatedTargetId
            ) and not self._confirmAndDeleteActivePlanningDownstream(
                _("switch to a trajectory for another target tooth")
            ):
                self._restoringTrajectoryAssociation = True
                try:
                    self._parameterNode.trajectoryLine = previousNode
                    self.ui.trajectorySelector.setCurrentNode(previousNode)
                finally:
                    self._restoringTrajectoryAssociation = False
                return
        self._restoringTrajectoryAssociation = True
        wasModifying = self._parameterNode.StartModify()
        try:
            self._parameterNode.trajectoryLine = trajectoryNode
            if association:
                associatedSegmentation = association["segmentationNode"]
                associatedTargetId = association["targetRecord"]["segmentId"]
                associatedRoi = association["targetBoundsRoi"]
                if (
                    previousSegmentation is not associatedSegmentation
                    or previousTargetId != associatedTargetId
                ):
                    self._parameterNode.templateSupportToothSegmentIdsJson = "[]"
                oldRoi = self._parameterNode.targetToothBoundsRoi
                if (
                    oldRoi
                    and oldRoi is not associatedRoi
                    and oldRoi.GetDisplayNode()
                ):
                    oldRoi.GetDisplayNode().SetVisibility(False)
                self._parameterNode.teethSegmentation = associatedSegmentation
                self._parameterNode.targetToothSegmentId = associatedTargetId
                self._parameterNode.targetToothBoundsRoi = associatedRoi
            elif trajectoryNode and self._parameterNode.targetToothSegmentId:
                self.logic.configureTrajectoryTarget(
                    trajectoryNode,
                    self._parameterNode.teethSegmentation,
                    self._parameterNode.targetToothSegmentId,
                )
        finally:
            self._parameterNode.EndModify(wasModifying)
            self._restoringTrajectoryAssociation = False

        if previousNodeId and previousNodeId != selectedNodeId:
            self._validTrajectoryPointsByNodeId.pop(previousNodeId, None)
        self._planningConstraintWarning = ""
        self._bindSegmentationReviewNode(self._parameterNode.teethSegmentation)
        self._updateSegmentationReview()
        self._bindPlanningTrajectoryNode(trajectoryNode)
        self._updatePlanning()
        self._updateTemplateModeling()
        self._updateTemplateGuide()
        if trajectoryNode:
            self._presentSelectedTrajectory(trajectoryNode)

    def onCreateTrajectory(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            targetRecord = self.logic.validateTargetTooth(
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
            )
            trajectoryNode = self.logic.createTrajectoryNode(
                f'DENTO Trajectory FDI {targetRecord["fdiNumber"]}'
            )
            self.logic.enableAutomaticTrajectoryName(trajectoryNode)
            self.logic.configureTrajectoryTarget(
                trajectoryNode,
                self._parameterNode.teethSegmentation,
                targetRecord["segmentId"],
            )
            self._parameterNode.trajectoryLine = trajectoryNode
            self._bindPlanningTrajectoryNode(trajectoryNode)
            self._updatePlanning()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onPlaceTrajectory(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            self.logic.validateTargetTooth(
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
            )
            self.logic.configureTrajectoryTarget(
                self._parameterNode.trajectoryLine,
                self._parameterNode.teethSegmentation,
                self._parameterNode.targetToothSegmentId,
            )
            self.logic.startTrajectoryPlacement(
                self._parameterNode.trajectoryLine
            )
            self._updatePlanning()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onUndoTrajectoryPoint(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        trajectoryNode = self._parameterNode.trajectoryLine
        if not trajectoryNode:
            return
        try:
            if trajectoryNode.GetLocked():
                raise ValueError(
                    _("Unlock the trajectory before removing a point.")
                )
            summary = self.logic.getTrajectorySummary(trajectoryNode)
            if summary["definedPointCount"] == 0:
                raise ValueError(_("The trajectory has no point to undo."))
            if not self._confirmAndDeleteTrajectoryDependents(
                trajectoryNode,
                _("remove its last Entry/Target point"),
            ):
                return
            self.logic.stopTrajectoryPlacement()
            trajectoryNode.RemoveNthControlPoint(
                summary["definedPointCount"] - 1
            )
            self._validTrajectoryPointsByNodeId.pop(
                trajectoryNode.GetID(),
                None,
            )
            self._planningConstraintWarning = ""
            self._enforceTrajectoryBounds(trajectoryNode)
            self._updatePlanning()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onResetTrajectory(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        trajectoryNode = self._parameterNode.trajectoryLine
        if not trajectoryNode:
            return
        summary = self.logic.getTrajectorySummary(trajectoryNode)
        if summary["definedPointCount"] == 0:
            return
        impact = self.logic.getTrajectoryDependentWorkflowImpact(
            trajectoryNode
        )
        if impact["hasDependents"]:
            if not self._confirmAndDeleteTrajectoryDependents(
                trajectoryNode,
                _("clear both Entry and Target points"),
                impact=impact,
            ):
                return
        elif not slicer.util.confirmYesNoDisplay(
                _(
                    "Clear both Entry and Target points from the selected "
                    "trajectory? This cannot be undone after the scene is saved."
                ),
                windowTitle=_("Clear Step 4A trajectory"),
            ):
            return
        self.logic.stopTrajectoryPlacement()
        trajectoryNode.SetLocked(False)
        trajectoryNode.RemoveAllControlPoints()
        self._validTrajectoryPointsByNodeId.pop(
            trajectoryNode.GetID(),
            None,
        )
        self._planningConstraintWarning = ""
        self._updatePlanning()

    def onDeleteTrajectory(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        trajectoryNode = self._parameterNode.trajectoryLine
        try:
            self.logic.validateDentobotTrajectoryForDeletion(trajectoryNode)
        except ValueError as exc:
            slicer.util.errorDisplay(str(exc))
            return
        trajectoryName = trajectoryNode.GetName() or _("Unnamed trajectory")
        impact = self.logic.getTrajectoryDependentWorkflowImpact(
            trajectoryNode
        )
        if impact["hasDependents"]:
            if not self._confirmAndDeleteTrajectoryDependents(
                trajectoryNode,
                _("permanently delete it"),
                impact=impact,
            ):
                return
        elif not slicer.util.confirmYesNoDisplay(
                _(
                    "Permanently delete the selected trajectory “%1”? The target "
                    "tooth, source segmentation, and target bounds will be kept. "
                    "This cannot be undone after the scene is saved."
                ).replace("%1", trajectoryName),
                windowTitle=_("Delete Step 4A trajectory"),
            ):
            return

        trajectoryId = trajectoryNode.GetID()
        self._bindPlanningTrajectoryNode(None)
        try:
            removal = self.logic.deleteTrajectoryNode(trajectoryNode)
        except (RuntimeError, ValueError) as exc:
            self._bindPlanningTrajectoryNode(trajectoryNode)
            slicer.util.errorDisplay(str(exc))
            return
        self._parameterNode.trajectoryLine = None
        self._validTrajectoryPointsByNodeId.pop(trajectoryId, None)
        self._planningConstraintWarning = ""
        logging.info(
            "Deleted DENTOBOT Step 4A trajectory %s and %d owned auxiliary nodes",
            removal["nodeId"],
            len(removal["auxiliaryNodeIds"]),
        )
        self._updatePlanning()

    def onTrajectoryLockToggled(self, locked: bool) -> None:
        if (
            self._updatingPlanningUI
            or not self._parameterNode
            or not self.logic
        ):
            return
        trajectoryNode = self._parameterNode.trajectoryLine
        if not trajectoryNode:
            return
        if locked:
            try:
                summary = self.logic.getTrajectorySummary(trajectoryNode)
                boundsReport = self.logic.getTrajectoryBoundsReport(
                    trajectoryNode,
                    self._parameterNode.teethSegmentation,
                    self._parameterNode.targetToothSegmentId,
                )
                if (
                    not summary["isValid"]
                    or summary["definedPointCount"] != 2
                    or not boundsReport["allDefinedPointsWithinBounds"]
                ):
                    raise ValueError(
                        _(
                            "A complete non-zero Entry/Target pair inside the "
                            "target bounds is required before locking."
                        )
                    )
                self.logic.stopTrajectoryPlacement()
                trajectoryNode.SetLocked(True)
            except (RuntimeError, ValueError) as exc:
                self._updatingPlanningUI = True
                try:
                    self.ui.lockTrajectoryButton.checked = False
                finally:
                    self._updatingPlanningUI = False
                slicer.util.errorDisplay(str(exc))
        else:
            if not self._confirmAndDeleteTrajectoryDependents(
                trajectoryNode,
                _("unlock and revise its Entry/Target points"),
            ):
                self._updatingPlanningUI = True
                try:
                    self.ui.lockTrajectoryButton.checked = True
                finally:
                    self._updatingPlanningUI = False
                trajectoryNode.SetLocked(True)
                return
            trajectoryNode.SetLocked(False)
        self._updatePlanning()

    def _clearTemplateModeling(self) -> None:
        if not hasattr(self, "ui"):
            return
        self._updatingTemplateUI = True
        try:
            self._templateSupportRecordsById = {}
            self._templateStatusWarning = ""
            self.ui.templateTargetToothValueLabel.text = _("--")
            self._updateLineageBadge(
                self.ui.templateModelingLineageLabel,
                None,
                _("Step 4A → Step 4B → Step 5A"),
                _(
                    "Target lineage: create a Step 4A trajectory to assign a color."
                ),
            )
            self.ui.templateSupportTeethListWidget.clear()
            self.ui.templateSupportTeethListWidget.enabled = False
            self._rebuildTemplateSupportArchSelector(None, [], [])
            self.ui.draftTemplateSupportModelSelector.setCurrentNode(None)
            self.ui.templateSupportBoundaryCurveSelector.setCurrentNode(None)
            self.ui.templateSupportBoundaryPlaneSelector.setCurrentNode(None)
            self.ui.visibleTemplateSupportModelSelector.setCurrentNode(None)
            self.ui.templateSupportDirectionValueLabel.text = _(
                "Select a complete target trajectory in Step 4A."
            )
            self.ui.flipTemplateSupportDirectionButton.checked = False
            self.ui.flipTemplateSupportDirectionButton.enabled = False
            self.ui.createDraftTemplateSupportModelButton.enabled = False
            self.ui.createDraftTemplateSupportModelButton.text = _(
                "Create Draft Support Model"
            )
            self.ui.createDraftTemplateSupportModelButton.toolTip = _(
                "Create one draft model from the reviewed target and checked "
                "support teeth. Source segmentation surfaces are not modified."
            )
            self.ui.reviewSegmentationForTemplateButton.visible = False
            self.ui.reviewSegmentationForTemplateButton.enabled = False
            self.ui.deleteDraftTemplateSupportModelButton.enabled = False
            self.ui.focusTemplateSupportButton.enabled = False
            self.ui.frameTemplateSupportButton.enabled = False
            self.ui.restoreTemplateSupportFocusButton.enabled = False
            self.ui.createTemplateSupportBoundaryButton.enabled = False
            self.ui.createTemplateSupportPlaneButton.enabled = False
            self.ui.generateTemplateSupportBoundaryFromPlaneButton.enabled = False
            self.ui.generateVisibleTemplateSupportModelButton.enabled = False
            self.ui.deleteTemplateSupportSelectionButton.enabled = False
            self.ui.templateModelingStatusLabel.text = _(
                "Select a reviewed dental segmentation and target tooth."
            )
            self.ui.templateModelingStatusLabel.styleSheet = "color: #b36b00;"
            self.ui.templateSupportSurfaceStatusLabel.text = _(
                "Create the full support model, then draw a closed boundary "
                "around the erupted support surfaces."
            )
            self.ui.templateSupportSurfaceStatusLabel.styleSheet = "color: #b36b00;"
        finally:
            self._updatingTemplateUI = False

    def _bindTemplateSupportBoundaryNode(self, curveNode) -> None:
        """Observe the editable visible-support boundary exactly once."""

        if curveNode is self._templateSupportBoundaryNode:
            return
        if self._templateSupportBoundaryNode:
            self.removeObserver(
                self._templateSupportBoundaryNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onTemplateSupportBoundaryModified,
            )
        self._templateSupportBoundaryNode = curveNode
        if curveNode:
            self.addObserver(
                curveNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onTemplateSupportBoundaryModified,
            )

    def _bindTemplateInsertionDirectionNode(self, lineNode) -> None:
        """Observe the editable Approach-to-Seat insertion line exactly once."""

        if lineNode is self._templateInsertionDirectionNode:
            return
        if self._templateInsertionDirectionNode:
            self.removeObserver(
                self._templateInsertionDirectionNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onTemplateInsertionDirectionModified,
            )
        self._templateInsertionDirectionNode = lineNode
        if lineNode:
            self.addObserver(
                lineNode,
                vtk.vtkCommand.ModifiedEvent,
                self._onTemplateInsertionDirectionModified,
            )

    def _invalidateTemplateUndercutDownstream(self, reason: str) -> bool:
        if not self._parameterNode or not self.logic:
            return False
        changed = self.logic.markTemplateUndercutOutputsStale(
            self._parameterNode.templateUndercutSurfaceModel,
            self._parameterNode.templateUndercutBlockoutModel,
            reason,
        )
        changed = self.logic.markPatientContactShellStale(
            self._parameterNode.patientContactShellModel,
            reason,
        ) or changed
        changed = self.logic.markFinalPrintableTemplateStale(
            self._parameterNode.finalPrintableTemplateModel,
            reason,
        ) or changed
        changed = self.logic.markFinalizedTemplateShellStale(
            self._parameterNode.finalizedTemplateShellModel,
            reason,
        ) or changed
        return changed

    def _onTemplateInsertionDirectionModified(self, caller=None, event=None) -> None:
        del event
        if (
            self._restoringTemplateInsertionDirection
            or not self._parameterNode
            or caller is not self._parameterNode.templateInsertionDirection
        ):
            return
        self._invalidateTemplateUndercutDownstream(
            _("The template insertion direction changed."),
        )
        qt.QTimer.singleShot(0, self._updateTemplateGuide)

    def _bindSelectedGuideTrajectoryNodes(self, trajectoryNodes: list) -> None:
        oldIds = {node.GetID() for node in self._guideTrajectoryObserverNodes if node}
        newIds = {node.GetID() for node in trajectoryNodes if node}
        if oldIds == newIds:
            return
        for node in self._guideTrajectoryObserverNodes:
            self.removeObserver(
                node,
                vtk.vtkCommand.ModifiedEvent,
                self._onSelectedGuideTrajectoryModified,
            )
        self._guideTrajectoryObserverNodes = list(trajectoryNodes)
        for node in self._guideTrajectoryObserverNodes:
            self.addObserver(
                node,
                vtk.vtkCommand.ModifiedEvent,
                self._onSelectedGuideTrajectoryModified,
            )

    def _onSelectedGuideTrajectoryModified(self, caller=None, event=None) -> None:
        del event
        if not self._parameterNode or caller not in self._guideTrajectoryObserverNodes:
            return
        reason = _("A source guide trajectory changed.")
        try:
            dockingSummary = self.logic.getTargetDockingAssemblySummary(
                self._parameterNode.targetDockingAssemblyModel
            )
            if caller in dockingSummary["trajectories"]:
                trajectoryGeometry = []
                for node in dockingSummary["trajectories"]:
                    trajectorySummary = self.logic.getTrajectorySummary(node)
                    trajectoryGeometry.append(
                        {
                            "entryRas": [
                                float(value)
                                for value in trajectorySummary["entryRas"]
                            ],
                            "targetRas": [
                                float(value)
                                for value in trajectorySummary["targetRas"]
                            ],
                        }
                    )
                currentGeometryJson = json.dumps(
                    trajectoryGeometry,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                if (
                    currentGeometryJson
                    == dockingSummary["trajectoryGeometryJson"]
                ):
                    # Markups also emits ModifiedEvent for scene restoration,
                    # lock state, labels, and display-only changes. Those are
                    # not trajectory geometry changes and must not invalidate
                    # the Step 4B/4C/5B chain.
                    return
                self.logic.markTargetDockingAssemblyStale(
                    self._parameterNode.targetDockingAssemblyModel,
                    reason,
                )
        except (RuntimeError, ValueError, json.JSONDecodeError):
            pass
        self.logic.markFinalPrintableTemplateStale(
            self._parameterNode.finalPrintableTemplateModel,
            reason,
        )
        qt.QTimer.singleShot(0, self._updateTargetDocking)
        qt.QTimer.singleShot(0, self._updateTemplateGuide)

    def _invalidateTemplateSupportSurfaceDownstream(self, reason: str) -> bool:
        if not self._parameterNode or not self.logic:
            return False
        changed = self.logic.markVisibleTemplateSupportModelStale(
            self._parameterNode.visibleTemplateSupportModel,
            reason,
        )
        changed = self.logic.markTemplateUndercutOutputsStale(
            self._parameterNode.templateUndercutSurfaceModel,
            self._parameterNode.templateUndercutBlockoutModel,
            reason,
        ) or changed
        changed = self.logic.markPatientContactShellStale(
            self._parameterNode.patientContactShellModel,
            reason,
        ) or changed
        changed = self.logic.markFinalPrintableTemplateStale(
            self._parameterNode.finalPrintableTemplateModel,
            reason,
        ) or changed
        changed = self.logic.markResearchTemplateModelsStale(
            self._parameterNode.researchTemplateShellModel,
            self._parameterNode.researchTemplateSleeveModel,
            reason,
        ) or changed
        changed = self.logic.markFinalizedTemplateShellStale(
            self._parameterNode.finalizedTemplateShellModel,
            reason,
        ) or changed
        return changed

    def _onTemplateSupportBoundaryModified(self, caller=None, event=None) -> None:
        del event
        if (
            self._restoringTemplateSupportBoundary
            or not self._parameterNode
            or caller is not self._parameterNode.templateSupportBoundaryCurve
        ):
            return
        previewModel = self._parameterNode.visibleTemplateSupportModel
        if self.logic.isVisibleTemplateSupportModelNode(previewModel):
            try:
                previewSummary = self.logic.getVisibleTemplateSupportModelSummary(
                    previewModel
                )
                if (
                    previewSummary["boundary"] is caller
                    and self.logic.templateSupportBoundaryMatchesGeometryJson(
                        caller,
                        previewSummary["boundaryGeometryJson"],
                    )
                ):
                    # Ignore non-geometric Markups modifications emitted while
                    # restoring a scene or changing display/lock state.
                    return
            except (RuntimeError, ValueError, json.JSONDecodeError):
                pass
        self._invalidateTemplateSupportSurfaceDownstream(
            _("The visible support boundary changed."),
        )
        qt.QTimer.singleShot(0, self._updateTemplateModeling)

    def _markCurrentDraftTemplateModelStale(self, reason: str) -> bool:
        if not self._parameterNode or not self.logic:
            return False
        changed = self.logic.markDraftTemplateSupportModelStale(
            self._parameterNode.draftTemplateSupportModel,
            reason,
        )
        changed = self.logic.markTargetDockingAssemblyStale(
            self._parameterNode.targetDockingAssemblyModel,
            reason,
        ) or changed
        return self._invalidateTemplateSupportSurfaceDownstream(reason) or changed

    def _selectedTemplateSupportSegmentIds(self) -> list[str]:
        selectedIds = []
        listWidget = self.ui.templateSupportTeethListWidget
        for itemIndex in range(listWidget.count):
            item = listWidget.item(itemIndex)
            segmentId = item.data(qt.Qt.UserRole)
            if segmentId and item.checkState() == qt.Qt.Checked:
                selectedIds.append(str(segmentId))
        return selectedIds

    def _startTemplateSupportBoundaryFocus(self) -> None:
        """Temporarily show only the tooth masks used by the support boundary."""

        if not self._parameterNode or not self.logic:
            raise RuntimeError(_("DENTOWorkflow is not ready for boundary placement."))
        self._restoreTemplateSupportBoundaryFocus(updateUi=False)
        contextModels = [
            self._parameterNode.draftTemplateSupportModel,
            self._parameterNode.visibleTemplateSupportModel,
        ]
        self._templateSupportBoundaryFocusState = (
            self.logic.applyTemplateSupportBoundaryFocus(
                self._parameterNode.teethSegmentation,
                self._parameterNode.draftTemplateSupportModel,
                contextModels=contextModels,
            )
        )
        self._syncSegmentationDisplayControls()
        self.ui.restoreTemplateSupportFocusButton.enabled = True

    def onFocusTemplateSupport(self) -> None:
        try:
            self._startTemplateSupportBoundaryFocus()
            self.onFrameTemplateSupport()
        except (RuntimeError, ValueError) as exc:
            self._restoreTemplateSupportBoundaryFocus(updateUi=False)
            slicer.util.errorDisplay(str(exc))

    def onFrameTemplateSupport(self) -> None:
        if not self._parameterNode:
            return
        modelNode = self._parameterNode.draftTemplateSupportModel
        if not modelNode or not modelNode.IsA("vtkMRMLModelNode"):
            slicer.util.errorDisplay(
                _("Create or select the Step 4B draft support model first.")
            )
            return
        bounds = [0.0] * 6
        modelNode.GetRASBounds(bounds)
        try:
            self._frameRasBoundsInViews(bounds)
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onRestoreTemplateSupportFocus(self) -> None:
        self._restoreTemplateSupportBoundaryFocus(updateUi=True)

    def _restoreTemplateSupportBoundaryFocus(self, updateUi: bool = True) -> None:
        """Restore the exact segmentation/model display state saved for Step 5A."""

        state = self._templateSupportBoundaryFocusState
        self._templateSupportBoundaryFocusState = None
        if not state or not self.logic:
            if hasattr(self, "ui"):
                self.ui.restoreTemplateSupportFocusButton.enabled = False
            return
        self.logic.restoreTemplateSupportBoundaryFocus(state)
        if hasattr(self, "ui"):
            self.ui.restoreTemplateSupportFocusButton.enabled = False
        if (
            updateUi
            and not self._isCleaningUp
            and hasattr(self, "ui")
            and self._reviewSegmentationNode
        ):
            self._syncSegmentationDisplayControls()

    def _updateTemplateModeling(self) -> None:
        if self._updatingTemplateUI:
            return
        if not self._parameterNode or not self.logic:
            self._clearTemplateModeling()
            return

        segmentationNode = self._parameterNode.teethSegmentation
        targetSegmentId = self._parameterNode.targetToothSegmentId
        targetRecord = self._targetToothRecordsById.get(targetSegmentId)
        modelNode = self._parameterNode.draftTemplateSupportModel
        self.logic.refreshWorkflowLineageColors()
        persistedSelectionError = ""
        archSelectionWarning = ""
        try:
            persistedSupportIds = self.logic.decodeTemplateSupportSegmentIds(
                self._parameterNode.templateSupportToothSegmentIdsJson
            )
        except ValueError as exc:
            persistedSupportIds = []
            persistedSelectionError = str(exc)

        targetFdi = str(targetRecord.get("fdiNumber") or "") if targetRecord else ""
        targetArch = self.logic.dentalArchForFdi(targetFdi)
        sameArchRecords = [
            record
            for record in self._targetToothRecordsById.values()
            if self.logic.dentalArchForFdi(record.get("fdiNumber") or "")
            == targetArch
        ] if targetArch else []
        sameArchIds = {record["segmentId"] for record in sameArchRecords}
        removedOpposingArchIds = [
            segmentId
            for segmentId in persistedSupportIds
            if segmentId in self._targetToothRecordsById
            and segmentId not in sameArchIds
        ]
        if removedOpposingArchIds:
            persistedSupportIds = [
                segmentId
                for segmentId in persistedSupportIds
                if segmentId not in removedOpposingArchIds
            ]
            archSelectionWarning = _(
                "Opposing-jaw teeth were removed from the saved support "
                "selection because supports must share the target arch."
            )
            self._updatingTemplateUI = True
            try:
                self._parameterNode.templateSupportToothSegmentIdsJson = (
                    self.logic.encodeTemplateSupportSegmentIds(
                        persistedSupportIds
                    )
                )
            finally:
                self._updatingTemplateUI = False

        invalidSupportIds = [
            segmentId
            for segmentId in persistedSupportIds
            if (
                segmentId == targetSegmentId
                or segmentId not in self._targetToothRecordsById
            )
        ]
        availableRecords = [
            record
            for record in sameArchRecords
            if record["segmentId"] != targetSegmentId
        ]
        archOrder = {
            fdiNumber: index
            for index, fdiNumber in enumerate(
                sum((list(row) for row in self._templateSupportArchRows(targetFdi)), [])
            )
        }
        availableRecords.sort(
            key=lambda record: archOrder.get(
                str(record.get("fdiNumber") or ""),
                999,
            )
        )
        self._templateSupportRecordsById = {
            record["segmentId"]: record for record in availableRecords
        }

        self._updatingTemplateUI = True
        try:
            self.ui.templateTargetToothValueLabel.text = (
                targetRecord["displayName"] if targetRecord else _("--")
            )
            listWidget = self.ui.templateSupportTeethListWidget
            listWidget.clear()
            for record in availableRecords:
                item = qt.QListWidgetItem(record["displayName"])
                item.setData(qt.Qt.UserRole, record["segmentId"])
                item.setToolTip(
                    _("Source label: %1").replace(
                        "%1",
                        record["sourceName"],
                    )
                )
                item.setCheckState(
                    qt.Qt.Checked
                    if record["segmentId"] in persistedSupportIds
                    else qt.Qt.Unchecked
                )
                listWidget.addItem(item)
            listWidget.enabled = bool(targetRecord and availableRecords)
            self._rebuildTemplateSupportArchSelector(
                targetRecord,
                availableRecords,
                persistedSupportIds,
            )
            if self.ui.draftTemplateSupportModelSelector.currentNode() is not modelNode:
                self.ui.draftTemplateSupportModelSelector.setCurrentNode(
                    modelNode
                )
        finally:
            self._updatingTemplateUI = False

        lineageNode = self._lineageSourceNode(
            (
                modelNode,
                self._parameterNode.trajectoryLine,
                self._parameterNode.targetToothBoundsRoi,
            ),
            targetSegmentId,
        )
        self._updateLineageBadge(
            self.ui.templateModelingLineageLabel,
            lineageNode,
            _("Step 4A → Step 4B → Step 5A"),
            _(
                "Target lineage: create a Step 4A trajectory to assign a color."
            ),
        )
        self._updateNodeSelectorLineageSwatches(
            self.ui.draftTemplateSupportModelSelector,
            self.logic.isDraftTemplateSupportModelNode,
        )

        selectedSupportIds = self._selectedTemplateSupportSegmentIds()
        modelSummary = None
        modelError = ""
        if modelNode:
            try:
                modelSummary = self.logic.getDraftTemplateSupportModelSummary(
                    modelNode
                )
            except ValueError as exc:
                modelError = str(exc)

        if modelSummary:
            automaticSelectionStaleReason = _(
                "Current target or support-tooth selection differs."
            )
            selectionDiffers = bool(
                modelSummary["sourceSegmentation"] is not segmentationNode
                or modelSummary["targetSegmentId"] != targetSegmentId
                or set(modelSummary["supportSegmentIds"])
                != set(persistedSupportIds)
            )
            if selectionDiffers:
                self.logic.markDraftTemplateSupportModelStale(
                    modelNode,
                    automaticSelectionStaleReason,
                )
                modelSummary = self.logic.getDraftTemplateSupportModelSummary(
                    modelNode
                )
            elif (
                modelSummary["geometryState"] == "Stale"
                and modelSummary["staleReason"] == automaticSelectionStaleReason
            ):
                # A scene-load UI refresh can transiently expose an empty list.
                # The persisted IDs and model provenance are authoritative; if
                # they agree again, clear only this automatically-created stale
                # state. Never clear content/edit staleness here.
                modelNode.SetAttribute("DENTOBOT.GeometryState", "Current")
                modelNode.SetAttribute("DENTOBOT.StaleReason", None)
                modelSummary = self.logic.getDraftTemplateSupportModelSummary(
                    modelNode
                )

        reviewState = (
            self.logic.getSegmentationReviewState(segmentationNode)
            if segmentationNode
            else ""
        )
        canCreate = bool(
            segmentationNode
            and targetRecord
            and selectedSupportIds
            and reviewState == "Reviewed"
            and not persistedSelectionError
            and not invalidSupportIds
            and not modelError
        )
        self.ui.createDraftTemplateSupportModelButton.enabled = canCreate
        self.ui.createDraftTemplateSupportModelButton.text = (
            _("Update Draft Support Model")
            if modelSummary
            else _("Create Draft Support Model")
        )
        needsReview = bool(segmentationNode and reviewState != "Reviewed")
        self.ui.reviewSegmentationForTemplateButton.visible = needsReview
        self.ui.reviewSegmentationForTemplateButton.enabled = needsReview
        self.ui.reviewSegmentationForTemplateButton.text = (
            _("Open Segmentation Review (%1)").replace(
                "%1",
                reviewState or _("Unreviewed"),
            )
        )
        if needsReview:
            self.ui.createDraftTemplateSupportModelButton.toolTip = _(
                "Blocked because the authoritative segmentation is %1. "
                "Open Segmentation Review, inspect it, and explicitly set "
                "Review state to Reviewed."
            ).replace("%1", reviewState or _("Unreviewed"))
        else:
            self.ui.createDraftTemplateSupportModelButton.toolTip = _(
                "Create or explicitly update one draft model from the target "
                "and all checked support teeth. Source segmentation surfaces "
                "are not modified."
            )
        self.ui.deleteDraftTemplateSupportModelButton.enabled = bool(
            modelNode
            and self.logic.isDraftTemplateSupportModelNode(modelNode)
        )
        hasSupportModel = bool(
            modelNode
            and self.logic.isDraftTemplateSupportModelNode(modelNode)
        )
        self.ui.focusTemplateSupportButton.enabled = hasSupportModel
        self.ui.frameTemplateSupportButton.enabled = hasSupportModel
        self.ui.restoreTemplateSupportFocusButton.enabled = bool(
            self._templateSupportBoundaryFocusState
        )

        if not segmentationNode:
            message = _("Select the authoritative dental segmentation.")
            style = "color: #b36b00;"
        elif not targetRecord:
            message = _("Select a target tooth in Step 4A.")
            style = "color: #b36b00;"
        elif persistedSelectionError:
            message = persistedSelectionError
            style = "color: #b00020;"
        elif invalidSupportIds:
            message = _(
                "The saved support selection contains unavailable or invalid "
                "whole-tooth segments: %1"
            ).replace("%1", ", ".join(invalidSupportIds))
            style = "color: #b00020;"
        elif archSelectionWarning:
            message = archSelectionWarning
            style = "color: #b36b00;"
        elif self._templateStatusWarning:
            message = self._templateStatusWarning
            style = "color: #b36b00;"
        elif not availableRecords:
            message = _(
                "No additional whole-tooth segments are available as supports."
            )
            style = "color: #b00020;"
        elif reviewState != "Reviewed":
            message = (
                _(
                    "Blocked: this segmentation is %1. Your %2 checked support "
                    "teeth are valid and preserved. Select Open Segmentation "
                    "Review, inspect the result, and set Review state to "
                    "Reviewed before creating derived template geometry."
                )
                .replace("%1", reviewState or _("Unreviewed"))
                .replace("%2", str(len(selectedSupportIds)))
            )
            style = "color: #b36b00;"
        elif not selectedSupportIds:
            message = _(
                "Click one or more available teeth in the same-jaw arch map. "
                "The highlighted target tooth is always included and cannot "
                "be toggled."
            )
            style = "color: #1f5f99;"
        elif modelError:
            message = modelError
            style = "color: #b00020;"
        elif modelSummary and modelSummary["geometryState"] == "Current":
            message = (
                _(
                    "Draft model is current for %1 manually selected support "
                    "teeth (%2 points, %3 cells)."
                )
                .replace("%1", str(len(selectedSupportIds)))
                .replace("%2", str(modelSummary["pointCount"]))
                .replace("%3", str(modelSummary["cellCount"]))
            )
            style = "color: #207227;"
        elif modelSummary:
            reason = modelSummary["staleReason"] or _(
                "The source selection changed."
            )
            message = (
                _("Draft model is stale: %1 Select Update to regenerate it.")
                .replace("%1", reason)
            )
            style = "color: #b36b00;"
        else:
            message = (
                _("Ready to create a draft model from the target and %1 support teeth.")
                .replace("%1", str(len(selectedSupportIds)))
            )
            style = "color: #1f5f99;"

        self.ui.templateModelingStatusLabel.text = message
        self.ui.templateModelingStatusLabel.styleSheet = style
        self._updateVisibleTemplateSupportSurfaceControls(modelSummary)

    def onReviewSegmentationForTemplate(self) -> None:
        """Reveal the authoritative review gate without approving it implicitly."""

        if not self._parameterNode or not self.logic:
            return
        segmentationNode = self._parameterNode.teethSegmentation
        if not segmentationNode:
            slicer.util.errorDisplay(
                _("Select the authoritative dental segmentation first.")
            )
            return
        if self.ui.reviewSegmentationSelector.currentNode() is not segmentationNode:
            self.ui.reviewSegmentationSelector.setCurrentNode(segmentationNode)
        self.ui.templateModelingCollapsibleButton.collapsed = True
        self.ui.segmentationReviewCollapsibleButton.collapsed = False

        def focusReviewState() -> None:
            self.ui.reviewStateComboBox.setFocus(qt.Qt.OtherFocusReason)
            ancestor = self.ui.reviewStateComboBox.parent()
            while ancestor:
                if ancestor.inherits("QScrollArea"):
                    ancestor.ensureWidgetVisible(
                        self.ui.reviewStateComboBox,
                        20,
                        20,
                    )
                    break
                ancestor = ancestor.parent()

        qt.QTimer.singleShot(0, focusReviewState)

    def _updateVisibleTemplateSupportSurfaceControls(
        self,
        sourceSummary: dict | None,
    ) -> None:
        if not self._parameterNode or not self.logic:
            return
        sourceModel = self._parameterNode.draftTemplateSupportModel
        curveNode = self._parameterNode.templateSupportBoundaryCurve
        planeNode = self._parameterNode.templateSupportBoundaryPlane
        previewModel = self._parameterNode.visibleTemplateSupportModel
        directionTrajectory = self._parameterNode.trajectoryLine
        reverseDirection = bool(
            self._parameterNode.templateSupportDirectionReversed
        )
        spacing = float(self._parameterNode.templateSupportCurveSamplingSpacingMm)
        terminalCoveragePercent = float(
            self._parameterNode.templateTerminalSupportCoveragePercent
        )

        self._updatingTemplateUI = True
        try:
            if self.ui.templateSupportBoundaryCurveSelector.currentNode() is not curveNode:
                self.ui.templateSupportBoundaryCurveSelector.setCurrentNode(curveNode)
            if self.ui.templateSupportBoundaryPlaneSelector.currentNode() is not planeNode:
                self.ui.templateSupportBoundaryPlaneSelector.setCurrentNode(planeNode)
            if self.ui.visibleTemplateSupportModelSelector.currentNode() is not previewModel:
                self.ui.visibleTemplateSupportModelSelector.setCurrentNode(previewModel)
            self.ui.flipTemplateSupportDirectionButton.checked = reverseDirection
        finally:
            self._updatingTemplateUI = False

        directionSummary = None
        directionError = ""
        if sourceModel:
            try:
                directionSummary = self.logic.resolveTemplateSupportTrajectoryDirection(
                    sourceModel,
                    directionTrajectory,
                    reverseDirection=reverseDirection,
                )
            except (RuntimeError, ValueError) as exc:
                directionError = str(exc)
        else:
            directionError = _("Create the full support-anatomy model first.")
        self._updatingTemplateUI = True
        try:
            self.ui.flipTemplateSupportDirectionButton.enabled = bool(
                directionSummary
            )
            if directionSummary and reverseDirection:
                self.ui.templateSupportDirectionValueLabel.text = _(
                    "Override active: Target → Entry points toward the roots; "
                    "the opposite selects the crown side on every tooth."
                )
            elif directionSummary:
                self.ui.templateSupportDirectionValueLabel.text = _(
                    "Automatic: Entry → Target points toward the roots; the "
                    "opposite selects the crown side on every tooth."
                )
            else:
                self.ui.templateSupportDirectionValueLabel.text = directionError
        finally:
            self._updatingTemplateUI = False

        curveError = ""
        curveGeometryJson = ""
        if curveNode:
            try:
                self.logic.validateTemplateSupportBoundary(sourceModel, curveNode)
                curveGeometryJson = self.logic.templateSupportBoundaryGeometryJson(
                    curveNode
                )
            except (RuntimeError, ValueError) as exc:
                curveError = str(exc)

        planeError = ""
        if planeNode:
            try:
                self.logic.validateTemplateSupportBoundaryPlane(
                    sourceModel,
                    planeNode,
                    directionTrajectory,
                )
                if (
                    directionSummary
                    and planeNode.GetAttribute("DENTOBOT.DirectionGeometryJson")
                    != directionSummary["directionGeometryJson"]
                ):
                    raise ValueError(
                        _(
                            "The target trajectory or polarity changed. Reset "
                            "the insertion-aligned support plane."
                        )
                    )
                if not math.isclose(
                    float(
                        planeNode.GetAttribute("DENTOBOT.DepthFromEntryMm")
                        or "nan"
                    ),
                    float(self._parameterNode.templateSupportPlaneDepthMm),
                    rel_tol=0.0,
                    abs_tol=1e-8,
                ):
                    raise ValueError(
                        _("The support-plane depth changed. Reset the support plane.")
                    )
                if not math.isclose(
                    float(
                        planeNode.GetAttribute("DENTOBOT.CrownCapPercent")
                        or "nan"
                    ),
                    float(self._parameterNode.templateSupportCrownCapPercent),
                    rel_tol=0.0,
                    abs_tol=1e-8,
                ):
                    raise ValueError(
                        _(
                            "The crown-cap tilt fit changed. Reset the support plane."
                        )
                    )
            except (RuntimeError, ValueError) as exc:
                planeError = str(exc)

        previewSummary = None
        previewError = ""
        if previewModel:
            try:
                previewSummary = self.logic.getVisibleTemplateSupportModelSummary(
                    previewModel
                )
            except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
                previewError = str(exc)

        if previewSummary:
            staleReason = ""
            if previewSummary["sourceModel"] is not sourceModel:
                staleReason = _("The selected full support model changed.")
            elif previewSummary["boundary"] is not curveNode:
                staleReason = _("The selected visible support boundary changed.")
            elif not sourceSummary or sourceSummary["geometryState"] != "Current":
                staleReason = _("The full support-anatomy model is stale.")
            elif previewSummary["sourceModelUpdatedUtc"] != (
                sourceModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            ):
                staleReason = _("The full support-anatomy geometry was updated.")
            elif curveGeometryJson and not self.logic.templateSupportBoundaryMatchesGeometryJson(
                curveNode,
                previewSummary["boundaryGeometryJson"],
            ):
                staleReason = _("The visible support boundary geometry changed.")
            elif previewSummary["selectionMode"] != "TrajectoryDirection":
                staleReason = _(
                    "This legacy preview used area-based side selection."
                )
            elif not directionSummary:
                staleReason = directionError
            elif previewSummary["directionTrajectory"] is not directionTrajectory:
                staleReason = _("The target trajectory used for direction changed.")
            elif (
                previewSummary["directionGeometryJson"]
                != directionSummary["directionGeometryJson"]
            ):
                staleReason = _("The target trajectory points or polarity changed.")
            elif previewSummary["directionReversed"] != reverseDirection:
                staleReason = _("The crown/root direction polarity changed.")
            elif not math.isclose(
                previewSummary["samplingSpacingMm"],
                spacing,
                rel_tol=0.0,
                abs_tol=1e-9,
            ):
                staleReason = _("The boundary sampling spacing changed.")
            elif not math.isclose(
                previewSummary["terminalSupportCoveragePercent"],
                terminalCoveragePercent,
                rel_tol=0.0,
                abs_tol=1e-9,
            ):
                staleReason = _("The terminal support-tooth coverage changed.")
            if staleReason:
                self._invalidateTemplateSupportSurfaceDownstream(staleReason)
                previewSummary = self.logic.getVisibleTemplateSupportModelSummary(
                    previewModel
                )
            elif (
                previewSummary["geometryState"] == "Stale"
                and previewSummary["staleReason"]
                in {
                    _(
                        "The support-plane depth or crown-cap tilt fit changed; "
                        "regenerate the boundary and preview."
                    ),
                    _("The visible support boundary changed."),
                }
                and not planeError
            ):
                # A scene-load valueChanged signal used to mark the preview
                # stale even when the saved plane, curve, source model,
                # trajectory, polarity, and processing parameters all still
                # matched. Restore only this known no-op state after every
                # provenance comparison above has succeeded.
                previewModel.SetAttribute("DENTOBOT.GeometryState", "Current")
                previewModel.SetAttribute("DENTOBOT.StaleReason", None)
                previewSummary = self.logic.getVisibleTemplateSupportModelSummary(
                    previewModel
                )

        sourceCurrent = bool(
            sourceSummary and sourceSummary["geometryState"] == "Current"
        )
        curveComplete = bool(curveNode and not curveError and curveGeometryJson)
        planeCurrent = bool(planeNode and not planeError and directionSummary)
        self.ui.createTemplateSupportPlaneButton.enabled = bool(
            sourceCurrent and directionSummary
        )
        self.ui.generateTemplateSupportBoundaryFromPlaneButton.enabled = bool(
            sourceCurrent and planeCurrent and not previewError
        )
        self.ui.createTemplateSupportBoundaryButton.enabled = sourceCurrent
        self.ui.generateVisibleTemplateSupportModelButton.enabled = bool(
            sourceCurrent
            and curveComplete
            and directionSummary
            and not previewError
        )
        self.ui.deleteTemplateSupportSelectionButton.enabled = bool(
            self.logic.isTemplateSupportBoundaryNode(curveNode)
            or self.logic.isTemplateSupportBoundaryPlaneNode(planeNode)
            or self.logic.isVisibleTemplateSupportModelNode(previewModel)
        )

        if not sourceCurrent:
            message = _("Create or update the full support-anatomy model first.")
            style = "color: #b36b00;"
        elif planeError:
            message = planeError
            style = "color: #b36b00;"
        elif curveError:
            message = curveError
            style = "color: #b36b00;"
        elif directionError:
            message = directionError
            style = "color: #b36b00;"
        elif self._templateSupportBoundaryFocusState:
            message = _(
                "Boundary focus is active: only the target and checked support-"
                "tooth masks are shown. Place the closed loop, right-click to "
                "finish, then generate the preview; the prior display will be "
                "restored automatically."
            )
            style = "color: #1f5f99;"
        elif planeNode and not curveNode:
            message = _(
                "The insertion-aligned support plane is ready. Adjust only "
                "Plane depth from Entry, then select Generate Boundary + "
                "Preview. The generated curve remains editable."
            )
            style = "color: #1f5f99;"
        elif not curveNode:
            message = _(
                "Create the insertion-aligned support plane for the automatic "
                "workflow, or use Manual: Draw / Redraw Boundary as a fallback."
            )
            style = "color: #1f5f99;"
        elif not curveComplete:
            message = _(
                "Place at least three points directly on the orange support "
                "surfaces, then right-click to finish the closed loop."
            )
            style = "color: #1f5f99;"
        elif previewError:
            message = previewError
            style = "color: #b00020;"
        elif previewSummary and previewSummary["geometryState"] == "Current":
            selectedToothCount = int(
                previewSummary["metrics"].get(
                    "selectedToothCount",
                    previewSummary["metrics"].get("surfaceRegionCount", 0),
                )
            )
            sourceToothCount = int(
                previewSummary["metrics"].get(
                    "sourceToothCount",
                    previewSummary["metrics"].get("sourceSurfaceRegionCount", 0),
                )
            )
            omittedToothCount = int(
                previewSummary["metrics"].get(
                    "omittedToothCount",
                    max(0, sourceToothCount - selectedToothCount),
                )
            )
            ignoredIslandCount = int(
                previewSummary["metrics"].get("ignoredSourceIslandCount", 0)
            )
            ambiguousCount = sum(
                1
                for item in previewSummary["metrics"].get("toothMetrics", [])
                if item.get("directionSelectionAmbiguous")
            )
            terminalSupport = previewSummary["metrics"].get(
                "terminalSupport",
                {},
            )
            message = (
                _(
                    "Visible support preview is current (%1 points, %2 cells; "
                    "%3 of %4 selected teeth included by trajectory direction)."
                )
                .replace("%1", str(previewSummary["pointCount"]))
                .replace("%2", str(previewSummary["cellCount"]))
                .replace("%3", str(selectedToothCount))
                .replace("%4", str(sourceToothCount))
            )
            warnings = []
            if omittedToothCount:
                warnings.append(
                    _("%1 intended tooth/teeth were not mapped.").replace(
                        "%1",
                        str(omittedToothCount),
                    )
                )
            if ignoredIslandCount:
                warnings.append(
                    _(
                        "%1 extra disconnected mesh island(s) were ignored "
                        "inside their source tooth segments."
                    ).replace("%1", str(ignoredIslandCount))
                )
            if ambiguousCount:
                warnings.append(
                    _("%1 tooth side choice(s) were directionally close.").replace(
                        "%1",
                        str(ambiguousCount),
                    )
                )
            if terminalSupport.get("applied"):
                message += " " + (
                    _(
                        "Inward %1% coverage was applied to terminal support "
                        "tooth/teeth %2."
                    )
                    .replace(
                        "%1",
                        f"{previewSummary['terminalSupportCoveragePercent']:.0f}",
                    )
                    .replace(
                        "%2",
                        ", ".join(
                            terminalSupport.get(
                                "clippedTerminalSegmentIds",
                                [],
                            )
                        ),
                    )
                )
            if warnings:
                message += _(
                    " %1 Inspect the orange preview and review the segmentation "
                    "if ignored islands are unexpected."
                ).replace("%1", " ".join(warnings))
                style = "color: #b36b00;"
            else:
                style = "color: #207227;"
        elif previewSummary:
            message = _("Visible support preview is stale: %1").replace(
                "%1",
                previewSummary["staleReason"] or _("regeneration required"),
            )
            style = "color: #b36b00;"
        else:
            message = _(
                "Boundary and target-trajectory direction are ready. Generate "
                "the preview, then inspect the orange crown-side patches."
            )
            style = "color: #1f5f99;"
        self.ui.templateSupportSurfaceStatusLabel.text = message
        self.ui.templateSupportSurfaceStatusLabel.styleSheet = style

        self._updateNodeSelectorLineageSwatches(
            self.ui.visibleTemplateSupportModelSelector,
            self.logic.isVisibleTemplateSupportModelNode,
        )

    def onTemplateSupportToothItemChanged(self, item) -> None:
        del item
        if (
            self._updatingTemplateUI
            or not self._parameterNode
            or not self.logic
        ):
            return
        self._restoreTemplateSupportBoundaryFocus()
        selectedSupportIds = self._selectedTemplateSupportSegmentIds()
        serializedIds = self.logic.encodeTemplateSupportSegmentIds(
            selectedSupportIds
        )
        if (
            serializedIds
            != self._parameterNode.templateSupportToothSegmentIdsJson
        ):
            self._markCurrentDraftTemplateModelStale(
                _("Support-tooth selection changed.")
            )
            self._updatingTemplateUI = True
            try:
                self._parameterNode.templateSupportToothSegmentIdsJson = (
                    serializedIds
                )
            finally:
                self._updatingTemplateUI = False
        self._updateTemplateModeling()

    def onDraftTemplateSupportModelSelectionChanged(self, modelNode) -> None:
        if self._updatingTemplateUI or not self._parameterNode:
            return
        currentNode = self._parameterNode.draftTemplateSupportModel
        currentNodeId = currentNode.GetID() if currentNode else None
        selectedNodeId = modelNode.GetID() if modelNode else None
        if currentNodeId != selectedNodeId:
            self._parameterNode.draftTemplateSupportModel = modelNode
            self.logic.markTargetDockingAssemblyStale(
                self._parameterNode.targetDockingAssemblyModel,
                _("The Step 4B support-anatomy draft was regenerated."),
            )
        self._updateTemplateModeling()

    def onCreateDraftTemplateSupportModel(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        self._restoreTemplateSupportBoundaryFocus()
        try:
            supportSegmentIds = self._selectedTemplateSupportSegmentIds()
            modelNode, details = (
                self.logic.createOrUpdateDraftTemplateSupportModel(
                    self._parameterNode.teethSegmentation,
                    self._parameterNode.targetToothSegmentId,
                    supportSegmentIds,
                    self._parameterNode.draftTemplateSupportModel,
                )
            )
            self._parameterNode.templateSupportToothSegmentIdsJson = (
                self.logic.encodeTemplateSupportSegmentIds(
                    supportSegmentIds
                )
            )
            self._parameterNode.draftTemplateSupportModel = modelNode
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The full support-anatomy model was regenerated."),
            )
            self._templateStatusWarning = ""
            logging.info(
                "DENTOBOT Step 4B draft model %s created/updated with "
                "%d support teeth, %d points, and %d cells",
                modelNode.GetID(),
                details["supportCount"],
                details["pointCount"],
                details["cellCount"],
            )
            self._updateTemplateModeling()
        except (RuntimeError, ValueError) as exc:
            self._templateStatusWarning = str(exc)
            self.ui.templateModelingStatusLabel.text = str(exc)
            self.ui.templateModelingStatusLabel.styleSheet = "color: #b00020;"
            slicer.util.errorDisplay(str(exc))

    def onDeleteDraftTemplateSupportModel(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        modelNode = self._parameterNode.draftTemplateSupportModel
        try:
            self.logic.validateDraftTemplateSupportModelForDeletion(modelNode)
        except ValueError as exc:
            slicer.util.errorDisplay(str(exc))
            return
        modelName = modelNode.GetName() or _("Unnamed draft support model")
        if not slicer.util.confirmYesNoDisplay(
            _(
                "Permanently delete the draft support-anatomy model “%1”? "
                "The source segmentation, target tooth, and checked support "
                "teeth will be kept so a new draft can be created. Its visible "
                "support boundary and preview will also be removed. This "
                "cannot be undone after the scene is saved."
            ).replace("%1", modelName),
            windowTitle=_("Delete Step 4B draft support model"),
        ):
            return

        self._restoreTemplateSupportBoundaryFocus()
        try:
            if (
                self._parameterNode.templateSupportBoundaryCurve
                or self._parameterNode.templateSupportBoundaryPlane
                or self._parameterNode.visibleTemplateSupportModel
            ):
                if self.logic.isPatientContactShellModelNode(
                    self._parameterNode.patientContactShellModel
                ):
                    self._deleteFinalPrintableTemplateCascade()
                    self.logic.deletePatientContactShell(
                        self._parameterNode.patientContactShellModel
                    )
                self.logic.deleteTemplateUndercutWorkflow(
                    self._parameterNode.templateInsertionDirection,
                    self._parameterNode.templateUndercutSurfaceModel,
                    self._parameterNode.templateUndercutBlockoutModel,
                )
                self._bindTemplateInsertionDirectionNode(None)
                self.logic.deleteTemplateSupportSelection(
                    self._parameterNode.templateSupportBoundaryCurve,
                    self._parameterNode.visibleTemplateSupportModel,
                    self._parameterNode.templateSupportBoundaryPlane,
                )
                self._bindTemplateSupportBoundaryNode(None)
            removal = self.logic.deleteDraftTemplateSupportModel(modelNode)
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))
            return
        self._parameterNode.draftTemplateSupportModel = None
        self._templateStatusWarning = ""
        logging.info(
            "Deleted DENTOBOT Step 4B draft model %s and %d owned auxiliary nodes",
            removal["nodeId"],
            len(removal["auxiliaryNodeIds"]),
        )
        self._updateTemplateModeling()

    def onTemplateSupportBoundarySelectionChanged(self, curveNode) -> None:
        if self._updatingTemplateUI or not self._parameterNode:
            return
        currentNode = self._parameterNode.templateSupportBoundaryCurve
        if (currentNode.GetID() if currentNode else None) != (
            curveNode.GetID() if curveNode else None
        ):
            self._restoreTemplateSupportBoundaryFocus()
            self._parameterNode.templateSupportBoundaryCurve = curveNode
            self._bindTemplateSupportBoundaryNode(curveNode)
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The selected visible support boundary changed."),
            )
        self._updateTemplateModeling()

    def onVisibleTemplateSupportModelSelectionChanged(self, modelNode) -> None:
        if self._updatingTemplateUI or not self._parameterNode:
            return
        currentNode = self._parameterNode.visibleTemplateSupportModel
        if (currentNode.GetID() if currentNode else None) != (
            modelNode.GetID() if modelNode else None
        ):
            self._restoreTemplateSupportBoundaryFocus()
            self._parameterNode.visibleTemplateSupportModel = modelNode
        self._updateTemplateModeling()

    def onTemplateSupportSurfaceParameterChanged(self, *args) -> None:
        del args
        if self._updatingTemplateUI or not self._parameterNode:
            return
        spacing = float(self.ui.templateSupportCurveSamplingSpacingSpinBox.value)
        terminalCoveragePercent = float(
            self.ui.templateTerminalSupportCoverageSpinBox.value
        )
        changed = bool(
            not math.isclose(
                self._parameterNode.templateSupportCurveSamplingSpacingMm,
                spacing,
                rel_tol=0.0,
                abs_tol=1e-9,
            )
            or not math.isclose(
                self._parameterNode.templateTerminalSupportCoveragePercent,
                terminalCoveragePercent,
                rel_tol=0.0,
                abs_tol=1e-9,
            )
        )
        self._parameterNode.templateSupportCurveSamplingSpacingMm = spacing
        self._parameterNode.templateTerminalSupportCoveragePercent = (
            terminalCoveragePercent
        )
        if changed:
            self._invalidateTemplateSupportSurfaceDownstream(
                _("Visible support-surface processing parameters changed."),
            )
        self._updateTemplateModeling()

    def onTemplateSupportDirectionReversedToggled(self, checked: bool) -> None:
        if self._updatingTemplateUI or not self._parameterNode:
            return
        reversedValue = bool(checked)
        if (
            self._parameterNode.templateSupportDirectionReversed
            != reversedValue
        ):
            self._parameterNode.templateSupportDirectionReversed = reversedValue
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The target-trajectory crown/root polarity changed."),
            )
            if self._parameterNode.templateSupportBoundaryPlane and self.logic:
                try:
                    self.logic.createOrUpdateTemplateSupportBoundaryPlane(
                        self._parameterNode.draftTemplateSupportModel,
                        self._parameterNode.trajectoryLine,
                        reverseDirection=reversedValue,
                        depthFromEntryMm=(
                            self._parameterNode.templateSupportPlaneDepthMm
                        ),
                        crownCapPercent=(
                            self._parameterNode.templateSupportCrownCapPercent
                        ),
                        planeNode=(
                            self._parameterNode.templateSupportBoundaryPlane
                        ),
                    )
                except (RuntimeError, ValueError) as exc:
                    self.ui.templateSupportSurfaceStatusLabel.text = str(exc)
                    self.ui.templateSupportSurfaceStatusLabel.styleSheet = (
                        "color: #b00020;"
                    )
        self._updateTemplateModeling()

    def onCreateTemplateSupportBoundary(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        curveNode = self._parameterNode.templateSupportBoundaryCurve
        if curveNode and curveNode.GetNumberOfDefinedControlPoints() >= 3:
            if not slicer.util.confirmYesNoDisplay(
                _(
                    "Redraw the visible support boundary? Existing boundary "
                    "points will be cleared and downstream template geometry "
                    "will become stale."
                ),
                windowTitle=_("Redraw visible support boundary"),
            ):
                return
        try:
            curveNode = self.logic.createOrResetTemplateSupportBoundary(
                self._parameterNode.draftTemplateSupportModel,
                curveNode,
            )
            self._parameterNode.templateSupportBoundaryCurve = curveNode
            self._bindTemplateSupportBoundaryNode(curveNode)
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The visible support boundary was redrawn."),
            )
            self._startTemplateSupportBoundaryFocus()
            self.logic.startClosedCurvePlacement(curveNode)
            self._updateTemplateModeling()
        except (RuntimeError, ValueError) as exc:
            self._restoreTemplateSupportBoundaryFocus()
            slicer.util.errorDisplay(str(exc))

    def onCreateTemplateSupportPlane(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            planeNode, _geometry = (
                self.logic.createOrUpdateTemplateSupportBoundaryPlane(
                    self._parameterNode.draftTemplateSupportModel,
                    self._parameterNode.trajectoryLine,
                    reverseDirection=(
                        self._parameterNode.templateSupportDirectionReversed
                    ),
                    depthFromEntryMm=(
                        self._parameterNode.templateSupportPlaneDepthMm
                    ),
                    crownCapPercent=(
                        self._parameterNode.templateSupportCrownCapPercent
                    ),
                    planeNode=self._parameterNode.templateSupportBoundaryPlane,
                )
            )
            self._parameterNode.templateSupportBoundaryPlane = planeNode
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The insertion-aligned support plane was created or reset."),
            )
            self._updateTemplateModeling()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onTemplateSupportPlaneDepthChanged(self, value: float) -> None:
        del value
        if self._updatingTemplateUI or not self._parameterNode or not self.logic:
            return
        depth = float(self.ui.templateSupportPlaneDepthSpinBox.value)
        capPercent = float(self.ui.templateSupportCrownCapSpinBox.value)
        self._parameterNode.templateSupportPlaneDepthMm = depth
        self._parameterNode.templateSupportCrownCapPercent = capPercent
        planeNode = self._parameterNode.templateSupportBoundaryPlane
        if not planeNode:
            self._updateTemplateModeling()
            return
        try:
            storedDepth = float(
                planeNode.GetAttribute("DENTOBOT.DepthFromEntryMm") or "nan"
            )
            storedCapPercent = float(
                planeNode.GetAttribute("DENTOBOT.CrownCapPercent") or "nan"
            )
        except ValueError:
            storedDepth = math.nan
            storedCapPercent = math.nan
        if math.isclose(
            storedDepth,
            depth,
            rel_tol=0.0,
            abs_tol=1e-8,
        ) and math.isclose(
            storedCapPercent,
            capPercent,
            rel_tol=0.0,
            abs_tol=1e-8,
        ):
            # Parameter-wrapper restoration can emit valueChanged even though
            # the persisted support plane already has exactly these settings.
            self._updateTemplateModeling()
            return
        try:
            self.logic.createOrUpdateTemplateSupportBoundaryPlane(
                self._parameterNode.draftTemplateSupportModel,
                self._parameterNode.trajectoryLine,
                reverseDirection=(
                    self._parameterNode.templateSupportDirectionReversed
                ),
                depthFromEntryMm=depth,
                crownCapPercent=capPercent,
                planeNode=planeNode,
            )
            self._invalidateTemplateSupportSurfaceDownstream(
                _(
                    "The support-plane depth or crown-cap tilt fit changed; "
                    "regenerate the boundary and preview."
                ),
            )
            self._updateTemplateModeling()
        except (RuntimeError, ValueError) as exc:
            self.ui.templateSupportSurfaceStatusLabel.text = str(exc)
            self.ui.templateSupportSurfaceStatusLabel.styleSheet = "color: #b00020;"

    def onGenerateTemplateSupportBoundaryFromPlane(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        self._restoreTemplateSupportBoundaryFocus()
        self._restoringTemplateSupportBoundary = True
        try:
            curveNode, metrics = (
                self.logic.createOrUpdateTemplateSupportBoundaryFromPlane(
                    self._parameterNode.draftTemplateSupportModel,
                    self._parameterNode.templateSupportBoundaryPlane,
                    self._parameterNode.trajectoryLine,
                    samplingSpacingMm=(
                        self._parameterNode.templateSupportCurveSamplingSpacingMm
                    ),
                    curveNode=self._parameterNode.templateSupportBoundaryCurve,
                )
            )
            self._parameterNode.templateSupportBoundaryCurve = curveNode
            self._bindTemplateSupportBoundaryNode(curveNode)
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The support boundary was regenerated from the support plane."),
            )
            logging.info(
                "Initialized Step 5A support boundary from plane with %d points; "
                "%d of %d selected teeth intersected",
                metrics["outputLoopPointCount"],
                metrics["intersectedToothCount"],
                metrics["sourceToothCount"],
            )
        except (RuntimeError, ValueError) as exc:
            self.ui.templateSupportSurfaceStatusLabel.text = str(exc)
            self.ui.templateSupportSurfaceStatusLabel.styleSheet = "color: #b00020;"
            slicer.util.errorDisplay(str(exc))
            return
        finally:
            self._restoringTemplateSupportBoundary = False
        self._updateTemplateModeling()
        self.onGenerateVisibleTemplateSupportModel()

    def onGenerateVisibleTemplateSupportModel(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        self._restoreTemplateSupportBoundaryFocus()
        try:
            modelNode, metrics = self.logic.createOrUpdateVisibleTemplateSupportModel(
                self._parameterNode.draftTemplateSupportModel,
                self._parameterNode.templateSupportBoundaryCurve,
                directionTrajectory=self._parameterNode.trajectoryLine,
                reverseDirection=(
                    self._parameterNode.templateSupportDirectionReversed
                ),
                samplingSpacingMm=(
                    self._parameterNode.templateSupportCurveSamplingSpacingMm
                ),
                terminalCoveragePercent=(
                    self._parameterNode.templateTerminalSupportCoveragePercent
                ),
                outputModel=self._parameterNode.visibleTemplateSupportModel,
                insertionDirectionNode=(
                    self._parameterNode.templateInsertionDirection
                ),
            )
            self._parameterNode.visibleTemplateSupportModel = modelNode
            insertionDirection = modelNode.GetNodeReference(
                self.logic.TEMPLATE_VISIBLE_SUPPORT_INSERTION_DIRECTION_REFERENCE_ROLE
            )
            self._parameterNode.templateInsertionDirection = insertionDirection
            self._bindTemplateInsertionDirectionNode(insertionDirection)
            self.logic.markTemplateUndercutOutputsStale(
                self._parameterNode.templateUndercutSurfaceModel,
                self._parameterNode.templateUndercutBlockoutModel,
                _("The visible support surface was regenerated."),
            )
            self.logic.markPatientContactShellStale(
                self._parameterNode.patientContactShellModel,
                _("The visible support surface was regenerated."),
            )
            self.logic.markResearchTemplateModelsStale(
                self._parameterNode.researchTemplateShellModel,
                self._parameterNode.researchTemplateSleeveModel,
                _("The visible support surface was regenerated."),
            )
            self.logic.markFinalizedTemplateShellStale(
                self._parameterNode.finalizedTemplateShellModel,
                _("The visible support surface was regenerated."),
            )
            logging.info(
                "Generated visible support surface %s with %d points and %d triangles",
                modelNode.GetID(),
                metrics["pointCount"],
                metrics["triangleCount"],
            )
            self._updateTemplateModeling()
            self._updateTemplateGuide()
            self._updateTemplateFinalization()
        except (RuntimeError, ValueError) as exc:
            self.ui.templateSupportSurfaceStatusLabel.text = str(exc)
            self.ui.templateSupportSurfaceStatusLabel.styleSheet = "color: #b00020;"
            slicer.util.errorDisplay(str(exc))

    def onDeleteTemplateSupportSelection(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        if not slicer.util.confirmYesNoDisplay(
            _(
                "Delete the visible support boundary and its derived preview? "
                "The authoritative segmentation, target/support tooth selection, "
                "and full support-anatomy model will be preserved."
            ),
            windowTitle=_("Delete visible support selection"),
        ):
            return
        self._restoreTemplateSupportBoundaryFocus()
        try:
            self._invalidateTemplateSupportSurfaceDownstream(
                _("The visible support selection was deleted."),
            )
            if self.logic.isPatientContactShellModelNode(
                self._parameterNode.patientContactShellModel
            ):
                self._deleteFinalPrintableTemplateCascade()
                self.logic.deletePatientContactShell(
                    self._parameterNode.patientContactShellModel
                )
            self.logic.deleteTemplateUndercutWorkflow(
                self._parameterNode.templateInsertionDirection,
                self._parameterNode.templateUndercutSurfaceModel,
                self._parameterNode.templateUndercutBlockoutModel,
            )
            self._bindTemplateInsertionDirectionNode(None)
            self.logic.deleteTemplateSupportSelection(
                self._parameterNode.templateSupportBoundaryCurve,
                self._parameterNode.visibleTemplateSupportModel,
                self._parameterNode.templateSupportBoundaryPlane,
            )
            self._bindTemplateSupportBoundaryNode(None)
            self._updateTemplateModeling()
            self._updateTemplateGuide()
            self._updateTemplateFinalization()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def _clearTemplateGuide(self) -> None:
        if not hasattr(self, "ui"):
            return
        self._updatingTemplateGuideUI = True
        try:
            self.ui.templateInsertionDirectionSelector.setCurrentNode(None)
            self.ui.templateUndercutSurfaceModelSelector.setCurrentNode(None)
            self.ui.templateUndercutBlockoutModelSelector.setCurrentNode(None)
            self.ui.patientContactShellModelSelector.setCurrentNode(None)
            self.ui.finalPrintableTemplateModelSelector.setCurrentNode(None)
            self.ui.templateGuideTrajectoriesListWidget.clear()
            self.ui.patientContactShellSourceValueLabel.text = _("--")
            self.ui.createTemplateInsertionDirectionButton.enabled = False
            self.ui.deleteTemplateInsertionDirectionButton.enabled = False
            self.ui.analyzeTemplateUndercutsButton.enabled = False
            self.ui.generateFinalPrintableTemplateButton.enabled = False
            self.ui.deleteFinalPrintableTemplateButton.enabled = False
            self.ui.inspectTemplateFitButton.enabled = False
            self.ui.inspectShellAndGuidesButton.enabled = False
            self.ui.inspectUnifiedTemplateButton.enabled = False
            self.ui.templateDockingFusionStatusLabel.text = _(
                "Generate an undercut-aware patient-contact shell first."
            )
            self.ui.templateDockingFusionStatusLabel.styleSheet = "color: #b36b00;"
            self.ui.generatePatientContactShellButton.enabled = False
            self.ui.deletePatientContactShellButton.enabled = False
            self.ui.patientContactShellStatusLabel.text = _(
                "Generate a current visible support preview in Step 5A first."
            )
            self.ui.patientContactShellStatusLabel.styleSheet = "color: #b36b00;"
            self.ui.templateShellRoiSelector.setCurrentNode(None)
            self.ui.researchTemplateShellModelSelector.setCurrentNode(None)
            self.ui.researchTemplateSleeveModelSelector.setCurrentNode(None)
            self._updateLineageBadge(
                self.ui.templateGuideLineageLabel,
                None,
                _("Step 4A → Step 4B → Step 5A → Step 5B"),
                _(
                    "Inherited lineage: waiting for a colored Step 5A/Step 4A input."
                ),
            )
            self.ui.createTemplateShellRoiButton.enabled = False
            self.ui.deleteTemplateShellRoiButton.enabled = False
            for visibilityCheckBox in (
                self.ui.targetBoundsVisibilityCheckBox,
                self.ui.trajectoryVisibilityCheckBox,
                self.ui.supportModelVisibilityCheckBox,
                self.ui.shellRoiVisibilityCheckBox,
                self.ui.shellModelVisibilityCheckBox,
                self.ui.sleeveModelVisibilityCheckBox,
                self.ui.patientContactShellVisibilityCheckBox,
                self.ui.templateInsertionDirectionVisibilityCheckBox,
                self.ui.templateUndercutVisibilityCheckBox,
                self.ui.templateBlockoutVisibilityCheckBox,
                self.ui.supportBoundaryVisibilityCheckBox,
                self.ui.supportPlaneVisibilityCheckBox,
                self.ui.visibleSupportVisibilityCheckBox,
                self.ui.finalTemplateVisibilityCheckBox,
            ):
                visibilityCheckBox.enabled = False
                visibilityCheckBox.checked = False
            self.ui.generateResearchTemplateButton.enabled = False
            self.ui.deleteResearchTemplateButton.enabled = False
            self.ui.exportResearchTemplateButton.enabled = False
            self.ui.templateGuideStatusLabel.text = _(
                "Create a current Step 4B support draft and Step 5A visible support preview, then lock the trajectory."
            )
            self.ui.templateGuideStatusLabel.styleSheet = "color: #b36b00;"
        finally:
            self._updatingTemplateGuideUI = False

    def _templateGuideParameters(self) -> dict[str, float]:
        if not self._parameterNode:
            return {}
        return {
            "clearanceMm": self._parameterNode.templateShellClearanceMm,
            "thicknessMm": self._parameterNode.templateShellThicknessMm,
            "samplingSpacingMm": self._parameterNode.templateSamplingSpacingMm,
            "channelDiameterMm": self._parameterNode.templateChannelDiameterMm,
            "sleeveOuterDiameterMm": self._parameterNode.templateSleeveOuterDiameterMm,
            "sleeveInnerDiameterMm": self._parameterNode.templateSleeveInnerDiameterMm,
            "sleeveHeightMm": self._parameterNode.templateSleeveHeightMm,
        }

    def _templateGuideVisibilityEntries(self) -> tuple[tuple[object, object], ...]:
        if not self._parameterNode:
            return ()
        return (
            (
                self.ui.targetBoundsVisibilityCheckBox,
                self._parameterNode.targetToothBoundsRoi,
            ),
            (
                self.ui.trajectoryVisibilityCheckBox,
                self._parameterNode.trajectoryLine,
            ),
            (
                self.ui.supportModelVisibilityCheckBox,
                self._parameterNode.draftTemplateSupportModel,
            ),
            (
                self.ui.shellRoiVisibilityCheckBox,
                self._parameterNode.templateShellRoi,
            ),
            (
                self.ui.shellModelVisibilityCheckBox,
                self._parameterNode.researchTemplateShellModel,
            ),
            (
                self.ui.sleeveModelVisibilityCheckBox,
                self._parameterNode.researchTemplateSleeveModel,
            ),
            (
                self.ui.patientContactShellVisibilityCheckBox,
                self._parameterNode.patientContactShellModel,
            ),
            (
                self.ui.templateInsertionDirectionVisibilityCheckBox,
                self._parameterNode.templateInsertionDirection,
            ),
            (
                self.ui.templateUndercutVisibilityCheckBox,
                self._parameterNode.templateUndercutSurfaceModel,
            ),
            (
                self.ui.templateBlockoutVisibilityCheckBox,
                self._parameterNode.templateUndercutBlockoutModel,
            ),
            (
                self.ui.supportBoundaryVisibilityCheckBox,
                self._parameterNode.templateSupportBoundaryCurve,
            ),
            (
                self.ui.supportPlaneVisibilityCheckBox,
                self._parameterNode.templateSupportBoundaryPlane,
            ),
            (
                self.ui.visibleSupportVisibilityCheckBox,
                self._parameterNode.visibleTemplateSupportModel,
            ),
            (
                self.ui.finalTemplateVisibilityCheckBox,
                self._parameterNode.finalPrintableTemplateModel,
            ),
        )

    def _updateTemplateGuideVisibilityControls(self) -> None:
        self._updatingTemplateGuideVisibilityUI = True
        try:
            for checkBox, node in self._templateGuideVisibilityEntries():
                displayNode = node.GetDisplayNode() if node else None
                checkBox.enabled = bool(displayNode)
                checkBox.checked = bool(
                    displayNode and displayNode.GetVisibility()
                )
                color = (
                    self.logic.lineageColorFromNode(node)
                    if self.logic and node
                    else None
                )
                checkBox.styleSheet = (
                    self._lineageStyleSheet(
                        color,
                        borderWidth=6,
                    ).replace("QLabel", "QCheckBox")
                    if color
                    else ""
                )
        finally:
            self._updatingTemplateGuideVisibilityUI = False

    def onTemplateGuideVisibilityChanged(self, *args) -> None:
        del args
        if (
            self._updatingTemplateGuideVisibilityUI
            or self._updatingTemplateGuideUI
        ):
            return
        for checkBox, node in self._templateGuideVisibilityEntries():
            displayNode = node.GetDisplayNode() if node else None
            if displayNode and checkBox.enabled:
                displayNode.SetVisibility(bool(checkBox.checked))
        self._updateTemplateGuideVisibilityControls()

    def _updateTemplateGuideTrajectoryList(self, sourceModel) -> None:
        try:
            included = self.logic.getTargetDockingAssemblySummary(
                self._parameterNode.targetDockingAssemblyModel
            )["trajectories"]
        except (RuntimeError, ValueError):
            try:
                included = self.logic.getEligibleTemplateGuideTrajectories(
                    sourceModel
                )
            except (RuntimeError, ValueError):
                included = []
        self._updatingGuideTrajectorySelectionUI = True
        try:
            self.ui.templateGuideTrajectoriesListWidget.clear()
            for trajectoryNode in included:
                association = self.logic.getTrajectoryTargetAssociation(trajectoryNode)
                targetRecord = association["targetRecord"] if association else {}
                fdiNumber = targetRecord.get("fdiNumber") or "--"
                try:
                    summary = self.logic.getTrajectorySummary(trajectoryNode)
                    ready = bool(
                        summary["isValid"]
                        and summary["definedPointCount"] == 2
                        and trajectoryNode.GetLocked()
                    )
                except ValueError:
                    ready = False
                state = (
                    _("included automatically — approved/locked")
                    if ready
                    else _("included automatically — incomplete or unlocked")
                )
                item = qt.QListWidgetItem(
                    _("FDI %1 — %2 (%3)")
                    .replace("%1", str(fdiNumber))
                    .replace("%2", trajectoryNode.GetName() or _("Unnamed trajectory"))
                    .replace("%3", state)
                )
                item.setData(qt.Qt.UserRole, trajectoryNode.GetID())
                item.setFlags(item.flags() | qt.Qt.ItemIsSelectable)
                if not ready:
                    item.setToolTip(
                        _("Complete and lock this trajectory in Step 4A before building.")
                    )
                self.ui.templateGuideTrajectoriesListWidget.addItem(item)
        finally:
            self._updatingGuideTrajectorySelectionUI = False

    def _selectedTemplateGuideTrajectoryItems(self) -> list[vtkMRMLMarkupsLineNode]:
        selected = []
        listWidget = self.ui.templateGuideTrajectoriesListWidget
        for itemIndex in range(listWidget.count):
            item = listWidget.item(itemIndex)
            if item.checkState() != qt.Qt.Checked:
                continue
            node = slicer.mrmlScene.GetNodeByID(str(item.data(qt.Qt.UserRole)))
            if node:
                selected.append(node)
        return selected

    def _updateFinalPrintableTemplateControls(self, patientShell, sourceModel) -> None:
        targetDockingAssembly = self._parameterNode.targetDockingAssemblyModel
        selectedTrajectories = []
        try:
            targetDockingSummary = self.logic.getTargetDockingAssemblySummary(
                targetDockingAssembly
            )
            selectedTrajectories = targetDockingSummary["trajectories"]
        except (RuntimeError, ValueError, json.JSONDecodeError):
            targetDockingSummary = None
        if sourceModel:
            self._updateTemplateGuideTrajectoryList(sourceModel)
        self._bindSelectedGuideTrajectoryNodes(selectedTrajectories)
        finalModel = self._parameterNode.finalPrintableTemplateModel
        if self.ui.finalPrintableTemplateModelSelector.currentNode() is not finalModel:
            self._updatingTemplateGuideUI = True
            try:
                self.ui.finalPrintableTemplateModelSelector.setCurrentNode(finalModel)
            finally:
                self._updatingTemplateGuideUI = False
        self._updateNodeSelectorLineageSwatches(
            self.ui.finalPrintableTemplateModelSelector,
            self.logic.isFinalPrintableTemplateModelNode,
        )
        inputError = ""
        normalizedParameters = None
        validatedInputs = None
        try:
            normalizedParameters = normalize_docking_parameters(
                outer_diameter_mm=self._parameterNode.templateSleeveOuterDiameterMm,
                inner_diameter_mm=self._parameterNode.templateSleeveInnerDiameterMm,
                height_mm=self._parameterNode.templateSleeveHeightMm,
                clearance_mm=self._parameterNode.templateDockingClearanceMm,
                reinforcement_radial_mm=(
                    self._parameterNode.templateReinforcementRadialMm
                ),
                reinforcement_depth_mm=(
                    self._parameterNode.templateReinforcementDepthMm
                ),
                processing_resolution_mm=self._parameterNode.templateSamplingSpacingMm,
            )
            validatedInputs = self.logic._validateFinalGuideInputs(
                patientShell,
                targetDockingAssembly,
                selectedTrajectories,
                normalizedParameters,
            )
        except (RuntimeError, ValueError) as exc:
            inputError = str(exc)

        finalSummary = None
        outputError = ""
        if finalModel:
            try:
                finalSummary = self.logic.getFinalPrintableTemplateSummary(finalModel)
            except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
                outputError = str(exc)
        if finalSummary and finalSummary["geometryState"] == "Current":
            currentTrajectoryGeometry = [
                {
                    "entryRas": record["entryRas"],
                    "targetRas": record["targetRas"],
                }
                for record in validatedInputs["trajectories"]
            ] if validatedInputs else []
            staleReason = ""
            if inputError:
                staleReason = inputError
            elif finalSummary["patientShell"] is not patientShell:
                staleReason = _("The patient-contact shell changed.")
            elif finalSummary["targetDockingAssembly"] is not targetDockingAssembly:
                staleReason = _("The Step 4C docking assembly changed.")
            elif finalSummary["trajectories"] != selectedTrajectories:
                staleReason = _("The selected guide trajectories changed.")
            elif finalSummary["parametersJson"] != json.dumps(
                normalizedParameters,
                sort_keys=True,
                separators=(",", ":"),
            ):
                staleReason = _("Docking clearance, reinforcement, dimensions, or resolution changed.")
            elif finalSummary["trajectoryGeometryJson"] != json.dumps(
                currentTrajectoryGeometry,
                sort_keys=True,
                separators=(",", ":"),
            ):
                staleReason = _("A source trajectory geometry changed.")
            elif finalSummary["patientShellUpdatedUtc"] != (
                patientShell.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            ):
                staleReason = _("The patient-contact shell was regenerated.")
            elif finalSummary["targetDockingUpdatedUtc"] != (
                targetDockingAssembly.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            ):
                staleReason = _("The Step 4C docking assembly was regenerated.")
            if staleReason:
                self.logic.markFinalPrintableTemplateStale(finalModel, staleReason)
                finalSummary = self.logic.getFinalPrintableTemplateSummary(finalModel)

        buildPreflightError = ""
        try:
            self._completeTemplateBuildPreflight()
        except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
            buildPreflightError = str(exc)

        patientShellCurrent = False
        if patientShell:
            try:
                patientShellCurrent = (
                    self.logic.getPatientContactShellSummary(patientShell)[
                        "geometryState"
                    ]
                    == "Current"
                )
            except (RuntimeError, ValueError, json.JSONDecodeError):
                pass
        finalCurrent = bool(
            finalSummary and finalSummary["geometryState"] == "Current"
        )
        self.ui.generateFinalPrintableTemplateButton.enabled = bool(
            not buildPreflightError and not outputError
        )
        if finalCurrent:
            self.ui.generateFinalPrintableTemplateButton.text = _(
                "Inspect Current Unified Template (No Rebuild)"
            )
        elif patientShellCurrent:
            self.ui.generateFinalPrintableTemplateButton.text = _(
                "Fuse Cached Shell + Guides + 4 Docks"
            )
        else:
            self.ui.generateFinalPrintableTemplateButton.text = _(
                "Build Complete Template (Missing/Stale Stages Only)"
            )
        self.ui.deleteFinalPrintableTemplateButton.enabled = bool(
            self.logic.isFinalPrintableTemplateModelNode(finalModel)
        )
        self.ui.inspectTemplateFitButton.enabled = bool(
            self.logic.isVisibleTemplateSupportModelNode(
                self._parameterNode.visibleTemplateSupportModel
            )
            or self.logic.isTemplateUndercutSurfaceModelNode(
                self._parameterNode.templateUndercutSurfaceModel
            )
            or self.logic.isTemplateUndercutBlockoutModelNode(
                self._parameterNode.templateUndercutBlockoutModel
            )
            or self.logic.isPatientContactShellModelNode(patientShell)
        )
        self.ui.inspectShellAndGuidesButton.enabled = bool(
            self.logic.isPatientContactShellModelNode(patientShell)
        )
        self.ui.inspectUnifiedTemplateButton.enabled = finalCurrent
        if outputError:
            message, style = outputError, "color: #b00020;"
        elif buildPreflightError:
            message, style = buildPreflightError, "color: #b36b00;"
        elif finalCurrent:
            message = (
                _(
                    "Unified template is current (%1 trajectory/trajectories, %2 triangles, "
                    "%3 connected occupied volume(s), four target-frame docks); final verification is required."
                )
                .replace("%1", str(len(finalSummary["trajectories"])))
                .replace("%2", str(finalSummary["metrics"].get("triangleCount", "--")))
                .replace(
                    "%3",
                    str(
                        finalSummary["metrics"].get(
                            "occupiedVolumeRegionCount",
                            "--",
                        )
                    ),
                )
            )
            style = "color: #b36b00;"
        elif patientShellCurrent:
            message = _(
                "Patient shell is cached and current. Build will reuse it and compute "
                "only the trajectory-guide/four-dock fusion that is missing or stale."
            )
            style = "color: #1f5f99;"
        elif finalSummary:
            message = _("Unified template is stale: %1").replace(
                "%1",
                finalSummary["staleReason"] or _("regeneration required"),
            )
            style = "color: #b36b00;"
        else:
            message = _(
                "Inputs are ready. Build will generate only missing or stale blockout, "
                "patient-shell, and unified guide/dock stages."
            )
            style = "color: #1f5f99;"
        self.ui.templateDockingFusionStatusLabel.text = message
        self.ui.templateDockingFusionStatusLabel.styleSheet = style

    def _updateTemplateGuide(self) -> None:
        if self._updatingTemplateGuideUI:
            return
        if not self._parameterNode or not self.logic:
            self._clearTemplateGuide()
            return

        supportModel = self._parameterNode.draftTemplateSupportModel
        visibleSupportModel = self._parameterNode.visibleTemplateSupportModel
        insertionDirection = self._parameterNode.templateInsertionDirection
        if visibleSupportModel:
            try:
                referencedInsertion = (
                    self.logic.getVisibleTemplateSupportModelSummary(
                        visibleSupportModel
                    )["insertionDirection"]
                )
            except (RuntimeError, ValueError, json.JSONDecodeError):
                referencedInsertion = None
            if (
                self.logic.isTemplateInsertionDirectionNode(referencedInsertion)
                and insertionDirection is not referencedInsertion
            ):
                self._updatingTemplateGuideUI = True
                try:
                    self._parameterNode.templateInsertionDirection = referencedInsertion
                    insertionDirection = referencedInsertion
                    self._bindTemplateInsertionDirectionNode(referencedInsertion)
                finally:
                    self._updatingTemplateGuideUI = False
        undercutModel = self._parameterNode.templateUndercutSurfaceModel
        blockoutModel = self._parameterNode.templateUndercutBlockoutModel
        patientContactShell = self._parameterNode.patientContactShellModel
        trajectoryNode = self._parameterNode.trajectoryLine
        roiNode = self._parameterNode.templateShellRoi
        shellModel = self._parameterNode.researchTemplateShellModel
        sleeveModel = self._parameterNode.researchTemplateSleeveModel
        rejectedRoiWarning = ""
        if roiNode and not self.logic.isTemplateShellRoiNode(roiNode):
            rejectedRoiWarning = _(
                "Ignored a non-Step 5B ROI. Create the automatic shell bounds "
                "ROI with the Step 5B button; target-bounds and unrelated ROIs "
                "cannot be used for shell generation."
            )
            logging.warning(
                "Cleared invalid Step 5B ROI reference to %s (%s)",
                roiNode.GetID(),
                roiNode.GetName() or "unnamed ROI",
            )
            self._updatingTemplateGuideUI = True
            try:
                self._parameterNode.templateShellRoi = None
                self.ui.templateShellRoiSelector.setCurrentNode(None)
            finally:
                self._updatingTemplateGuideUI = False
            roiNode = None
        elif roiNode:
            self.logic.enforceWorkflowRoiNonInteractive(roiNode)
        self.logic.refreshWorkflowLineageColors()
        self.logic.refreshWorkflowNodeStepTags()
        lineageNode = self._lineageSourceNode(
            (
                supportModel,
                visibleSupportModel,
                insertionDirection,
                undercutModel,
                blockoutModel,
                patientContactShell,
                trajectoryNode,
                roiNode,
                shellModel,
                sleeveModel,
            ),
            self._parameterNode.targetToothSegmentId,
        )
        self._updateLineageBadge(
            self.ui.templateGuideLineageLabel,
            lineageNode,
            _("Step 4A → Step 4B → Step 5A → Step 5B"),
            _(
                "Inherited lineage: waiting for a colored Step 5A/Step 4A input."
            ),
        )
        for selector, acceptsNode in (
            (
                self.ui.templateInsertionDirectionSelector,
                self.logic.isTemplateInsertionDirectionNode,
            ),
            (
                self.ui.templateUndercutSurfaceModelSelector,
                self.logic.isTemplateUndercutSurfaceModelNode,
            ),
            (
                self.ui.templateUndercutBlockoutModelSelector,
                self.logic.isTemplateUndercutBlockoutModelNode,
            ),
            (
                self.ui.patientContactShellModelSelector,
                self.logic.isPatientContactShellModelNode,
            ),
            (
                self.ui.templateShellRoiSelector,
                self.logic.isTemplateShellRoiNode,
            ),
            (
                self.ui.researchTemplateShellModelSelector,
                self.logic.isResearchTemplateModelNode,
            ),
            (
                self.ui.researchTemplateSleeveModelSelector,
                self.logic.isResearchTemplateModelNode,
            ),
        ):
            self._updateNodeSelectorLineageSwatches(
                selector,
                acceptsNode,
            )

        selectorNodes = (
            (self.ui.templateInsertionDirectionSelector, insertionDirection),
            (self.ui.templateUndercutSurfaceModelSelector, undercutModel),
            (self.ui.templateUndercutBlockoutModelSelector, blockoutModel),
            (self.ui.patientContactShellModelSelector, patientContactShell),
        )
        if any(selector.currentNode() is not node for selector, node in selectorNodes):
            self._updatingTemplateGuideUI = True
            try:
                for selector, node in selectorNodes:
                    selector.setCurrentNode(node)
            finally:
                self._updatingTemplateGuideUI = False
        self.ui.patientContactShellSourceValueLabel.text = (
            visibleSupportModel.GetName()
            if self.logic.isVisibleTemplateSupportModelNode(visibleSupportModel)
            else _("--")
        )
        visibleCurrent = False
        try:
            visibleCurrent = (
                self.logic.getVisibleTemplateSupportModelSummary(
                    visibleSupportModel
                )["geometryState"]
                == "Current"
            )
        except (RuntimeError, ValueError, json.JSONDecodeError):
            pass
        self.ui.createTemplateInsertionDirectionButton.enabled = visibleCurrent
        self.ui.deleteTemplateInsertionDirectionButton.enabled = bool(
            self.logic.isTemplateInsertionDirectionNode(insertionDirection)
            or self.logic.isTemplateUndercutSurfaceModelNode(undercutModel)
            or self.logic.isTemplateUndercutBlockoutModelNode(blockoutModel)
        )

        directionSummary = None
        directionError = ""
        try:
            directionSummary = self.logic.getTemplateInsertionDirectionSummary(
                insertionDirection
            )
            if directionSummary["sourceSurface"] is not visibleSupportModel:
                raise ValueError(
                    _("The insertion direction belongs to another support surface.")
                )
            visibleSummaryForDirection = (
                self.logic.getVisibleTemplateSupportModelSummary(
                    visibleSupportModel
                )
            )
            if (
                directionSummary["sourceTrajectory"]
                and directionSummary["sourceTrajectory"]
                is not visibleSummaryForDirection["directionTrajectory"]
            ):
                raise ValueError(
                    _("The insertion direction belongs to another trajectory.")
                )
        except (RuntimeError, ValueError) as exc:
            directionError = str(exc)

        undercutParameters = {
            "angleToleranceDeg": float(
                self._parameterNode.templateUndercutAngleToleranceDeg
            ),
            "interproximalReliefMm": float(
                self._parameterNode.templateInterproximalReliefMm
            ),
            "processingResolutionMm": float(
                self._parameterNode.templateSamplingSpacingMm
            ),
            "paddingMm": max(
                5.0,
                4.0 * float(self._parameterNode.templateSamplingSpacingMm),
            ),
        }
        undercutParametersJson = json.dumps(
            undercutParameters,
            sort_keys=True,
            separators=(",", ":"),
        )
        undercutSummary = None
        blockoutSummary = None
        undercutOutputError = ""
        for modelNode, role in (
            (undercutModel, "TemplateUndercutSurface"),
            (blockoutModel, "TemplateUndercutBlockout"),
        ):
            if not modelNode:
                continue
            try:
                summary = self.logic.getTemplateUndercutOutputSummary(
                    modelNode,
                    role,
                )
                if role == "TemplateUndercutSurface":
                    undercutSummary = summary
                else:
                    blockoutSummary = summary
            except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
                undercutOutputError = str(exc)
        if directionSummary and (undercutSummary or blockoutSummary):
            staleReason = ""
            for summary in (undercutSummary, blockoutSummary):
                if not summary or summary["geometryState"] != "Current":
                    continue
                if summary["sourceModel"] is not supportModel:
                    staleReason = _("The full support anatomy changed.")
                elif summary["visibleSupport"] is not visibleSupportModel:
                    staleReason = _("The visible support surface changed.")
                elif summary["insertionDirection"] is not insertionDirection:
                    staleReason = _("The insertion direction node changed.")
                elif summary["parametersJson"] != undercutParametersJson:
                    staleReason = _("Undercut tolerance or processing resolution changed.")
                elif summary["insertionGeometryJson"] != directionSummary["geometryJson"]:
                    staleReason = _("The insertion direction points changed.")
                elif summary["sourceModelUpdatedUtc"] != (
                    supportModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
                ):
                    staleReason = _("The full support anatomy was regenerated.")
                elif summary["visibleSupportUpdatedUtc"] != (
                    visibleSupportModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
                ):
                    staleReason = _("The visible support surface was regenerated.")
                if staleReason:
                    break
            if staleReason:
                self.logic.markTemplateUndercutOutputsStale(
                    undercutModel,
                    blockoutModel,
                    staleReason,
                )
                if undercutSummary:
                    undercutSummary = self.logic.getTemplateUndercutOutputSummary(
                        undercutModel,
                        "TemplateUndercutSurface",
                    )
                if blockoutSummary:
                    blockoutSummary = self.logic.getTemplateUndercutOutputSummary(
                        blockoutModel,
                        "TemplateUndercutBlockout",
                    )
        blockoutCurrent = bool(
            blockoutSummary and blockoutSummary["geometryState"] == "Current"
        )
        self.ui.analyzeTemplateUndercutsButton.enabled = bool(
            visibleCurrent and directionSummary and not undercutOutputError
        )

        patientParameters = None
        patientInputError = ""
        try:
            patientParameters = self.logic.patientContactShellParameters(
                self._parameterNode.templateShellClearanceMm,
                self._parameterNode.templateShellThicknessMm,
                self._parameterNode.templateSamplingSpacingMm,
                self._parameterNode.templateBlockoutSafetyMm,
                self._parameterNode.templateShellVoxelClosingMm,
            )
            self.logic.validatePatientContactShellInputs(
                supportModel,
                visibleSupportModel,
                insertionDirection,
                blockoutModel,
                patientParameters,
            )
        except (RuntimeError, ValueError) as exc:
            patientInputError = str(exc)

        patientSummary = None
        patientOutputError = ""
        if patientContactShell:
            try:
                patientSummary = self.logic.getPatientContactShellSummary(
                    patientContactShell
                )
            except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
                patientOutputError = str(exc)
        if patientSummary and patientSummary["geometryState"] == "Current":
            staleReason = ""
            currentParametersJson = (
                json.dumps(
                    patientParameters,
                    sort_keys=True,
                    separators=(",", ":"),
                )
                if patientParameters
                else ""
            )
            if patientInputError:
                staleReason = patientInputError
            elif patientSummary["sourceModel"] is not supportModel:
                staleReason = _("The full support-anatomy model changed.")
            elif patientSummary["visibleSupport"] is not visibleSupportModel:
                staleReason = _("The visible support surface changed.")
            elif patientSummary["insertionDirection"] is not insertionDirection:
                staleReason = _("The insertion direction changed.")
            elif patientSummary["blockoutModel"] is not blockoutModel:
                staleReason = _("The directional blockout changed.")
            elif patientSummary["parametersJson"] != currentParametersJson:
                staleReason = _("Shell fit, blockout, smoothing, or resolution changed.")
            elif patientSummary["sourceModelUpdatedUtc"] != (
                supportModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            ):
                staleReason = _("The full support anatomy was regenerated.")
            elif patientSummary["visibleSupportUpdatedUtc"] != (
                visibleSupportModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            ):
                staleReason = _("The visible support surface was regenerated.")
            elif patientSummary["insertionGeometryJson"] != directionSummary["geometryJson"]:
                staleReason = _("The insertion direction points changed.")
            elif patientSummary["blockoutUpdatedUtc"] != (
                blockoutModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            ):
                staleReason = _("The directional blockout was regenerated.")
            if staleReason:
                self.logic.markPatientContactShellStale(
                    patientContactShell,
                    staleReason,
                )
                patientSummary = self.logic.getPatientContactShellSummary(
                    patientContactShell
                )

        self.ui.generatePatientContactShellButton.enabled = bool(
            not patientInputError and not patientOutputError
        )
        self.ui.deletePatientContactShellButton.enabled = bool(
            self.logic.isPatientContactShellModelNode(patientContactShell)
        )
        if patientOutputError:
            patientMessage, patientStyle = patientOutputError, "color: #b00020;"
        elif undercutOutputError:
            patientMessage, patientStyle = undercutOutputError, "color: #b00020;"
        elif not visibleCurrent:
            patientMessage, patientStyle = (
                _("Generate a current visible support preview in Step 5A first."),
                "color: #b36b00;",
            )
        elif directionError:
            patientMessage, patientStyle = directionError, "color: #b36b00;"
        elif not blockoutCurrent:
            if blockoutSummary:
                patientMessage = _("Directional blockout is stale: %1").replace(
                    "%1",
                    blockoutSummary["staleReason"] or _("regeneration required"),
                )
            else:
                patientMessage = _(
                    "Insertion direction is ready. Analyze undercuts to create the "
                    "directional blockout."
                )
            patientStyle = "color: #1f5f99;"
        elif patientInputError:
            patientMessage, patientStyle = patientInputError, "color: #b36b00;"
        elif patientSummary and patientSummary["geometryState"] == "Current":
            patientMessage = (
                _(
                    "Undercut-aware patient-contact shell is current (%1 triangles, "
                    "%2 component(s))."
                )
                .replace(
                    "%1",
                    str(patientSummary["metrics"].get("triangleCount", "--")),
                )
                .replace(
                    "%2",
                    str(patientSummary["metrics"].get("surfaceRegionCount", "--")),
                )
            )
            if patientSummary["warnings"]:
                patientMessage += " " + " ".join(patientSummary["warnings"])
                patientStyle = "color: #b36b00;"
            else:
                patientStyle = "color: #207227;"
        elif patientSummary:
            patientMessage = _("Patient-contact shell is stale: %1").replace(
                "%1",
                patientSummary["staleReason"] or _("regeneration required"),
            )
            patientStyle = "color: #b36b00;"
        else:
            patientMessage = _(
                "Directional blockout and fit parameters are current. Generate the "
                "undercut-aware patient-contact shell."
            )
            patientStyle = "color: #1f5f99;"
        self.ui.patientContactShellStatusLabel.text = patientMessage
        self.ui.patientContactShellStatusLabel.styleSheet = patientStyle
        self._updateFinalPrintableTemplateControls(patientContactShell, supportModel)
        self._updateTemplateGuideVisibilityControls()
        # The remaining research-shell/ROI/sleeve controller below is retained
        # only so older scenes can still deserialize their derived nodes.  It
        # is no longer part of, or executed by, the active 5B workflow.
        return
        self.ui.createTemplateShellRoiButton.enabled = bool(
            supportModel
            and self.logic.isDraftTemplateSupportModelNode(supportModel)
        )
        self.ui.deleteTemplateShellRoiButton.enabled = bool(
            self.logic.isTemplateShellRoiNode(roiNode)
            and slicer.mrmlScene.IsNodePresent(roiNode)
        )

        inputError = ""
        parameters = self._templateGuideParameters()
        normalizedParameters = None
        validatedInputs = None
        try:
            normalizedParameters = self.logic._templateGuideParameters(
                parameters["clearanceMm"],
                parameters["thicknessMm"],
                parameters["samplingSpacingMm"],
                parameters["channelDiameterMm"],
                parameters["sleeveOuterDiameterMm"],
                parameters["sleeveInnerDiameterMm"],
                parameters["sleeveHeightMm"],
            )
            validatedInputs = self.logic.validateResearchTemplateInputs(
                supportModel,
                trajectoryNode,
                roiNode,
                normalizedParameters,
            )
        except (RuntimeError, ValueError) as exc:
            inputError = str(exc)

        summaries = []
        outputError = ""
        for modelNode, role in (
            (shellModel, "ResearchTemplateShell"),
            (sleeveModel, "ResearchTemplateSleeve"),
        ):
            if not modelNode:
                summaries.append(None)
                continue
            try:
                summaries.append(
                    self.logic.getResearchTemplateModelSummary(modelNode, role)
                )
            except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
                summaries.append(None)
                outputError = str(exc)

        shellSummary, sleeveSummary = summaries
        if (shellSummary or sleeveSummary) and not validatedInputs:
            self.logic.markResearchTemplateModelsStale(
                shellModel,
                sleeveModel,
                inputError or _("A required Step 5B input is unavailable."),
            )
            if shellSummary:
                shellSummary = self.logic.getResearchTemplateModelSummary(
                    shellModel,
                    "ResearchTemplateShell",
                )
            if sleeveSummary:
                sleeveSummary = self.logic.getResearchTemplateModelSummary(
                    sleeveModel,
                    "ResearchTemplateSleeve",
                )
        if validatedInputs and shellSummary and sleeveSummary:
            currentTrajectoryJson = json.dumps(
                {
                    "entryRas": validatedInputs["trajectorySummary"]["entryRas"],
                    "targetRas": validatedInputs["trajectorySummary"]["targetRas"],
                },
                sort_keys=True,
                separators=(",", ":"),
            )
            currentRoiJson = json.dumps(
                validatedInputs["roiBoundsRas"],
                separators=(",", ":"),
            )
            currentParametersJson = json.dumps(
                normalizedParameters,
                sort_keys=True,
                separators=(",", ":"),
            )
            sourceUpdatedUtc = supportModel.GetAttribute("DENTOBOT.UpdatedUtc") or ""
            differs = any(
                summary["sourceModel"] is not supportModel
                or summary["trajectory"] is not trajectoryNode
                or summary["roi"] is not roiNode
                or summary["parametersJson"] != currentParametersJson
                or summary["trajectoryGeometryJson"] != currentTrajectoryJson
                or summary["roiBoundsRasJson"] != currentRoiJson
                or summary["sourceModelUpdatedUtc"] != sourceUpdatedUtc
                for summary in (shellSummary, sleeveSummary)
            )
            if differs:
                self.logic.markResearchTemplateModelsStale(
                    shellModel,
                    sleeveModel,
                    _("Step 4B support draft, trajectory, ROI, or dimensions changed."),
                )
                shellSummary = self.logic.getResearchTemplateModelSummary(
                    shellModel,
                    "ResearchTemplateShell",
                )
                sleeveSummary = self.logic.getResearchTemplateModelSummary(
                    sleeveModel,
                    "ResearchTemplateSleeve",
                )

        canGenerate = bool(validatedInputs and not outputError)
        bothCurrent = bool(
            shellSummary
            and sleeveSummary
            and shellSummary["geometryState"] == "Current"
            and sleeveSummary["geometryState"] == "Current"
        )
        self.ui.generateResearchTemplateButton.enabled = canGenerate
        self.ui.deleteResearchTemplateButton.enabled = bool(
            self.logic.isResearchTemplateModelNode(shellModel)
            or self.logic.isResearchTemplateModelNode(sleeveModel)
        )

        if rejectedRoiWarning:
            message, style = rejectedRoiWarning, "color: #b00020;"
        elif outputError:
            message, style = outputError, "color: #b00020;"
        elif inputError:
            message, style = inputError, "color: #b36b00;"
        elif shellSummary and sleeveSummary and not bothCurrent:
            message, style = (
                _("Step 5B outputs are stale. Regenerate after reviewing the current inputs."),
                "color: #b36b00;",
            )
        elif bothCurrent:
            warnings = list(dict.fromkeys(shellSummary["warnings"] + sleeveSummary["warnings"]))
            if warnings:
                message = _("Research template generated with warnings: %1").replace(
                    "%1", " ".join(warnings)
                )
                style = "color: #b36b00;"
            else:
                message = (
                    _("Research shell and sleeve are current and ready for Step 5C fit and trim.")
                )
                style = "color: #207227;"
        else:
            message, style = (
                _("Inputs are ready. Generate the research shell and sleeve."),
                "color: #1f5f99;",
            )
        self.ui.templateGuideStatusLabel.text = message
        self.ui.templateGuideStatusLabel.styleSheet = style

    def onTemplateGuideInputChanged(self, *args) -> None:
        del args
        if not self._updatingTemplateGuideUI:
            self._updateTemplateGuide()
            self._updateTemplateFinalization()

    def onPatientContactShellSelectionChanged(self, modelNode) -> None:
        if self._updatingTemplateGuideUI or not self._parameterNode:
            return
        currentNode = self._parameterNode.patientContactShellModel
        if (currentNode.GetID() if currentNode else None) != (
            modelNode.GetID() if modelNode else None
        ):
            self._parameterNode.patientContactShellModel = modelNode
        self._updateTemplateGuide()

    def onTemplateInsertionDirectionSelectionChanged(self, lineNode) -> None:
        if self._updatingTemplateGuideUI or not self._parameterNode:
            return
        currentNode = self._parameterNode.templateInsertionDirection
        if (currentNode.GetID() if currentNode else None) != (
            lineNode.GetID() if lineNode else None
        ):
            self._parameterNode.templateInsertionDirection = lineNode
            self._bindTemplateInsertionDirectionNode(lineNode)
            self._invalidateTemplateUndercutDownstream(
                _("The selected template insertion direction changed."),
            )
        self._updateTemplateGuide()

    def onTemplateUndercutOutputSelectionChanged(self, *args) -> None:
        del args
        if self._updatingTemplateGuideUI or not self._parameterNode:
            return
        self._parameterNode.templateUndercutSurfaceModel = (
            self.ui.templateUndercutSurfaceModelSelector.currentNode()
        )
        self._parameterNode.templateUndercutBlockoutModel = (
            self.ui.templateUndercutBlockoutModelSelector.currentNode()
        )
        self._updateTemplateGuide()

    def onCreateTemplateInsertionDirection(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        try:
            visibleSupport = self._parameterNode.visibleTemplateSupportModel
            visibleSummary = self.logic.getVisibleTemplateSupportModelSummary(
                visibleSupport
            )
            trajectoryNode = visibleSummary["directionTrajectory"]
            lineNode = self.logic.createOrUpdateTemplateInsertionDirectionFromTrajectory(
                visibleSupport,
                trajectoryNode,
                reverseDirection=visibleSummary["directionReversed"],
                lineNode=self._parameterNode.templateInsertionDirection,
            )
            visibleSupport.SetNodeReferenceID(
                self.logic.TEMPLATE_VISIBLE_SUPPORT_INSERTION_DIRECTION_REFERENCE_ROLE,
                lineNode.GetID(),
            )
            self._parameterNode.templateInsertionDirection = lineNode
            self._bindTemplateInsertionDirectionNode(lineNode)
            self._invalidateTemplateUndercutDownstream(
                _("The trajectory-derived template insertion direction was refreshed."),
            )
            self._updateTemplateGuide()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onCreateManualTemplateInsertionDirection(self) -> None:
        """Legacy developer fallback retained outside the routine UI path."""

        if not self._parameterNode or not self.logic:
            return
        try:
            lineNode = self.logic.createOrResetTemplateInsertionDirection(
                self._parameterNode.visibleTemplateSupportModel,
                self._parameterNode.templateInsertionDirection,
            )
            self._parameterNode.templateInsertionDirection = lineNode
            self._bindTemplateInsertionDirectionNode(lineNode)
            self._invalidateTemplateUndercutDownstream(
                _("The manual template insertion direction was reset."),
            )
            self.logic.startLinePlacement(lineNode)
            self._updateTemplateGuide()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def onDeleteTemplateInsertionDirection(self) -> None:
        if not self._parameterNode or not self.logic:
            return
        if not slicer.util.confirmYesNoDisplay(
            _(
                "Delete the insertion direction, undercut preview, and directional "
                "blockout? The patient-contact shell will also be deleted because it "
                "depends on this blockout. Visible support anatomy is preserved."
            ),
            windowTitle=_("Delete insertion and undercut workflow"),
        ):
            return
        try:
            if self.logic.isPatientContactShellModelNode(
                self._parameterNode.patientContactShellModel
            ):
                self._deleteFinalPrintableTemplateCascade()
                self.logic.deletePatientContactShell(
                    self._parameterNode.patientContactShellModel
                )
            removals = self.logic.deleteTemplateUndercutWorkflow(
                self._parameterNode.templateInsertionDirection,
                self._parameterNode.templateUndercutSurfaceModel,
                self._parameterNode.templateUndercutBlockoutModel,
            )
            self._bindTemplateInsertionDirectionNode(None)
            logging.info(
                "Deleted template insertion/undercut subtree containing %d nodes",
                len(removals),
            )
            self._updateTemplateGuide()
        except (RuntimeError, ValueError) as exc:
            slicer.util.errorDisplay(str(exc))

    def _createOrUpdateTemplateUndercuts(self):
        if not self._parameterNode or not self.logic:
            raise RuntimeError(_("DENTOWorkflow is not ready."))
        undercutModel, blockoutModel, details = (
            self.logic.createOrUpdateTemplateUndercutAnalysis(
                self._parameterNode.draftTemplateSupportModel,
                self._parameterNode.visibleTemplateSupportModel,
                self._parameterNode.templateInsertionDirection,
                angleToleranceDeg=(
                    self._parameterNode.templateUndercutAngleToleranceDeg
                ),
                interproximalReliefMm=(
                    self._parameterNode.templateInterproximalReliefMm
                ),
                samplingSpacingMm=self._parameterNode.templateSamplingSpacingMm,
                undercutModel=self._parameterNode.templateUndercutSurfaceModel,
                blockoutModel=self._parameterNode.templateUndercutBlockoutModel,
            )
        )
        self._parameterNode.templateUndercutSurfaceModel = undercutModel
        self._parameterNode.templateUndercutBlockoutModel = blockoutModel
        self.logic.markPatientContactShellStale(
            self._parameterNode.patientContactShellModel,
            _("The directional undercut blockout was regenerated."),
        )
        logging.info(
            "Updated directional blockout %s from %d retentive surface cells",
            blockoutModel.GetID(),
            details["undercut"]["undercutTriangleCount"],
        )
        self._updateTemplateGuide()
        return undercutModel, blockoutModel, details

